// generated by tools/build_verse_manifests.js from ot_english.js — Dual-view English for the chapters of ot_verses/psa.js
registerEnglish([["Psalms",1,1,"Blessed is the man who does not walk in the counsel of the wicked, nor stands in the way of sinners, nor sits in the seat of scorners."],["Psalms",1,2,"But his delight is in the law of the Lord; and in his law he meditates day and night."],["Psalms",1,3,"And he shall be like a tree planted by streams of water, that brings forth its fruit in its season; its leaf also shall not wither; and in whatever he does he shall prosper."],["Psalms",1,4,"Not so the wicked: but they are like the chaff which the wind drives away."],["Psalms",1,5,"Therefore the wicked shall not stand in the judgment, nor sinners in the congregation of the righteous."],["Psalms",1,6,"For the Lord knows the way of the righteous: but the way of the wicked shall perish."],["Psalms",2,1,"Why are the nations in uproar, and the people mutter a vain thing?"],["Psalms",2,2,"The kings of the earth set themselves, and the rulers take counsel together, against the Lord, and against his anointed, saying,"],["Psalms",2,3,"Let us break their bonds asunder, and cast away their cords from us."],["Psalms",2,4,"He who sits in the heavens laughs: the Lord has them in derision."],["Psalms",2,5,"Then shall he speak to them in his wrath, and terrify them in his burning anger."],["Psalms",2,6,"But I have set my king upon Zion, my holy hill."],["Psalms",2,7,"I will tell of the decree: the Lord has said to me, Thou art my son; this day have I begotten thee."],["Psalms",2,8,"Ask of me, and I shall give thee nations for thy inheritance, and the uttermost parts of the earth for thy possession."],["Psalms",2,9,"Thou shalt break them with a rod of iron; thou shalt dash them in pieces like a potter's vessel."],["Psalms",2,10,"Be wise now therefore, O kings: be warned, O judges of the earth."],["Psalms",2,11,"Serve the Lord with fear, and rejoice with trembling."],["Psalms",2,12,"Worship in purity, lest he be angry, and you perish from the way, for in a little while his anger will blaze. Blessed are all who put their trust in him."],["Psalms",3,1,"A Psalm of David, when he fled from Absalom his son."],["Psalms",3,2,"Lord, how many are my enemies become! many are they who rise up against me:"],["Psalms",3,3,"many there be who say of my soul, There is no help for him in God. (Selah.)"],["Psalms",3,4,"But Thou, O Lord, art a shield for me; my glory, and the lifter up of my head."],["Psalms",3,5,"I cried to the Lord with my voice, and he heard me out of his holy hill. (Selah.)"],["Psalms",3,6,"I lie me down and sleep; I awake; for the Lord sustains me."],["Psalms",3,7,"I will not be afraid of ten thousands of people, that have set themselves against me round about."],["Psalms",3,8,"Arise, O Lord; save me, O my God: for Thou hast smitten all my enemies upon the cheek; Thou hast broken the teeth of the wicked."],["Psalms",3,9,"Salvation belongs to the Lord: Thy blessing be upon Thy people. (Selah.)"],["Psalms",4,1,"For the chief Musician on strings, A Psalm of David."],["Psalms",4,2,"Hear me when I call, O God of my righteousness: Thou hast enlarged me when I was in distress; have mercy upon me, and hear my prayer."],["Psalms",4,3,"O sons of men, how long will you turn my glory into shame? you love vanity, and seek after falsehood. (Selah.)"],["Psalms",4,4,"But know that the Lord has set apart the godly man as his own: the Lord will hear when I call to him."],["Psalms",4,5,"Tremble, and sin not: commune with your own heart upon your bed, and be still. (Selah.)"],["Psalms",4,6,"Offer the sacrifices of righteousness, and put your trust in the Lord."],["Psalms",4,7,"There are many who say, Who will show us good? Lord, lift Thou up the light of Thy countenance upon us."],["Psalms",4,8,"Thou hast put more gladness in my heart than they have whose corn and wine are increased."],["Psalms",4,9,"I will both lie down and sleep, in peace: for Thou, Lord, alone, makest me to dwell in safety."],["Psalms",5,1,"To the chief Musician for flutes, A Psalm of David."],["Psalms",5,2,"Give ear to my words, O Lord, consider my meditation."],["Psalms",5,3,"Hearken to the voice of my cry, my King, and my God: for to Thee I will pray."],["Psalms",5,4,"My voice shalt Thou hear in the morning, O Lord; in the morning I will direct my prayer to Thee; and will wait expectantly."],["Psalms",5,5,"For Thou art not a God That hast pleasure in wickedness: nor shall evil dwell with Thee."],["Psalms",5,6,"The boastful shall not stand in Thy sight: Thou hatest all workers of iniquity."],["Psalms",5,7,"Thou dost destroy them that speak falsehood: the Lord abhors the bloody and deceitful man."],["Psalms",5,8,"But as for me, I will come into Thy house in the multitude of Thy love: and in the fear of Thee I will worship towards Thy holy temple."],["Psalms",5,9,"Lead me, O Lord, in Thy righteousness because of my enemies; make Thy way straight before my face."],["Psalms",5,10,"For there is no sincerity in their mouth; in their heart is malice; their throat is an open sepulchre; they flatter with their tongue."],["Psalms",5,11,"Condemn them, O God; let them fall by their own counsels; cast them out for the multitude of their transgressions; for they have rebelled against Thee."],["Psalms",5,12,"But let all those that put their trust in Thee rejoice: let them ever shout for joy, because Thou dost defend them: and let those who love Thy name be joyful in Thee."],["Psalms",5,13,"For Thou, Lord, dost bless the righteous; Thou dost encircle him with favour as with a shield."],["Psalms",6,1,"To the chief Musician on strings upon the Sheminith, A Psalm of David."],["Psalms",6,2,"O Lord, rebuke me not in Thy anger, nor chasten me in Thy hot displeasure."],["Psalms",6,3,"Have mercy upon me, O Lord; for I am weak: O Lord, heal me; for my bones shudder;"],["Psalms",6,4,"and my soul is much affrighted. And Thou, O Lord, how long?"],["Psalms",6,5,"Return, O Lord, deliver my soul: oh save me on account of Thy steadfast love."],["Psalms",6,6,"For in death there is no remembrance of Thee: in Sheol who shall give Thee thanks?"],["Psalms",6,7,"I am weary with my groaning: all the night I make my bed to swim; I water my couch with my tears."],["Psalms",6,8,"My eye is wasted because of grief; it grows weak because of all my enemies."],["Psalms",6,9,"Depart from me, all you workers of iniquity; for the Lord has heard the voice of my weeping."],["Psalms",6,10,"The Lord has heard my supplication; the Lord receives my prayer."],["Psalms",6,11,"All my enemies will be ashamed and much affrighted: they will turn back and be confounded in a moment."],["Psalms",7,1,"A Shiggaion of David, which he sang to the Lord, concerning the words of Ethiopia the Benjamite."],["Psalms",7,2,"O Lord my God, in Thee do I put my trust: save me from all them that persecute me, and deliver me:"],["Psalms",7,3,"lest he tear my soul like a lion, rending it in pieces, while there is none to deliver."],["Psalms",7,4,"O Lord my God, if I have done this; if there be iniquity in my hands;"],["Psalms",7,5,"if I have rewarded evil to him that was at peace with me; (indeed, I have rescued him that without cause is my enemy:)"],["Psalms",7,6,"let the enemy persecute my soul, and take it; and let him tread down my life to the earth, and lay my honour in the dust. (Selah.)"],["Psalms",7,7,"Arise, O Lord, in Thy anger, lift up Thyself against the fury of my enemies: and awake for me: Thou hast commanded judgment."],["Psalms",7,8,"Let the congregation of the peoples compass Thee about: and for their sakes return Thou on high."],["Psalms",7,9,"The Lord shall judge the peoples. Judge me, O Lord, according to my righteousness, and according to my integrity that is in me."],["Psalms",7,10,"O let the wickedness of the wicked come to an end; but establish the just: for the righteous God tries the hearts and reins."],["Psalms",7,11,"My defence is of God, who saves the upright in heart."],["Psalms",7,12,"God is a righteous judge; and a God who has indignation every day."],["Psalms",7,13,"If a man does not turn, then he will whet his sword; he has bent his bow, and made it ready."],["Psalms",7,14,"He has also prepared for him the instruments of death; he makes arrows for the pursuers."],["Psalms",7,15,"Behold, he travails with iniquity, and has conceived mischief, and brings forth falsehood."],["Psalms",7,16,"He has made a pit, and has dug it out, and has fallen into the ditch which he made."],["Psalms",7,17,"His mischief shall return upon his own head, and his violent dealing shall come down upon his own pate."],["Psalms",7,18,"I will praise the Lord according to his righteousness: and will sing praise to the name of the Lord most high."],["Psalms",8,1,"To the chief Musician upon the Gittith, A Psalm of David."],["Psalms",8,2,"O Lord our Lord, how majestic is Thy name in all the earth; who hast set Thy glory above the heavens."],["Psalms",8,3,"Out of the mouth of babes and sucklings hast Thou founded strength because of Thy enemies, that Thou mightest still the enemy and the avenger."],["Psalms",8,4,"When I behold Thy heavens, the work of Thy fingers, the moon and the stars, which Thou hast ordained;"],["Psalms",8,5,"what is man, that Thou art mindful of him? and the son of man, that Thou visitest him?"],["Psalms",8,6,"Yet Thou hast made him a little lower than the angels, and Thou dost crown him with glory and honour."],["Psalms",8,7,"Thou makest him to have dominion over the works of Thy hands; Thou hast put all things under his feet:"],["Psalms",8,8,"all sheep, and oxen, and also the beasts of the field;"],["Psalms",8,9,"the birds of the sky, and the fish of the sea; whatever passes through the paths of the seas."],["Psalms",8,10,"O Lord our Lord, how majestic is Thy name in all the earth!"],["Psalms",9,1,"To the chief Musician on Muth-labben, A Psalm of David."],["Psalms",9,2,"I will praise Thee, O Lord, with my whole heart; I will relate all Thy marvellous works."],["Psalms",9,3,"I will be glad and rejoice in Thee: I will sing praise to Thy name, O Thou most High:"],["Psalms",9,4,"when my enemies are turned back, when they stumble and perish at Thy presence."],["Psalms",9,5,"For Thou hast maintained my right and my cause; Thou didst sit on the throne giving righteous judgment."],["Psalms",9,6,"Thou hast rebuked the nations, Thou hast destroyed the wicked, Thou hast blotted out their name for ever and ever."],["Psalms",9,7,"The enemies are come to an end, in perpetual ruins: for Thou hast destroyed the cities; their memorial is perished."],["Psalms",9,8,"But the Lord shall endure forever: he has prepared his throne for judgment."],["Psalms",9,9,"And he will judge the world in righteousness, he will minister judgment to the people in uprightness."],["Psalms",9,10,"The Lord also will be a stronghold for the oppressed, a refuge in times of trouble."],["Psalms",9,11,"And they that know Thy name will put their trust in Thee: for Thou, Lord, hast not forsaken those who seek Thee."],["Psalms",9,12,"Sing praises to the Lord, who dwells in Zion: declare among the peoples his doings."],["Psalms",9,13,"For he avenges blood, he remembers it: he does not forget the cry of the humble."],["Psalms",9,14,"Be gracious to me, O Lord; consider my trouble which I suffer from those who hate me, Thou that liftest me up from the gates of death:"],["Psalms",9,15,"that I may relate all Thy praise in the gates of the daughter of Zion. I will rejoice in Thy salvation."],["Psalms",9,16,"The nations are sunk down in the pit that they have made: in the net which they hid is their own foot taken."],["Psalms",9,17,"The Lord is known by the judgment which he executes: the wicked is snared in the work of his own hands. (A Higgaion. Selah.)"],["Psalms",9,18,"The wicked shall be turned back to Sheol, all the nations that forget God."],["Psalms",9,19,"For the needy shall not always be forgotten: the expectation of the poor shall not perish forever."],["Psalms",9,20,"Arise, O Lord; let man not prevail: let the nations be judged in Thy sight."],["Psalms",9,21,"Put them in fear, O Lord: the nations will then know themselves to be but men. (Selah.)"],["Psalms",10,1,"Why standest Thou afar off, O Lord? why hidest Thou Thyself in times of trouble?"],["Psalms",10,2,"The wicked in his pride hotly pursues the poor: let them be taken in the devices that they have imagined."],["Psalms",10,3,"For the wicked boasts of his heart's desire, and the greedy wretch curses and renounces the Lord."],["Psalms",10,4,"The wicked, through the pride of his countenance thinks, He will not seek out: all his thoughts are, God is not."],["Psalms",10,5,"His ways are always strong; thy judgments are far above out of his sight: as for all his enemies, he hisses at them."],["Psalms",10,6,"He says in his heart, I shall not be moved: for I shall never be in adversity."],["Psalms",10,7,"His mouth is full of cursing and deceit and fraud: under his tongue is mischief and iniquity."],["Psalms",10,8,"He sits in the lurking places of the villages: in the secret places he murders the innocent: his eyes stealthily watch for the helpless."],["Psalms",10,9,"He lies in wait secretly like a lion in his den: he lies in wait to catch the poor: he catches the poor, when he draws him into his net."],["Psalms",10,10,"The helpless collapse: they bow down, and fall into his power."],["Psalms",10,11,"He says in his heart, God has forgotten: he hides his face; he will never see it."],["Psalms",10,12,"Arise, O Lord; O God, lift up Thy hand: forget not the humble."],["Psalms",10,13,"Why does the wicked man renounce God? he says in his heart, Thou wilt not avenge."],["Psalms",10,14,"Thou hast seen it; for Thou beholdest mischief and spite, to requite it with Thy hand: the helpless man commits himself to Thee; Thou art the helper of the fatherless."],["Psalms",10,15,"Break Thou the arm of the wicked and the evil man: seek out his wickedness till Thou find none left."],["Psalms",10,16,"The Lord is King for ever and ever: the nations are perished out of his land."],["Psalms",10,17,"Lord, Thou hast heard the desire of the humble: Thou wilt strengthen their heart, Thou wilt cause Thy ear to hear:"],["Psalms",10,18,"to judge the fatherless and the oppressed, so that none shall any longer terrify innocent men from the earth."],["Psalms",11,1,"To the chief Musician, of David. In the Lord I put my trust: how can you say to my soul, Flee like a bird to your mountain?"],["Psalms",11,2,"For, lo, the wicked bend the bow, they make ready their arrow upon the string, that they may shoot in darkness at the upright in heart."],["Psalms",11,3,"For when the foundations are destroyed, what can the righteous do?"],["Psalms",11,4,"The Lord in his holy temple, the Lord whose throne is in heaven, whose eyes behold, whose eyelids try, the children of men:"],["Psalms",11,5,"the Lord tries the righteous: but the wicked and him who loves violence his soul hates."],["Psalms",11,6,"Upon the wicked he shall rain coals, fire and brimstone, and a scorching wind shall be the portion of their cup."],["Psalms",11,7,"For the Lord is righteous, he loves righteousness; the upright shall behold his face."],["Psalms",12,1,"To the chief Musician upon the Sheminith, A Psalm of David."],["Psalms",12,2,"Help, Lord; for the godly man ceases; for the faithful fail from among the children of men."],["Psalms",12,3,"They speak vanity every one with his fellow: with flattering lips and with a double heart they speak."],["Psalms",12,4,"May the Lord cut off all flattering lips, the tongue that speaks proud things:"],["Psalms",12,5,"who have said, With our tongue we will prevail; our lips are our own: who is lord over us?"],["Psalms",12,6,"For the violence done to the poor, for the sighing of the needy, now will I arise, says the Lord; I will set him in safety at whom they hiss."],["Psalms",12,7,"The words of the Lord are pure words: silver refined in a furnace upon the ground, purified seven times."],["Psalms",12,8,"Thou shalt keep them, O Lord, Thou shalt preserve them from this generation forever."],["Psalms",12,9,"The wicked walk on every side, when vileness is exalted among the children of men."],["Psalms",13,1,"To the chief Musician, A Psalm of David."],["Psalms",13,2,"How long wilt Thou forget me O Lord? forever? how long wilt Thou hide Thy face from me?"],["Psalms",13,3,"How long shall I take counsel in my soul, having sorrow in my heart daily? how long shall my enemy be exalted over me?"],["Psalms",13,4,"Look, and hear me, O Lord my God: lighten my eyes, lest I sleep the sleep of death;"],["Psalms",13,5,"lest my enemy say, I have prevailed against him; and those who trouble me rejoice when I am moved."],["Psalms",13,6,"But I have trusted in Thy mercy; my heart shall rejoice in Thy salvation. I will sing to the Lord, because he has dealt bountifully with me."],["Psalms",14,1,"To the chief Musician, of David. The fool has said in his heart, There is no God. They are corrupt, they have done abominable works, there is none that does good."],["Psalms",14,2,"The Lord looked down from heaven upon the children of men, to see if there were any that understood, and sought God."],["Psalms",14,3,"They are all gone aside, they are all together become filthy: there is none that does good, no, not one."],["Psalms",14,4,"Have all the workers of iniquity no knowledge? who eat up my people as they eat bread, and call not upon the Lord."],["Psalms",14,5,"There were they in great fear: for God is in the generation of the righteous."],["Psalms",14,6,"You shame the counsel of the poor, because the Lord is his refuge."],["Psalms",14,7,"Oh that the salvation of Israel were come out of Zion! when the Lord brings back the captivity of his people, Jacob shall rejoice, and Israel shall be glad."],["Psalms",15,1,"A Psalm of David. Lord, who shall abide in Thy tent? who shall dwell in Thy holy hill?"],["Psalms",15,2,"He that walks uprightly, and acts justly, and speaks the truth in his heart."],["Psalms",15,3,"He that does not slander with his tongue, nor does evil to his fellow, nor takes up a reproach against his neighbour."],["Psalms",15,4,"In whose eyes a vile person is despised; but he honours them that fear the Lord. He that swears to his own hurt, and changes not."],["Psalms",15,5,"He that does not put out his money on interest, nor takes a bribe against the innocent. He that does these things shall never be moved."],["Psalms",16,1,"A Michtam of David. Preserve me, O God: for in Thee do I put my trust."],["Psalms",16,2,"I have said to the Lord, Thou art my Lord: I have no good apart from Thee;"],["Psalms",16,3,"and to the saints that are on the earth, They are the excellent, in whom is all my delight."],["Psalms",16,4,"Their sorrows shall be multiplied that hasten after another god: their drink offerings of blood will I not offer, nor take up their names upon my lips."],["Psalms",16,5,"The Lord is the portion of my inheritance and of my cup: Thou maintainest my lot."],["Psalms",16,6,"The lines are fallen to me in pleasant places; yea, I have a goodly heritage."],["Psalms",16,7,"I bless the Lord, who gives me counsel: my reins also admonish me in the night seasons."],["Psalms",16,8,"I have set the Lord always before me: surely he is at my right hand, I shall not be moved."],["Psalms",16,9,"Therefore my heart is glad, and my glory rejoices: my flesh also dwells secure."],["Psalms",16,10,"For Thou wilt not abandon my soul to Sheol; nor wilt Thou suffer thy holy one to see the pit."],["Psalms",16,11,"Thou wilt make known to me the path of life: in Thy presence is fulness of joy; at Thy right hand are pleasures for evermore."],["Psalms",17,1,"A Prayer of David. Hear the right, O Lord, attend to my cry, give ear to my prayer, from lips without deceit."],["Psalms",17,2,"Let my sentence come forth from Thy presence; let Thy eyes behold the right."],["Psalms",17,3,"Thou hast proved my heart; Thou hast visited it in the night: Thou hast tried me, but Thou findest nothing; let no presumptuous thought pass my lips."],["Psalms",17,4,"Concerning the works of men, by the word of Thy lips I have kept me from the paths of the violent."],["Psalms",17,5,"My steps have held fast to Thy paths; my feet have not slipped."],["Psalms",17,6,"I have called upon Thee, for Thou wilt hear me, O God: incline Thy ear to me, and hear my speech."],["Psalms",17,7,"Show marvellously Thy steadfast love, saving with Thy right hand from their enemies those who seek refuge."],["Psalms",17,8,"Keep me as the apple of the eye, hide me under the shadow of Thy wings,"],["Psalms",17,9,"from the wicked that oppress me, from my deadly enemies, who compass me about."],["Psalms",17,10,"They are inclosed in their own fat: with their mouth they speak proudly."],["Psalms",17,11,"They dog our footsteps; they surround us: they set their eyes to tread us down to the earth;"],["Psalms",17,12,"he is like a lion greedy for its prey, and as it were a young lion lurking in secret places."],["Psalms",17,13,"Arise, O Lord, confront him, cast him down: deliver my soul from the wicked, by Thy sword:"],["Psalms",17,14,"from men, by Thy hand, O Lord, from men whose portion in life is of the world, and whose belly Thou fillest with Thy treasure: who have children in plenty, and who leave their abundance to their babes."],["Psalms",17,15,"As for me, I will behold Thy face in righteousness: I shall be satisfied, when I awake, with beholding Thy likeness."],["Psalms",18,1,"To the chief Musician, of David, the servant of the Lord, who spoke to the Lord the words of this song in the day that the Lord delivered him from the hand of all his enemies, and from the hand of Saul:"],["Psalms",18,2,"and he said, I will love Thee, O Lord, my strength."],["Psalms",18,3,"The Lord is my rock, and my fortress, and my deliverer; my God, my rock, in whom I will trust; my shield, and the horn of my salvation, and my high tower."],["Psalms",18,4,"He is worthy to be praised: I will call upon the Lord: so shall I be saved from my enemies."],["Psalms",18,5,"The bonds of death encircled me, and the floods of ungodly men made me afraid."],["Psalms",18,6,"The cords of Sheol compassed me about: the snares of death took me by surprise."],["Psalms",18,7,"In my distress I called upon the Lord, and cried to my God: he heard my voice out of his temple, and my cry came before him, into his ears."],["Psalms",18,8,"Then the earth shook and trembled; and the foundations of the hills moved and were shaken, because of his anger."],["Psalms",18,9,"There went up a smoke out of his nostrils, and fire out of his mouth devoured: coals were kindled by it."],["Psalms",18,10,"He bowed the heavens also, and came down: and darkness was under his feet."],["Psalms",18,11,"And he rode upon a keruv, and did fly: he soared on the wings of the wind."],["Psalms",18,12,"He made darkness his secret place; his pavilion round about him was dark water and thick clouds of the skies."],["Psalms",18,13,"At the brightness that was before him his thick clouds passed, hail and coals of fire."],["Psalms",18,14,"The Lord also thundered in the heavens, and the Highest gave his voice; hail and coals of fire."],["Psalms",18,15,"And he sent out his arrows, and scattered them; and he shot out lightnings, and confounded them."],["Psalms",18,16,"Then the channels of waters were seen, and the foundations of the world were laid bare, at Thy rebuke, O Lord, at the blast of the breath of Thy nostrils."],["Psalms",18,17,"He sent from above, he took me, he drew me out of many waters."],["Psalms",18,18,"He delivered me from my strong enemy, and from those who hated me: for they were too strong for me."],["Psalms",18,19,"They surprised me in the day of my calamity: but the Lord was my stay."],["Psalms",18,20,"He brought me forth also into a large place; he delivered me, because he delighted in me."],["Psalms",18,21,"The Lord rewards me according to my righteousness; according to the cleanness of my hands he recompenses me."],["Psalms",18,22,"For I have kept the ways of the Lord, and have not wickedly departed from my God."],["Psalms",18,23,"For all his judgments were before me, and I did not put away his statutes from me."],["Psalms",18,24,"I was also upright before him, and I kept myself from my iniquity."],["Psalms",18,25,"Therefore the Lord recompenses me according to my righteousness, according to the cleanness of my hands in his eyesight."],["Psalms",18,26,"With the merciful Thou wilt show Thyself merciful; with an upright man Thou wilt show Thyself upright;"],["Psalms",18,27,"with the pure Thou wilt show Thyself pure; and with the perverse Thou wilt show Thyself subtle."],["Psalms",18,28,"For Thou wilt save the afflicted people; but wilt bring down high looks."],["Psalms",18,29,"For Thou wilt light my candle: the Lord my God will enlighten my darkness."],["Psalms",18,30,"For by Thee I run through a troop; and by my God I leap over a wall."],["Psalms",18,31,"As for God, his way is perfect: the word of the Lord is tried: he is a shield to all those who trust in him."],["Psalms",18,32,"For who is God save the Lord? or who is a rock save our God?"],["Psalms",18,33,"It is God that girds me with strength, and makes my way perfect."],["Psalms",18,34,"He makes my feet like hinds' feet, and sets me upon my heights."],["Psalms",18,35,"He teaches my hands to war, so that a bow of brass is bent in my arms."],["Psalms",18,36,"Thou hast also given me the shield of Thy salvation: and Thy right hand has supported me and Thy condescension has made me great."],["Psalms",18,37,"Thou hast enlarged my steps under me, that my feet did not slip."],["Psalms",18,38,"I have pursued my enemies, and overtaken them: neither did I turn back till they were consumed."],["Psalms",18,39,"I have crushed them so that they were not able to rise: they are fallen under my feet."],["Psalms",18,40,"For Thou hast girded me with strength to the battle: Thou hast subdued under me those who rose up against me."],["Psalms",18,41,"Thou hast also made my enemies turn their backs on me; that I might destroy those who hate me."],["Psalms",18,42,"They cried, but there was none to save them: to the Lord, but he answered them not."],["Psalms",18,43,"Then did I beat them small like the dust before the wind: I did cast them out like the dirt in the streets."],["Psalms",18,44,"Thou deliverest me from the strivings of the people; Thou makest me the head of nations: a people whom I have not known shall serve me."],["Psalms",18,45,"As soon as they hear of me, they shall obey me: the strangers shall submit themselves to me."],["Psalms",18,46,"The strangers shall fade away, and come trembling out of their close places."],["Psalms",18,47,"The Lord lives; and blessed is my rock; and let the God of my salvation be exalted."],["Psalms",18,48,"It is God who avenges me, and has subdued peoples under me."],["Psalms",18,49,"He delivers me from my enemies: indeed, thou liftest me up above those who rise up against me: Thou deliverest me from the violent man."],["Psalms",18,50,"Therefore will I give thanks to Thee, O Lord, among the nations, and sing praises to Thy name."],["Psalms",18,51,"Great deliverance he gives to his king; and shows steadfast love to his anointed, to David, and to his seed for evermore."],["Psalms",19,1,"To the chief Musician, A Psalm of David."],["Psalms",19,2,"The heavens declare the glory of God; and the firmament proclaims his handiwork."],["Psalms",19,3,"Day to day utters speech, and night to night expresses knowledge."],["Psalms",19,4,"There is no speech nor are there words; their voice is not heard."],["Psalms",19,5,"Their line is gone out through all the earth, and their words to the end of the world. In them he has set a tent for the sun,"],["Psalms",19,6,"which is like a bridegroom coming out of his chamber, and rejoices like a strong man to run a race."],["Psalms",19,7,"His going forth is from the end of the heaven, and his circuit to the ends of it: and there is nothing hid from his heat."],["Psalms",19,8,"The law of the Lord is perfect, restoring the soul: the testimony of the Lord is sure, making wise the simple."],["Psalms",19,9,"The statutes of the Lord are right, rejoicing the heart: the commandment of the Lord is pure, enlightening the eyes."],["Psalms",19,10,"The fear of the Lord is clean, enduring forever: the judgments of the Lord are true and are righteous altogether."],["Psalms",19,11,"More to be desired are they than gold, even much fine gold: sweeter also than honey and the honeycomb."],["Psalms",19,12,"Moreover by them is Thy servant enlightened: and in keeping of them there is great reward."],["Psalms",19,13,"Who can discern errors? cleanse Thou me from secret faults."],["Psalms",19,14,"Keep back Thy servant also from presumptuous sins; let them not have dominion over me: then shall I be upright, and I shall be clear of much transgression."],["Psalms",19,15,"Let the words of my mouth, and the meditation of my heart, be acceptable in Thy sight, O Lord, my rock, and my redeemer."],["Psalms",20,1,"To the chief Musician, A Psalm for David."],["Psalms",20,2,"May the Lord hear thee in the day of trouble; may the name of the God of Jacob defend thee!"],["Psalms",20,3,"May he send thee help from the sanctuary, and strengthen thee out of Zion!"],["Psalms",20,4,"May he remember all thy offerings, and accept with favour thy burnt offering! (Selah.)"],["Psalms",20,5,"May he grant thee thy heart's desire, and fulfil all thy counsel!"],["Psalms",20,6,"May we rejoice in Thy salvation, and in the name of our God set up our banner! Let the Lord fulfil all thy petitions!"],["Psalms",20,7,"Now I know that the Lord saves his anointed; that he answers him from his holy heaven with the saving strength of his right hand."],["Psalms",20,8,"Some trust in chariots, and some in horses: but we will make mention of the name of the Lord our God."],["Psalms",20,9,"They are bowed down and fallen: but we are risen, and stand upright."],["Psalms",20,10,"Save, Lord; O King, who hears us on the day when we call."],["Psalms",21,1,"To the chief Musicians, A Psalm of David."],["Psalms",21,2,"The king joys in Thy strength, O Lord; and in Thy salvation how greatly he rejoices!"],["Psalms",21,3,"Thou hast given him his heart's desire, and hast not withheld the request of his lips. (Selah.)"],["Psalms",21,4,"For Thou dost meet him with the blessings of goodness: Thou settest a crown of pure gold on his head."],["Psalms",21,5,"He asked life of Thee, and Thou didst give it him; length of days for ever and ever."],["Psalms",21,6,"His glory is great in Thy salvation: honour and majesty Thou dost lay upon him."],["Psalms",21,7,"For Thou dost make him most blessed forever: Thou makest him exceeding glad with Thy countenance."],["Psalms",21,8,"For the king trusts in the Lord, and through the steadfast love of the most High he shall not be moved."],["Psalms",21,9,"Thy hand shall find out all Thy enemies: Thy right hand shall seize those that hate Thee."],["Psalms",21,10,"Thou shalt make them like a fiery oven in the time of Thy anger: the Lord shall swallow them up in his wrath, and the fire shall devour them."],["Psalms",21,11,"Their fruit shalt Thou destroy from the earth, and their seed from among the children of men."],["Psalms",21,12,"For they intended evil against Thee: they imagined a mischievous device, but they will not succeed."],["Psalms",21,13,"For Thou shalt make them turn their back; Thou shalt aim Thy bowstrings against the face of them."],["Psalms",21,14,"Be Thou exalted, Lord, in Thy own strength: we will sing and praise Thy power."],["Psalms",22,1,"To the chief Musician upon Aijeleth Shahar, A Psalm of David."],["Psalms",22,2,"My God, my God, why hast Thou forsaken me? why art Thou so far from helping me, from the words of my loud complaint?"],["Psalms",22,3,"O my God, I cry in the daytime, but Thou hearest not; and in the night season, and I have no rest."],["Psalms",22,4,"But Thou art holy, O Thou That art enthroned upon the praises of Israel."],["Psalms",22,5,"Our fathers trusted in Thee: they trusted, and Thou didst deliver them."],["Psalms",22,6,"They cried to Thee, and were delivered: they trusted in Thee, and were not confounded."],["Psalms",22,7,"But I am a worm, and no man; a reproach of men, and despised of the people."],["Psalms",22,8,"All that see me laugh me to scorn: they shoot out the lip, they shake the head,"],["Psalms",22,9,"saying, He trusts in the Lord that he will deliver him! Let him deliver him, seeing he delights in him."],["Psalms",22,10,"But Thou art he that took me out of the womb: Thou didst make me hope when I was upon my mother's breasts."],["Psalms",22,11,"I was cast upon Thee from the womb: Thou art my God from my mother's belly."],["Psalms",22,12,"Be not far from me; for trouble is near; for there is none to help."],["Psalms",22,13,"Many bulls have compassed me: strong bulls of Bashan have beset me round."],["Psalms",22,14,"They gape upon me with their mouths, like a ravening and a roaring lion."],["Psalms",22,15,"I am poured out like water, and all my bones are out of joint: my heart is become like wax; it is melted in the midst of my bowels."],["Psalms",22,16,"My strength is dried up like a potsherd; and my tongue cleaves to my jaws; and Thou layest me down in the dust of death."],["Psalms",22,17,"For dogs have compassed me: the assembly of the wicked have inclosed me: they seize my hands and my feet like a lion."],["Psalms",22,18,"I can count all my bones: they look and stare upon me."],["Psalms",22,19,"They part my garments among them, and cast lots upon my vesture."],["Psalms",22,20,"But be not Thou far from me, O Lord: O my strength, haste Thee to help me."],["Psalms",22,21,"Deliver my life from the sword; my only one from the power of the dog."],["Psalms",22,22,"Save me from the lion's mouth: for Thou hast answered me from the horns of the wild oxen."],["Psalms",22,23,"I will declare Thy name to my brethren: in the midst of the congregation I will praise Thee."],["Psalms",22,24,"You who fear the Lord, praise him; all you the seed of Jacob, glorify him; and fear him, all the seed of Israel."],["Psalms",22,25,"For he has not despised nor abhorred the affliction of the afflicted; nor has he hid his face from him; but when he cried to him, he heard."],["Psalms",22,26,"My praise shall be of Thee in the great congregation: I will pay my vows before those who fear him."],["Psalms",22,27,"The meek shall eat and be satisfied: those who seek him shall praise the Lord: may your heart forever revive!"],["Psalms",22,28,"All the ends of the world shall remember and turn to the Lord: and all the families of the nations shall worship before Thee."],["Psalms",22,29,"For the kingdom is the Lord's: and he is ruler over the nations."],["Psalms",22,30,"All the fat ones of the earth shall eat and worship: all they that go down to the dust, and he that cannot keep alive his own soul, shall bow before him."],["Psalms",22,31,"Their seed shall serve him; it shall be told of the Lord to the coming generation."],["Psalms",22,32,"They shall come, and shall declare his righteousness to a people that shall be born, that he has done this."],["Psalms",23,1,"A Psalm of David. The Lord is my shepherd; I shall not want."],["Psalms",23,2,"He makes me to lie down in green pastures: he leads me beside the still waters."],["Psalms",23,3,"He restores my soul: he leads me in the paths of righteousness for his name's sake."],["Psalms",23,4,"Even though I walk through the valley of the shadow of death, I will fear no evil: for Thou art with me; Thy rod and Thy staff they comfort me."],["Psalms",23,5,"Thou preparest a table before me in the presence of my enemies: Thou anointest my head with oil; my cup runs over."],["Psalms",23,6,"Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the Lord forever."],["Psalms",24,1,"A Psalm of David. The earth is the Lord's, and the fulness thereof; the world, and they that dwell in it."],["Psalms",24,2,"For he has founded it upon the seas, and established it upon the floods."],["Psalms",24,3,"Who shall ascend into the mountain of the Lord? or who shall stand in his holy place?"],["Psalms",24,4,"He that has clean hands, and a pure heart; who has not taken my name in vain, nor sworn deceitfully."],["Psalms",24,5,"He shall receive a blessing from the Lord, and righteousness from the God of his salvation."],["Psalms",24,6,"This is Jacob, the generation of those who seek him, that seek Thy face. (Selah.)"],["Psalms",24,7,"Lift up your heads, O you gates; and be lifted up, you everlasting doors; and the King of glory shall come in."],["Psalms",24,8,"Who is this King of glory? The Lord strong and mighty, the Lord mighty in battle."],["Psalms",24,9,"Lift up your heads, O you gates; and lift them up, you everlasting doors; that the King of glory may come in."],["Psalms",24,10,"Who is this King of glory? The Lord of hosts, he is the King of glory. (Selah.)"],["Psalms",25,1,"Of David. To Thee, O Lord, do I lift up my soul."],["Psalms",25,2,"O my God, I trust in Thee: let me not be ashamed, let not my enemies triumph over me."],["Psalms",25,3,"Moreover let none that wait on Thee be ashamed: let them be ashamed who betray without cause."],["Psalms",25,4,"Make me know Thy ways, O Lord; teach me Thy paths."],["Psalms",25,5,"Lead me in Thy truth, and teach me: for Thou art the God of my salvation; for Thee do I wait all the day."],["Psalms",25,6,"Remember, O Lord, Thy tender mercies and Thy truth; for they have been from of old."],["Psalms",25,7,"Remember not the sins of my youth, nor my transgressions: according to Thy loyal love remember Thou me for Thy goodness' sake, O Lord."],["Psalms",25,8,"Good and upright is the Lord: therefore does he instruct sinners in the way."],["Psalms",25,9,"He directs the humble in justice: and he teaches the meek his way."],["Psalms",25,10,"All the paths of the Lord are mercy and truth to such as keep his covenant and his testimonies."],["Psalms",25,11,"For Thy name's sake, O Lord, pardon my iniquity; for it is great."],["Psalms",25,12,"What man is he that fears the Lord? him shall he teach in the way that he should choose."],["Psalms",25,13,"His soul shall abide in prosperity; and his seed shall inherit the earth."],["Psalms",25,14,"The counsel of the Lord is with them that fear him; and he will reveal to them his covenant."],["Psalms",25,15,"My eyes are ever towards the Lord; for he shall pluck my feet out of the net."],["Psalms",25,16,"Turn Thee to me, and be gracious to me; for I am desolate and afflicted."],["Psalms",25,17,"The troubles of my heart are enlarged: O bring me out of my distresses."],["Psalms",25,18,"Look upon my affliction and my pain; and forgive all my sins."],["Psalms",25,19,"Consider my enemies; for they are many; and they hate me with a cruel hatred."],["Psalms",25,20,"O keep my soul, and deliver me: let me not be ashamed; for I put my trust in Thee."],["Psalms",25,21,"Let integrity and uprightness preserve me; because I wait for Thee."],["Psalms",25,22,"Redeem Israel, O God, out of all his troubles."],["Psalms",26,1,"Of David. Judge me, O Lord; for I have walked in my integrity: and I have trusted in the Lord; I shall not slip."],["Psalms",26,2,"Examine me, O Lord, and prove me; try my reins and my heart."],["Psalms",26,3,"For Thy loyal love is before my eyes: and I have walked in Thy truth."],["Psalms",26,4,"I have not sat with vain persons, neither do I enter the company of dissemblers."],["Psalms",26,5,"I have hated the congregation of evil doers; and I do not sit with the wicked."],["Psalms",26,6,"I wash my hands in innocency: so I compass Thy altar, O Lord:"],["Psalms",26,7,"that I may sound the voice of thanksgiving, and tell of all Thy wondrous works."],["Psalms",26,8,"Lord, I love the habitation of Thy house, and the place where Thy glory dwells."],["Psalms",26,9,"Gather not my soul with sinners, nor my life with bloody men:"],["Psalms",26,10,"in whose hands is mischief, and their right hand is full of bribes."],["Psalms",26,11,"But as for me, I will walk in my integrity: redeem me, and be gracious unto me."],["Psalms",26,12,"My foot stands in an even place: in the congregations I will bless the Lord."],["Psalms",27,1,"Of David. The Lord is my light and my salvation; whom shall I fear? the Lord is the stronghold of my life; of whom shall I be afraid?"],["Psalms",27,2,"When the wicked, my enemies and my foes, came upon me to eat up my flesh, they stumbled and fell."],["Psalms",27,3,"Though a host should camp against me, my heart shall not fear: though war should rise against me, even then I will be confident."],["Psalms",27,4,"One thing have I desired of the Lord, that will I seek after; that I may dwell in the house of the Lord all the days of my life, to behold the beauty of the Lord, and to inquire in his temple."],["Psalms",27,5,"For in the day of evil he shall hide me in his pavilion: in the covert of his tent he shall hide me; he shall set me up upon a rock."],["Psalms",27,6,"And now shall my head be lifted up above my enemies round about me: therefore I will offer in his tabernacle sacrifices of joy; I will sing, and I will make melody to the Lord."],["Psalms",27,7,"Hear, O Lord, when I cry with my voice: be gracious to me, and answer me."],["Psalms",27,8,"Of Thee my heart has said, Seek my face. Thy face, O Lord, I seek."],["Psalms",27,9,"Hide not Thy face from me; put not Thy servant away in anger: Thou hast been my help; abandon me not, nor forsake me, O God of my salvation."],["Psalms",27,10,"For my father and my mother have forsaken me, but the Lord will take me up."],["Psalms",27,11,"Teach me Thy way, O Lord, and lead me in an even path, because of my enemies."],["Psalms",27,12,"Deliver me not over to the will of my enemies: for false witnesses are risen up against me, and such as breathe out violence."],["Psalms",27,13,"Were it not that I believed I should see the goodness of the Lord in the land of the living."],["Psalms",27,14,"Wait on the Lord: be of good courage, and he shall strengthen thy heart: and wait on the Lord."],["Psalms",28,1,"Of David. To Thee I will cry, O Lord; my rock; be not silent to me: lest, if Thou be silent to me, I become like those who go down into the pit."],["Psalms",28,2,"Hear the voice of my supplications, when I cry to Thee, when I lift up my hands towards Thy holy sanctuary."],["Psalms",28,3,"Drag me not away with the wicked, and with the workers of iniquity, who speak peace to their neighbours, but there is evil in their hearts."],["Psalms",28,4,"Give them according to their deeds, and according to the wickedness of their endeavours: give them after the work of their hands; render to them their desert."],["Psalms",28,5,"Because they give no heed to the works of the Lord, nor to the operation of his hands, he will destroy them, and not build them up."],["Psalms",28,6,"Blessed be the Lord, because he has heard the voice of my supplications."],["Psalms",28,7,"The Lord is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoices; and with my song I will praise him."],["Psalms",28,8,"The Lord is a strength to them, and he is the saving strength of his anointed."],["Psalms",28,9,"Save Thy people, and bless Thy inheritance: and shepherd them, and carry them forever."],["Psalms",29,1,"A Psalm of David. Ascribe to the Lord, O you mighty, ascribe to the Lord glory and strength."],["Psalms",29,2,"Give to the Lord the glory due to his name; worship the Lord in the beauty of holiness."],["Psalms",29,3,"The voice of the Lord is upon the waters: the God of glory thunders: the Lord is upon many waters."],["Psalms",29,4,"The voice of the Lord is powerful; the voice of the Lord is full of majesty."],["Psalms",29,5,"The voice of the Lord breaks the cedars; yea, the Lord breaks the cedars of the Lebanon."],["Psalms",29,6,"He makes them also skip like a calf; Lebanon and Sirion like a young wild ox."],["Psalms",29,7,"The voice of the Lord divides the flames of fire."],["Psalms",29,8,"The voice of the Lord shakes the wilderness; the Lord shakes the wilderness of Kadesh."],["Psalms",29,9,"The voice of the Lord makes the hinds to calve, and strips the forests bare, and in his temple everyone speaks of his glory."],["Psalms",29,10,"The Lord sat enthroned at the flood; and he sits enthroned as King forever."],["Psalms",29,11,"The Lord gives strength to his people; the Lord blesses his people with peace."],["Psalms",30,1,"A Psalm and Song at the dedication of the house; of David."],["Psalms",30,2,"I will extol Thee, O Lord; for Thou hast lifted me up, and hast not made my foes to rejoice over me."],["Psalms",30,3,"O Lord my God, I cried to Thee and Thou hast healed me."],["Psalms",30,4,"O Lord, Thou hast brought up my soul from Sheol: Thou hast kept me alive, that I should not go down to the pit."],["Psalms",30,5,"Sing to the Lord, O his pious ones, and give thanks to his holy name."],["Psalms",30,6,"For his anger endures but a moment; in his favour is life: weeping may endure for a night, but joy comes in the morning."],["Psalms",30,7,"And in my prosperity I said, I shall never be moved."],["Psalms",30,8,"Lord, by Thy favour Thou hast made my mountain to stand strong: Thou didst hide Thy face, and I was affrighted."],["Psalms",30,9,"I cried to Thee, O Lord; and to the Lord I made supplication."],["Psalms",30,10,"What profit is there in my blood, when I go down to the pit? Shall dust praise Thee? shall it declare Thy truth?"],["Psalms",30,11,"Hear, O Lord, and be gracious to me: Lord, be Thou my helper."],["Psalms",30,12,"Thou hast turned for me my mourning into dancing: Thou hast loosed my sackcloth, and girded me with gladness;"],["Psalms",30,13,"to the end that my glory may sing praise to Thee, and not be silent. O Lord my God, I will give thanks to Thee forever."],["Psalms",31,1,"To the chief Musician, A Psalm of David."],["Psalms",31,2,"In Thee, O Lord, do I take refuge; let me never be ashamed: deliver me in Thy righteousness."],["Psalms",31,3,"Incline Thy ear to me; deliver me speedily: be Thou my strong rock, a fortress of defence to save me."],["Psalms",31,4,"For Thou art my rock and my fortress; therefore for Thy name's sake lead me, and guide me."],["Psalms",31,5,"Pull me out of the net that they have hidden for me: for Thou art my stronghold."],["Psalms",31,6,"Into Thy hand I commit my spirit: Thou hast redeemed me, O Lord God of truth."],["Psalms",31,7,"I hate them that regard vain idols: but I trust in the Lord."],["Psalms",31,8,"I will be glad and rejoice in Thy loyal love: for Thou hast considered my affliction: Thou hast known the troubles of my soul;"],["Psalms",31,9,"and Thou hast not delivered me up into the hand of the enemy: Thou hast set my feet in a broad place."],["Psalms",31,10,"Be gracious to me, O Lord, for I am in trouble: my eye is consumed with grief, my soul and my body."],["Psalms",31,11,"For my life is spent with grief, and my years with sighing: my strength fails because of my iniquity, and my bones are wasted away."],["Psalms",31,12,"I am the scorn of all my adversaries, and very much of my neighbours, and a dread to my acquaintances: those who see me in the street flee from me."],["Psalms",31,13,"I am forgotten as a dead man out of mind: I am like a broken vessel."],["Psalms",31,14,"For I have heard the slander of many: fear on every side: while they took counsel together against me, they devised to take away my life."],["Psalms",31,15,"But I trusted in Thee, O Lord: I said, Thou art my God."],["Psalms",31,16,"My times are in Thy hand: deliver me from the hand of my enemies, and from those who persecute me."],["Psalms",31,17,"Make Thy face to shine upon Thy servant: save me by Thy loyal love."],["Psalms",31,18,"Let me not be ashamed, O Lord; for I have called upon Thee: let the wicked be ashamed, and let them be silent in Sheol."],["Psalms",31,19,"Let the lying lips be put to silence; which speak arrogant words, proudly and contemptuously, against the righteous."],["Psalms",31,20,"Oh how great is Thy goodness, which Thou has laid up for those who fear Thee; which Thou hast performed for those who trust in Thee in the sight of the sons of men!"],["Psalms",31,21,"Thou hidest them in the covert of Thy presence from the plots of men: Thou shalt keep them secretly in a pavilion from the strife of tongues."],["Psalms",31,22,"Blessed be the Lord: for he has shown me his marvellous love in a strong city."],["Psalms",31,23,"For I said in my haste, I am cut off from before Thy eyes: nevertheless Thou didst hear the voice of my supplications when I cried to Thee."],["Psalms",31,24,"O love the Lord, all his pious ones: for the Lord preserves the faithful, and plentifully repays him who acts haughtily."],["Psalms",31,25,"Be of good courage, and let your heart be strong, all you who hope in the Lord."],["Psalms",32,1,"Of David. A maskil. Blessed is he whose transgression is forgiven, whose sin is covered."],["Psalms",32,2,"Blessed is the man to whom the Lord imputes no iniquity, and in whose spirit there is no guile."],["Psalms",32,3,"When I kept silence, my bones wasted away through my groaning all the day long."],["Psalms",32,4,"For day and night Thy hand was heavy upon me: my moisture is turned into the drought of summer. (Selah.)"],["Psalms",32,5,"I acknowledged my sin to Thee, and my iniquity I have not hid. I said, I will confess my transgressions to the Lord; and Thou didst forgive the iniquity of my sin. (Selah.)"],["Psalms",32,6,"For this shall everyone that is godly pray to Thee in a time when Thou mayst be found: then surely the floods of great waters shall not come near him."],["Psalms",32,7,"Thou art my hiding place; Thou shalt preserve me from trouble; Thou dost compass me about with songs of deliverance. (Selah.)"],["Psalms",32,8,"I will instruct thee and teach thee in the way which thou shalt go: I will counsel thee, with my eye upon thee."],["Psalms",32,9,"Be not like the horse, or the mule, which have no understanding: whose mouth must be held in with bit and bridle, that they come not near to thee."],["Psalms",32,10,"Many are the sorrows of the wicked: but he that trusts in the Lord, shall be surrounded by love."],["Psalms",32,11,"Be glad in the Lord, and rejoice, O you righteous: and shout for joy, all you who are upright in heart."],["Psalms",33,1,"Rejoice in the Lord, O you righteous: praise is comely for the upright."],["Psalms",33,2,"Praise the Lord with a lyre: make melody to him with the harp of ten strings."],["Psalms",33,3,"Sing to him a new song; play skillfully with loud jubilations."],["Psalms",33,4,"For the word of the Lord is right; and all his work is done in faithfulness."],["Psalms",33,5,"He loves righteousness and judgment: the earth is full of the goodness of the Lord."],["Psalms",33,6,"By the word of the Lord were the heavens made; and all the host of them by the breath of his mouth."],["Psalms",33,7,"He gathers the waters of the sea together like a rampart: he lays up the depths in storehouses."],["Psalms",33,8,"Let all the earth fear the Lord: let all the inhabitants of the world stand in awe of him."],["Psalms",33,9,"For he spoke, and it was; he commanded, and it stood fast."],["Psalms",33,10,"The Lord brings the counsel of the nations to nought: he makes the devices of the peoples to be of no effect."],["Psalms",33,11,"The counsel of the Lord stands forever, the thoughts of his heart to all generations."],["Psalms",33,12,"Happy is the nation whose God is the Lord; and the people whom he has chosen for his own inheritance."],["Psalms",33,13,"The Lord looks down from heaven; he beholds all the sons of men."],["Psalms",33,14,"From the place of his habitation he looks upon all the inhabitants of the earth;"],["Psalms",33,15,"he who fashions their hearts alike; who considers all their deeds."],["Psalms",33,16,"There is no king saved by the multitude of a host: a mighty man is not delivered by great strength."],["Psalms",33,17,"A horse is a vain thing for safety: nor shall he save by his great strength."],["Psalms",33,18,"Behold, the eye of the Lord is upon those who fear him, upon those who hope in his steadfast love:"],["Psalms",33,19,"to deliver their soul from death, and to keep them alive in famine."],["Psalms",33,20,"Our soul waited for the Lord: he is our help and our shield."],["Psalms",33,21,"For our heart shall rejoice in him, because we have trusted in his holy name."],["Psalms",33,22,"Let Thy steadfast love, O Lord be upon us, even as we hope in Thee."],["Psalms",34,1,"Of David, when he changed his demeanour before Abimelech; who drove him away, and he departed."],["Psalms",34,2,"I will bless the Lord at all time: his praise shall continually be in my mouth."],["Psalms",34,3,"My soul shall glory in the Lord: the humble shall hear of it, and be glad."],["Psalms",34,4,"O magnify the Lord with me, and let us exalt his name together."],["Psalms",34,5,"I sought the Lord, and he answered me, and delivered me from all my fears."],["Psalms",34,6,"They looked to him, and are radiant: and their faces shall not be ashamed."],["Psalms",34,7,"This poor man cries, and the Lord hears, and saves him out of all his troubles."],["Psalms",34,8,"The angel of the Lord encamps round about those who fear him, and he delivers them."],["Psalms",34,9,"O taste and see that the Lord is good: blessed is the man who trusts in him."],["Psalms",34,10,"O fear the Lord, you saints of his: for those who fear him have no lack."],["Psalms",34,11,"The young lions lack, and suffer hunger: but they who seek the Lord shall not want any good thing."],["Psalms",34,12,"Come, children, hearken to me: I will teach you the fear of the Lord."],["Psalms",34,13,"Who is the man that desires life, and loves many days, that he may see good?"],["Psalms",34,14,"Keep thy tongue from evil, and thy lips from speaking guile."],["Psalms",34,15,"Depart from evil, and do good; seek peace, and pursue it."],["Psalms",34,16,"The eyes of the Lord are towards the righteous, and his ears are open to their cry."],["Psalms",34,17,"The face of the Lord is against those who do evil, to cut off the remembrance of them from the earth."],["Psalms",34,18,"The righteous cry, and the Lord hears, and delivers them out of all their troubles."],["Psalms",34,19,"The Lord is near to them who are of a broken heart; and he saves such as are of a contrite spirit."],["Psalms",34,20,"Many are the afflictions of the righteous: but the Lord delivers him out of them all."],["Psalms",34,21,"He keeps all his bones: not one of them is broken."],["Psalms",34,22,"Evil shall slay the wicked: and they that hate the righteous shall be condemned."],["Psalms",34,23,"The Lord redeems the soul of his servants: and none of them that trust in him shall be condemned."],["Psalms",35,1,"Of David. Strive, O Lord, with those who contend against me: fight with those who oppose me."],["Psalms",35,2,"Take hold of shield and buckler, and rise up for my help."],["Psalms",35,3,"Draw out also the spear, and battle axe against those who persecute me: say to my soul, I am thy salvation."],["Psalms",35,4,"Let them be confounded and put to shame who seek after my soul: let them be turned back and brought to confusion who devise my hurt."],["Psalms",35,5,"Let them be as chaff before the wind: the angel of the Lord thrusting them."],["Psalms",35,6,"Let their way be dark and slippery: the angel of the Lord pursuing them."],["Psalms",35,7,"For without cause have they hid for me their net; a pit without cause have they dug for my soul."],["Psalms",35,8,"Let destruction come upon him unawares; and let his net that he has hid catch himself: let him fall to ruin."],["Psalms",35,9,"And my soul shall be joyful in the Lord: it shall rejoice in his salvation."],["Psalms",35,10,"All my bones shall say, Lord, who is like Thee, who delivers the poor from him that is too strong for him, and the poor and the needy from him that robs him?"],["Psalms",35,11,"False witnesses rise up; they ask me things that I know not."],["Psalms",35,12,"They repay me evil for good; a bereavement to my soul!"],["Psalms",35,13,"But as for me, when they were sick, my clothing was sackcloth: I afflicted my soul with fasting; and as for my prayer may it return to my own bosom."],["Psalms",35,14,"I went about as for my friend or brother: I bowed down heavily, as one who mourns for his mother."],["Psalms",35,15,"But when I stumble they rejoice, and gather themselves together. Wretches whom I have not known tear me in pieces without ceasing."],["Psalms",35,16,"Like profane men, scornful mockers, they grind their teeth against me."],["Psalms",35,17,"Lord, how long wilt Thou look on? rescue my soul from their destructions, my only one from the lions."],["Psalms",35,18,"I will give Thee thanks in the great congregation: I will praise Thee among a numerous people."],["Psalms",35,19,"Let not those who are wrongfully my enemies rejoice over me; or those who hate me without cause wink their eye."],["Psalms",35,20,"For they seek not peace: but they devise deceitful matters against those who are quiet in the land."],["Psalms",35,21,"For they open their mouths wide against me, and say, Aha, aha, our eye has seen it."],["Psalms",35,22,"Thou hast seen, O Lord: keep no silence: O Lord, be not far from me."],["Psalms",35,23,"Rouse Thyself, and awake to my judgment; to my cause, my God and my Lord."],["Psalms",35,24,"Judge me, O Lord my God, according to Thy righteousness; and let them not rejoice over me."],["Psalms",35,25,"Let them not say in their hearts, Ah, so we have our desire: let them not say, We have swallowed him up."],["Psalms",35,26,"Let them be ashamed and brought to confusion together, those who rejoice at my hurt: let them be clothed with shame and dishonour, those who magnify themselves against me."],["Psalms",35,27,"Let them shout for joy, and be glad, those who favour my righteous cause: and let them say continually, Let the Lord be magnified, who has pleasure in the welfare of his servant."],["Psalms",35,28,"And my tongue shall speak of Thy righteousness; of Thy praise all the day long."],["Psalms",36,1,"To the chief Musician, of David the servant of the Lord."],["Psalms",36,2,"Transgression speaks to the wicked within his heart; there is no fear of God before his eyes."],["Psalms",36,3,"For he flatters himself in his own eyes, that his iniquity cannot be found out and hated."],["Psalms",36,4,"The words of his mouth are iniquity and deceit: he has left off being wise, and doing good."],["Psalms",36,5,"He devises mischief upon his bed; he sets himself in a way that is not good; he does not abhor evil."],["Psalms",36,6,"Thy steadfast love, O Lord, is in the heavens; and Thy faithfulness reaches the clouds."],["Psalms",36,7,"Thy righteousness is like the great mountains; Thy judgments are a great deep: O Lord, Thou preservest man and beast."],["Psalms",36,8,"How excellent is Thy love, O God! therefore the children of men shelter under the shadow of Thy wings."],["Psalms",36,9,"They are abundantly satisfied with the fatness of Thy house; and Thou makest them to drink of the river of Thy pleasures."],["Psalms",36,10,"For with Thee is the fountain of life: in Thy light we see light."],["Psalms",36,11,"O continue Thy steadfast love to those who know Thee; and Thy righteousness to the upright in heart."],["Psalms",36,12,"Let not the foot of pride come against me, and let not the hand of the wicked drive me away."],["Psalms",36,13,"There are the workers of iniquity fallen: they are cast down, and are not able to rise."],["Psalms",37,1,"Of David. Fret not thyself because of evil doers, nor be envious against the workers of iniquity."],["Psalms",37,2,"For they shall soon be cut down like the grass, and wither like the green herb."],["Psalms",37,3,"Trust in the Lord, and do good; dwell in the land, and enjoy security."],["Psalms",37,4,"Delight thyself also in the Lord; and he shall give thee the desires of thy heart."],["Psalms",37,5,"Commit thy way to the Lord; trust also in him; and he will bring it to pass."],["Psalms",37,6,"And he will bring forth thy righteousness as the light, and thy judgment like the noonday."],["Psalms",37,7,"Rest in the Lord, and wait patiently for him: fret not thyself because of him who prospers in his way, because of the man who accomplishes wicked devices."],["Psalms",37,8,"Cease from anger, and forsake wrath: fret not thyself: it comes to no good."],["Psalms",37,9,"For evildoers shall be cut off: but those who wait upon the Lord, they shall inherit the earth."],["Psalms",37,10,"For yet a little while, and the wicked shall not be: and thou shalt look well at his place, but he will not be there."],["Psalms",37,11,"But the meek shall inherit the earth; and shall delight themselves in the abundance of peace."],["Psalms",37,12,"The wicked man plots against the just, and grinds his teeth against him."],["Psalms",37,13,"The Lord shall laugh at him: for he sees that his day is coming."],["Psalms",37,14,"The wicked have drawn out the sword, and have bent their bow, to cast down the poor and needy, and to slay such as are of upright ways."],["Psalms",37,15,"Their sword shall enter into their own heart, and their bows shall be broken."],["Psalms",37,16,"A little that a righteous man has is better than the riches of many wicked men."],["Psalms",37,17,"For the arms of the wicked shall be broken: but the Lord upholds the just."],["Psalms",37,18,"The Lord knows the days of the innocent: and their inheritance shall be for ever."],["Psalms",37,19,"They shall not be ashamed in the evil time: and in the days of famine they shall be satisfied."],["Psalms",37,20,"But the wicked and the enemies of the Lord shall perish like the glory of the meadows; they shall consume; they shall pass away in smoke."],["Psalms",37,21,"The wicked borrows, but does not pay back: but the righteous man gives with a good grace."],["Psalms",37,22,"For such as are blessed of him shall inherit the earth; and they that are cursed of him shall be cut off."],["Psalms",37,23,"The steps of a man are ordered by the Lord: and he delights in his way."],["Psalms",37,24,"Though he fall, he shall not be utterly cast down: for the Lord upholds him with his hand."],["Psalms",37,25,"I have been young, and now am old; yet I have not seen a just man forsaken, and his seed begging bread."],["Psalms",37,26,"He lends generously at all times; and his seed is blessed."],["Psalms",37,27,"Depart from evil, and do good; and dwell for evermore."],["Psalms",37,28,"For the Lord loves justice, and forsakes not his pious ones; they are preserved for ever: but the seed of the wicked shall be cut off."],["Psalms",37,29,"The righteous shall inherit the land, and dwell in it for ever."],["Psalms",37,30,"The mouth of the righteous speaks wisdom, and his tongue discourses justice."],["Psalms",37,31,"The law of his God is in his heart; none of his steps shall falter."],["Psalms",37,32,"The wicked man watches the righteous, and seeks to slay him."],["Psalms",37,33,"The Lord will not leave him in his hand, nor allow him to be condemned when he is judged."],["Psalms",37,34,"Wait on the Lord, and keep his way, and he shall exalt thee to inherit the land: when the wicked are cut off, thou shalt see it."],["Psalms",37,35,"I have seen the wicked in great power, and spreading himself like a green tree in its native soil."],["Psalms",37,36,"Yet he passed away, and, lo, he was not: I sought him, but he could not be found."],["Psalms",37,37,"Mark the perfect man, and behold the upright: for the end of that man is peace."],["Psalms",37,38,"But the transgressors are destroyed together: the end of the wicked is cut off."],["Psalms",37,39,"And the salvation of the righteous is of the Lord: he is their strength in the time of trouble."],["Psalms",37,40,"And the Lord will help them, and deliver them: he shall deliver them from the wicked, and save them, because they take refuge in him."],["Psalms",38,1,"A Psalm of David, for invocation."],["Psalms",38,2,"O Lord, rebuke me not in Thy wrath: nor chasten me in Thy hot displeasure."],["Psalms",38,3,"For Thy arrows stick fast in me, and Thy hand presses me sore."],["Psalms",38,4,"There is no soundness in my flesh because of Thy anger; nor is there any health in my bones because of my sin."],["Psalms",38,5,"For my iniquities are gone over my head: like a heavy burden they are too heavy for me."],["Psalms",38,6,"My wounds stink; they fester because of my foolishness."],["Psalms",38,7,"I am troubled; I am bowed down greatly; I go mourning all the day long."],["Psalms",38,8,"For my loins are filled with burning: and there is no soundness in my flesh."],["Psalms",38,9,"I am feeble and sore broken: I groan by reason of the disquietness of my heart."],["Psalms",38,10,"Lord, all my desire is before Thee; and my sighing is not hid from Thee."],["Psalms",38,11,"My heart palpitates, my strength fails me: as for the light of my eyes, it also is gone from me."],["Psalms",38,12,"My lovers and my friends stand aloof from my plague; and my kinsmen stand afar off."],["Psalms",38,13,"And they who seek after my life lay snares for me: and they who seek my hurt speak mischievous things, and meditate deceits all the day long."],["Psalms",38,14,"But I, like a deaf man, hear not; and like a dumb man that opens not his mouth."],["Psalms",38,15,"Thus I was like a man that hears not, and in whose mouth are no rebukes."],["Psalms",38,16,"For in Thee, O Lord, I hope: Thou wilt hear, O Lord my God."],["Psalms",38,17,"For I said, Lest they should rejoice over me: when my foot slips, they magnify themselves against me."],["Psalms",38,18,"For I am ready to stumble, and my pain is continually before me."],["Psalms",38,19,"For I will declare my iniquity; I will be sorry for my sin."],["Psalms",38,20,"But my enemies are in vigorous life; and they who hate me wrongfully are many."],["Psalms",38,21,"They also who render evil for good are my adversaries; because I follow what is good."],["Psalms",38,22,"Forsake me not, O Lord: O my God, be not far from me."],["Psalms",38,23,"Make haste to help me, O Lord my salvation."],["Psalms",39,1,"To the chief Musician, for Jeduthun, A Psalm of David."],["Psalms",39,2,"I said, I will take heed to my ways, that I sin not with my tongue: I will keep a curb on my mouth, while the wicked man is before me."],["Psalms",39,3,"I was dumb with silence, I held my peace, had no comfort, and my pain was stirred up."],["Psalms",39,4,"My heart was hot within me; while I was musing, the fire burned: then I spoke with my tongue,"],["Psalms",39,5,"Lord, make me to know my end, and the measure of my days, what it is; I will know how frail I am."],["Psalms",39,6,"Behold, Thou hast made my days like handbreadths; and my age is as nothing before Thee: truly every man at his best state is altogether vanity. (Selah.)"],["Psalms",39,7,"Surely every man walks in a vain show: surely they are disquieted in vain: he heaps up riches, and knows not who shall gather them."],["Psalms",39,8,"And now, Lord, what do I wait for? my hope is in Thee."],["Psalms",39,9,"Deliver me from all my transgressions: make me not the reproach of the base man."],["Psalms",39,10,"I am dumb, I open not my mouth; because Thou didst it."],["Psalms",39,11,"Remove Thy stroke away from me: I am consumed by the blow of Thy hand."],["Psalms",39,12,"When Thou with rebukes dost correct a man for iniquity, Thou makest his beauty to consume away like a moth: surely every man is vanity. (Selah.)"],["Psalms",39,13,"Hear my prayer, O Lord, and give ear to my cry; keep not silence at my tears: for I am a stranger with Thee, and a sojourner, as all my fathers were."],["Psalms",39,14,"Look away from me, that I may recover brightness, before I go hence, and am no more."],["Psalms",40,1,"To the chief Musician, A Psalm of David."],["Psalms",40,2,"I waited patiently for the Lord; and he inclined to me, and heard my cry."],["Psalms",40,3,"He brought me up also out of the gruesome pit, out of the miry clay, and set my feet upon a rock, and established my footsteps."],["Psalms",40,4,"And he has put a new song in my mouth, a praise to our God. Many shall see, and fear, and shall trust in the Lord."],["Psalms",40,5,"Blessed is that man that makes the Lord his trust, and looks not to the proud, nor to such as turn aside to lies."],["Psalms",40,6,"Many, O Lord my God, are Thy wonderful works which Thou hast done, and Thy thoughts which are towards us: none can compare with Thee: if I would declare and speak of them, they are more than can be numbered."],["Psalms",40,7,"Thou dost not desire sacrifice or meal offering; Thou hast dug open my ears; burnt offering and sin offering hast Thou not required."],["Psalms",40,8,"Then said I, Lo, I come with the scroll of the book which is written for me;"],["Psalms",40,9,"I delight to do Thy will, O my God: and Thy law is within my heart."],["Psalms",40,10,"I have preached righteousness in the great congregation: lo, I did not refrain my lips, O Lord, Thou knowst."],["Psalms",40,11,"I have not hid Thy righteousness within my heart; I have declared Thy faithfulness and Thy salvation: I have not concealed Thy love and Thy truth from the great congregation."],["Psalms",40,12,"Withhold not Thou Thy tender mercies from me, O Lord: let Thy steadfast love and Thy truth continually preserve me."],["Psalms",40,13,"For innumerable evils have compassed me about: my iniquities have taken hold upon me, so that I am not able to look up; they are more than the hairs of my head: therefore my heart fails me."],["Psalms",40,14,"Be pleased, O Lord, to deliver me: O Lord, make haste to help me."],["Psalms",40,15,"Let them be ashamed and confounded together who seek after my soul to destroy it; let them be turned backward and put to shame who wish me evil."],["Psalms",40,16,"Let them be appalled because of their shame who say concerning me, Aha, aha."],["Psalms",40,17,"Let all those who seek Thee rejoice and be glad in Thee: let such as love Thy salvation say continually, The Lord be magnified."],["Psalms",40,18,"But I am poor and needy; yet the Lord takes thought for me: Thou art my help and my deliverer; delay not, O my God!"],["Psalms",41,1,"To the chief Musician, A Psalm of David."],["Psalms",41,2,"Blessed is he who considers the poor: the Lord will deliver him in the day of evil."],["Psalms",41,3,"The Lord preserves him, and keeps him alive; he is called happy upon the earth: and Thou wilt not deliver him to the will of his enemies."],["Psalms",41,4,"The Lord strengthens him upon the bed of sickness: whenever he is prostrate Thou recoverest him in his illness."],["Psalms",41,5,"I said, Lord, be gracious to me: heal my soul; for I have sinned against Thee."],["Psalms",41,6,"My enemies speak evil of me, When shall he die, and his name perish?"],["Psalms",41,7,"And if one comes to see me, he speaks vanity: his heart gathers iniquity to itself; when he goes abroad, he tells it."],["Psalms",41,8,"All that hate me whisper together against me: against me they devise my hurt."],["Psalms",41,9,"An evil disease, say they, cleaves fast to him: and from where he lies he shall rise up no more."],["Psalms",41,10,"Even my own familiar friend, in whom I trusted, who did eat of my bread, has lifted up his heel against me."],["Psalms",41,11,"But Thou, O Lord, be gracious to me, and raise me up, that I may pay them back."],["Psalms",41,12,"By this I know that Thou favourest me, because my enemy does not triumph over me."],["Psalms",41,13,"And as for me, Thou upholdest me in my integrity, and settest me before Thy face for ever."],["Psalms",41,14,"Blessed be the Lord, the God of Israel from everlasting, and to everlasting. Amen, and Amen."],["Psalms",42,1,"To the chief Musician, A Maschil, for the sons of Korah."],["Psalms",42,2,"As the hart pants after the water brooks, so my soul pants after Thee, O God."],["Psalms",42,3,"My soul thirsts for God, for the living God: when shall I come and appear before God?"],["Psalms",42,4,"My tears have been my bread day and night, while they say to me all the day, Where is thy God?"],["Psalms",42,5,"When I remember these things, I pour out my soul in me: how I was wont to pass on with the throng, leading them in procession to the house of God, with the voice of joy and praise, a crowd keeping holiday."],["Psalms",42,6,"Why art thou cast down, O my soul? and why dost thou moan within me? hope thou in God: for I shall yet praise him for the help of his countenance."],["Psalms",42,7,"O my God, my soul is cast down within me: because I remember Thee from the land of Jordan and the hills of Hermon, from the mount Mizar."],["Psalms",42,8,"Deep calls to deep at the noise of Thy cataracts: all Thy waves and Thy billows are gone over me."],["Psalms",42,9,"Yet the Lord will command his steadfast love in the daytime, and in the night his song shall be with me, a prayer to the God of my life."],["Psalms",42,10,"I will say to God my rock, Why hast Thou forgotten me? why go I mourning under the oppression of the enemy?"],["Psalms",42,11,"Like a deadly wound in my bones, my enemies taunt me; while they say daily to me, Where is thy God?"],["Psalms",42,12,"Why art thou cast down, O my soul? and why moanest thou within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God."],["Psalms",43,1,"Judge me, O God, and plead my cause against an ungodly nation: O deliver me from the deceitful and unjust man."],["Psalms",43,2,"For Thou art the God of my strength: why dost Thou cast me off? why go I mourning under the oppression of the enemy?"],["Psalms",43,3,"O send out Thy light and Thy truth: let them lead me; let them bring me to Thy holy hill, and to Thy dwelling places."],["Psalms",43,4,"Then will I go to the altar of God, to God my exceeding joy: and I will praise thee with the lyre, O God my God."],["Psalms",43,5,"Why art thou cast down, O my soul? and why dost thou moan within me? hope in God: for I shall yet praise him, who is the health of my countenance, and my God."],["Psalms",44,1,"To the chief Musician for the sons of Korah, A Maschil."],["Psalms",44,2,"We have heard with our ears, O God; our fathers have told us, what work Thou didst in their days, in the times of old:"],["Psalms",44,3,"how Thou didst drive out nations with Thy hand, and didst plant them; how Thou didst batter the peoples, and cast them out."],["Psalms",44,4,"For they did not get the land in possession by their own sword, nor did their own arm save them: but Thy right hand, and Thy arm, and the light of Thy countenance, because Thou didst favourably accept them."],["Psalms",44,5,"Thou art my King, O God: command deliverances for Jacob."],["Psalms",44,6,"Through Thee will we push down our enemies: through Thy name will we tread those under who rise up against us."],["Psalms",44,7,"For I trust not in my bow, nor shall my sword save me."],["Psalms",44,8,"But Thou hast saved us from our enemies, and hast put to shame those who hated us."],["Psalms",44,9,"In God we have gloried all the day long, and we praise Thy name for ever. (Selah.)"],["Psalms",44,10,"Yet, Thou hast cast off, and put us to shame; and Thou goest not forth with our armies."],["Psalms",44,11,"Thou makest us to turn back from the enemy: and they who hate us take plunder for themselves."],["Psalms",44,12,"Thou hast given us like sheep to be eaten: and hast scattered us among the nations."],["Psalms",44,13,"Thou sellest Thy people for no great gain, and hast not put high their prices."],["Psalms",44,14,"Thou dost make us a taunt to our neighbours, a scorn and a derision to those round about us."],["Psalms",44,15,"Thou makest us a byword among the nations, a shaking of the head among the peoples."],["Psalms",44,16,"My confusion is before me all the day, and the shame of my face has covered me,"],["Psalms",44,17,"For the voice of him that taunts and blasphemes; by reason of the enemy and avenger."],["Psalms",44,18,"All this is come upon us; yet we have not forgotten Thee, nor have we been false to Thy covenant."],["Psalms",44,19,"Our heart is not turned back, nor have our steps declined from Thy way;"],["Psalms",44,20,"though Thou hast sore broken us in the place of jackals, and covered us with the shadow of death."],["Psalms",44,21,"If we had forgotten the name of our God, or stretched out our hands to a strange god;"],["Psalms",44,22,"would not God search this out? for he knows the secrets of the heart."],["Psalms",44,23,"But for Thy sake are we killed all the day long; we are reckoned as sheep for the slaughter."],["Psalms",44,24,"Awake, why sleepest Thou, O Lord? arise, cast us not off for ever."],["Psalms",44,25,"Why dost Thou hide Thy face, and forget our affliction and our oppression?"],["Psalms",44,26,"For our soul is bowed down to the dust: our belly cleaves to the earth."],["Psalms",44,27,"Arise for our help, and redeem us for the sake of Thy steadfast love."],["Psalms",45,1,"To the chief Musician, to Shoshannim, A Maschil for the sons of Korah. A Song of loves."],["Psalms",45,2,"My heart overflows with a goodly matter: I relate my verses for the king: my tongue is the pen of a ready writer."],["Psalms",45,3,"Thou art fairer than the children of men: grace is poured into thy lips: therefore God has blessed thee for ever."],["Psalms",45,4,"Gird thy sword upon thy thigh, O mighty warrior: thy glory and thy majesty."],["Psalms",45,5,"And in thy majesty ride prosperously on in the cause of truth and for the sake of righteousness; and let thy right hand teach thee terrible things."],["Psalms",45,6,"Thy arrows are sharp: the people fall under thee: they sink into the heart of the king's enemies."],["Psalms",45,7,"Thy throne, of God, is for ever and ever: the sceptre of thy kingdom is a sceptre of equity."],["Psalms",45,8,"Thou lovest righteousness, and hatest wickedness: therefore God, thy God, has anointed thee with the oil of gladness above thy fellows."],["Psalms",45,9,"All thy garments are fragrant with myrrh, and aloes, and cassia: out of the ivory palaces stringed instruments have made thee glad."],["Psalms",45,10,"Kings' daughters are among thy favourites: upon thy right hand stands the queen in gold of Ophir."],["Psalms",45,11,"Hearken, O daughter, and consider, and incline thy ear; forget also thy own people, and thy father's house;"],["Psalms",45,12,"so shall the king desire thy beauty: for he is thy lord; and do homage to him."],["Psalms",45,13,"And O daughter of Tyre, the rich among the people, shall entreat thy favour with a gift."],["Psalms",45,14,"The king's daughter is all glorious within: her clothing is inwrought with gold."],["Psalms",45,15,"She shall be brought to the king in embroidered garments: the virgins, her companions that follow her, shall be brought to thee."],["Psalms",45,16,"With gladness and rejoicing shall they be led: they shall enter the king's palace."],["Psalms",45,17,"Instead of thy fathers shall be thy children, whom thou shalt make princes in all the earth."],["Psalms",45,18,"I will make thy name to be remembered in all generations: therefore shall the people praise Thee for ever and ever."],["Psalms",46,1,"To the chief Musician for the sons of Korah, A Song to Alamoth."],["Psalms",46,2,"God is our refuge and strength, a very present help in trouble."],["Psalms",46,3,"Therefore we will not fear, though the earth change, and though the mountains are moved in the midst of the sea;"],["Psalms",46,4,"though its waters roar and are troubled, though the mountains shake with the swelling thereof. (Selah.)"],["Psalms",46,5,"There is a river, whose streams make glad the city of God, the holiest dwelling place of the most High."],["Psalms",46,6,"God is in the midst of her; she shall not be moved: God shall help her at the dawn of day."],["Psalms",46,7,"Nations raged, kingdoms were moved: he uttered his voice, the earth melted."],["Psalms",46,8,"The Lord of hosts is with us; the God of Jacob is our fortress. (Selah.)"],["Psalms",46,9,"Come, behold the works of the Lord, who has made desolations in the earth."],["Psalms",46,10,"He makes wars to cease to the end of the earth; he breaks the bow, and cuts the spear in sunder; he burns the chariots in the fire."],["Psalms",46,11,"Be still, and know that I am God: I will be exalted among the nations, I will be exalted in the earth."],["Psalms",46,12,"The Lord of hosts is with us; the God of Jacob is our fortress. (Selah.)"],["Psalms",47,1,"To the chief Musician, A Psalm for the sons of Korah."],["Psalms",47,2,"O clap your hands, all you peoples; shout to God with the voice of triumph."],["Psalms",47,3,"For the Lord most high is terrible; he is a great King over all the earth."],["Psalms",47,4,"He subdues peoples under us, and nations under our feet."],["Psalms",47,5,"He chooses our inheritance for us, the pride of Jacob whom he loves. (Selah.)"],["Psalms",47,6,"God is gone up with a shout, the Lord with the sound of a shofar."],["Psalms",47,7,"Sing praises to God, sing praises: sing praises to our King, sing praises."],["Psalms",47,8,"For God is the King of all the earth: sing a Maschil psalm."],["Psalms",47,9,"God reigns over the nations: God sits upon the throne of his holiness."],["Psalms",47,10,"The nobles of the peoples are gathered together, the people of the God of Abraham: for the shields of the earth belong to God: he is greatly exalted."],["Psalms",48,1,"A Song, A Psalm for the sons of Korah."],["Psalms",48,2,"Great is the Lord, and highly to be praised in the city of our God, in the mountain of his holiness."],["Psalms",48,3,"Beautiful for situation, the joy of the whole earth: mount Zion, the sides of the north, the city of the great King."],["Psalms",48,4,"God is known in her palaces for a fortress."],["Psalms",48,5,"For, lo, the kings were assembled, they came on together."],["Psalms",48,6,"As soon as they saw, they were astounded; they were affrighted; they rushed away."],["Psalms",48,7,"Fear took hold of them there, and pain, like a woman in travail."],["Psalms",48,8,"Thou breakest the ships of Tarshish with an east wind."],["Psalms",48,9,"As we have heard, so have we seen in the city of the Lord of hosts, in the city of our God: may God establish it for ever. (Selah.)"],["Psalms",48,10,"We have thought of Thy steadfast love, O God, in the midst of Thy temple."],["Psalms",48,11,"According to Thy name, O God, so is Thy praise to the ends of the earth: Thy right hand is full of righteousness."],["Psalms",48,12,"Let mount Zion rejoice, let the daughters of Judah be glad, because of Thy judgments."],["Psalms",48,13,"Walk about Zion, and go round about her: count her towers."],["Psalms",48,14,"Mark well her bulwarks, consider her palaces; that you may tell it to the generation following."],["Psalms",48,15,"For such is God, our God, for ever and ever: he will be our guide to the death."],["Psalms",49,1,"To the chief Musician, A Psalm for the sons of Korah."],["Psalms",49,2,"Hear this, all the peoples; give ear, all the inhabitants of the world:"],["Psalms",49,3,"both low and high, rich and poor, together."],["Psalms",49,4,"My mouth shall speak wisdom; and the meditation of my heart shall be understanding."],["Psalms",49,5,"I will incline my ear to a parable: I will open my riddle to the lyre."],["Psalms",49,6,"Why should I fear in the days of evil, when the iniquity of my persecutors compasses me about?"],["Psalms",49,7,"They that trust in their wealth, and boast themselves in the multitude of their riches;"],["Psalms",49,8,"none of them can by any means redeem his brother, nor give to God a ransom for him:"],["Psalms",49,9,"for the redemption of their soul is too dear, and he leaves it for ever:"],["Psalms",49,10,"that he might still live for ever, and not see the pit."],["Psalms",49,11,"When he sees that wise men die, that the fool and the brutish person perish together, and leave their wealth to others:"],["Psalms",49,12,"their inward thought is, that their houses shall continue for ever, and their dwelling places to all generations; they call their lands after their own names."],["Psalms",49,13,"Nevertheless man abides not in honour: he is like the beasts that perish."],["Psalms",49,14,"This is their way in their folly: and their posterity who approve their sayings. (Selah.)"],["Psalms",49,15,"Like sheep they are appointed to Sheol; death shall be their shepherd; and the upright shall have dominion over them in the morning; and their form shall waste away in Sheol, leaving behind their dwelling."],["Psalms",49,16,"But God will redeem my soul from the power of Sheol: for he shall receive me. (Sheol.)"],["Psalms",49,17,"Be not thou afraid when one is made rich, when the glory of his house is increased;"],["Psalms",49,18,"for when he dies he shall carry nothing away: his glory shall not descend after him."],["Psalms",49,19,"Though while he lives he blesses his soul: and though men praise thee, when thou doest well to thyself:"],["Psalms",49,20,"it shall go to the generation of his fathers; they shall never see light."],["Psalms",49,21,"Man that is in honour, and understands not, is like the beasts that perish."],["Psalms",50,1,"A Psalm of Asaph. The mighty one, God, the Lord, has spoken, and called the earth from the rising of the sun to the going down thereof."],["Psalms",50,2,"Out of Zion, the perfection of beauty, God has shone forth."],["Psalms",50,3,"Our God comes, and does not keep silence: a fire devours before him, and it is very tempestuous round about him."],["Psalms",50,4,"He calls to the heavens above, and to the earth, that he may judge his people."],["Psalms",50,5,"Gather my pious ones together to me; those that have made a covenant with me by sacrifice."],["Psalms",50,6,"And the heavens declare his righteousness: for God is judge himself. (Selah.)"],["Psalms",50,7,"Hear, O my people, and I will speak; O Israel, and I will testify against thee: I am God, thy God."],["Psalms",50,8,"I will not reprove thee for thy sacrifices; and thy burnt offerings are continually before me."],["Psalms",50,9,"I will take no bullock out of thy house, nor he goats out of thy folds."],["Psalms",50,10,"For every beast of the forest is mine, and the cattle upon a thousand hills."],["Psalms",50,11,"I know all the birds of the mountains: and the wild beasts of the field are mine."],["Psalms",50,12,"If I were hungry, I would not tell thee: for the world is mine, and the fulness thereof."],["Psalms",50,13,"Do I eat the flesh of bulls, or drink the blood of goats?"],["Psalms",50,14,"Offer to God a thanksgiving; and pay thy vows to the most High:"],["Psalms",50,15,"and call upon me in the day of trouble: I will deliver thee, and thou shalt glorify me."],["Psalms",50,16,"But to the wicked man God says, What hast thou to do to declare my statutes, or that thou shouldst take my covenant in thy mouth?"],["Psalms",50,17,"Seeing thou hatest instruction, and dost cast my words behind thee."],["Psalms",50,18,"When thou didst see a thief, then thou didst consort with him, and hast been partaker with adulterers."],["Psalms",50,19,"Thou givest thy mouth free rein for evil, and thy tongue frames deceit."],["Psalms",50,20,"Thou sittest and speakest against thy brother; thou dost slander thy own mother's son."],["Psalms",50,21,"These things hast thou done, and if I kept silence, thou wouldst think that I was altogether such a one as thyself: but I will reprove thee, and set the matter before thy eyes."],["Psalms",50,22,"Now consider this, you who forget God, lest I tear you in pieces, and there be none to deliver."],["Psalms",50,23,"Whoever offers praise glorifies me: and to him that orders his way aright I will show the salvation of God."],["Psalms",51,1,"To the chief Musician, A Psalm of David,"],["Psalms",51,2,"when Nathan the prophet came to him, after he had gone in to Bath-sheba."],["Psalms",51,3,"Be gracious to me, O God, according to Thy steadfast love: according to the multitude of Thy tender mercies blot out my transgressions."],["Psalms",51,4,"Wash me thoroughly from my iniquity, and cleanse me from my sin."],["Psalms",51,5,"For I acknowledge my transgressions: and my sin is ever before me."],["Psalms",51,6,"Against Thee, Thee alone, have I sinned, and done that which is evil in Thy sight: so that Thou art justified in Thy sentence, and clear in Thy judgment."],["Psalms",51,7,"Behold, I was shaped in iniquity; and in sin did my mother conceive me."],["Psalms",51,8,"Behold, Thou desirest truth in the inward parts: therefore teach me wisdom in the inmost heart."],["Psalms",51,9,"Purge me with hyssop, and I shall be clean: wash me, and I shall be whiter than snow."],["Psalms",51,10,"Make me to hear joy and gladness: that the bones which Thou hast broken may rejoice."],["Psalms",51,11,"Hide Thy face from my sins, and blot out all my iniquities."],["Psalms",51,12,"Create in me a clean heart, O God and renew a steadfast spirit within me."],["Psalms",51,13,"Cast me not away from Thy presence; and take not Thy holy spirit from me."],["Psalms",51,14,"Restore to me the joy of Thy salvation; and uphold me with a willing spirit."],["Psalms",51,15,"Then I will teach transgressors Thy ways; and sinners shall return to Thee."],["Psalms",51,16,"Deliver me from bloodguiltiness, O God, Thou God of my salvation: and my tongue shall sing aloud of Thy righteousness."],["Psalms",51,17,"O Lord, open my lips; and my mouth shall rehearse Thy praise."],["Psalms",51,18,"For Thou desirest not sacrifice; or else I would give it: Thou delightest not in burnt offering."],["Psalms",51,19,"The sacrifices of God are a broken spirit: a broken and a contrite heart, O God, Thou wilt not despise."],["Psalms",51,20,"Do good in Thy favour to Zion: build Thou the walls of Jerusalem."],["Psalms",51,21,"Then shalt Thou be pleased with the sacrifices of righteousness, with burnt offering and whole burnt offering: then shall they offer bullocks upon Thy altar."],["Psalms",52,1,"To the chief Musician, A Maschil of David,"],["Psalms",52,2,"when Doeg the Edomite came and told Saul, and said to him, David is come to the house of Ahimelech."],["Psalms",52,3,"Why boastest thou thyself of evil, O mighty man? the love of God endures for all time."],["Psalms",52,4,"Thy tongue devises mischiefs; like a sharp razor, working deceitfully."],["Psalms",52,5,"Thou lovest evil more than good; and lying rather than speaking righteousness. (Selah.)"],["Psalms",52,6,"Thou lovest all devouring words, a deceitful tongue."],["Psalms",52,7,"God shall likewise destroy thee for ever, he shall take thee away, and pluck thee out of thy tent, and root thee out of the land of the living. (Selah.)"],["Psalms",52,8,"The righteous also shall see, and fear, and shall laugh at him:"],["Psalms",52,9,"lo, this is the man who made not God his strength; but trusted in the abundance of his riches, and strengthened himself in his wickedness."],["Psalms",52,10,"But I am like a green olive tree in the house of God: I trust in the love of God for ever and ever."],["Psalms",52,11,"I will give Thee thanks for ever, because Thou hast done it: and I will wait on Thy name, for it is good, before Thy saints."],["Psalms",53,1,"To the chief Musician on Mahalath, A Maschil of David."],["Psalms",53,2,"The fool has said in his heart, There is no God. They have acted corruptly, and they have done abominable iniquity: there is none that does good."],["Psalms",53,3,"God looked down from heaven upon the children of men, to see if there were any man of discernment, that did seek God."],["Psalms",53,4,"Is every one of them dross? are they altogether filthy? is there no one who does good? No, not even one."],["Psalms",53,5,"Have the workers of iniquity no knowledge, who eat up my people as they eat bread: and do not call upon God?"],["Psalms",53,6,"There were they in great fear, where no fear was: for God has scattered the bones of him that encamps against thee: thou hast put them to shame, because God has rejected them."],["Psalms",53,7,"Oh that the salvation of Israel were come out of Zion! When God brings back the captivity of his people, Jacob shall rejoice, and Israel shall be glad."],["Psalms",54,1,"To the chief Musician for strings, A Maschil of David,"],["Psalms",54,2,"when the Ziphim came and said to Saul, Does not David hide himself with us?"],["Psalms",54,3,"Save me, O God, by Thy name, and judge me by Thy strength."],["Psalms",54,4,"Hear my prayer, O God; give ear to the words of my mouth."],["Psalms",54,5,"For strangers are risen up against me, and violent men seek after my soul: they have not set God before them. (Selah.)"],["Psalms",54,6,"Behold, God is my helper: the Lord is the sustainer of my soul."],["Psalms",54,7,"He rewards evil to my enemies: O, cut them off in Thy truth."],["Psalms",54,8,"I will sacrifice a free will offering to Thee: I will praise Thy name, O Lord; for it is good."],["Psalms",54,9,"For he has delivered me out of all trouble: and my eye has gazed upon my enemies."],["Psalms",55,1,"To the chief Musician for strings, A Maschil of David."],["Psalms",55,2,"Give ear to my prayer, O God; and hide not Thyself from my supplication."],["Psalms",55,3,"Attend to me, and answer me: I sob in my complaint, and make moan;"],["Psalms",55,4,"because of the voice of the enemy, because of the oppression of the wicked: for they cast iniquity upon me, and in wrath they persecute me."],["Psalms",55,5,"My heart is sore pained within me: and the terrors of death are fallen upon me."],["Psalms",55,6,"Fearfulness and trembling are come upon me, and horror has overwhelmed me."],["Psalms",55,7,"And I said, Oh that I had wings like a dove! for then I would fly away, and be at rest."],["Psalms",55,8,"Lo, then I would wander far off, and remain in the wilderness. (Selah.)"],["Psalms",55,9,"I would hasten to find a refuge for myself from the windy storm and the tempest."],["Psalms",55,10,"Destroy, O Lord, and divide their tongues: for I have seen violence and strife in the city."],["Psalms",55,11,"Day and night they go about it upon its walls: mischief also and trouble are in the midst of it."],["Psalms",55,12,"Wickedness is in the midst of it: oppression and fraud depart not from her streets."],["Psalms",55,13,"For it was not an enemy who taunted me; then I could have borne it: nor was it one who hated me who did magnify himself against me; then I would have hid myself from him:"],["Psalms",55,14,"but it was Thou, a man my equal, my companion, and my familiar friend."],["Psalms",55,15,"We took sweet counsel together, and walked to the house of God in company."],["Psalms",55,16,"Let death spread its oblivion upon them, and let them go down alive into Sheol: for wickedness is in their dwellings, and among them."],["Psalms",55,17,"As for me, I will call upon God; and the Lord shall save me."],["Psalms",55,18,"Evening, and morning, and at noon, I pray, and cry aloud: and he hears my voice."],["Psalms",55,19,"He has delivered my soul in peace from the battle that was against me: for there were many who strove with me."],["Psalms",55,20,"God who is enthroned from olden time, shall hear and afflict them (Selah;) those who dread no changes, and do not fear God."],["Psalms",55,21,"He has put forth his hands against such as are at peace with him: he has broken his covenant."],["Psalms",55,22,"The words of his mouth were smoother than butter, but war was in his heart: his words were softer than oil, yet they were drawn swords."],["Psalms",55,23,"Cast thy burden upon the Lord, and he shall sustain thee: he shall never suffer the righteous to be moved."],["Psalms",55,24,"But Thou, O God, shalt bring them down into the pit of destruction: bloody and deceitful men shall not live out half their days; but I will trust in Thee."],["Psalms",56,1,"To the chief Musician, upon Jonath-elem-rechokim, A Michtam of David, when the Philistines seized him in Gath."],["Psalms",56,2,"Be gracious to me, O God: for men long to swallow me up; all day long the foeman oppresses me."],["Psalms",56,3,"My enemies daily long to swallow me up, for they are many who fight against me, O Thou most High."],["Psalms",56,4,"When I am afraid, I will trust in Thee."],["Psalms",56,5,"In God, I will praise his word, in God I have put my trust; I will not fear; what can flesh do to me?"],["Psalms",56,6,"Every day they wrest my words: all their thoughts are against me for evil."],["Psalms",56,7,"They gather themselves together, they hide themselves, they mark my steps, as they wait for my soul."],["Psalms",56,8,"Shall they escape by iniquity? in Thy anger cast down the peoples, O God."],["Psalms",56,9,"Thou dost count my wanderings: put my tears into Thy bottle: are they not in Thy book?"],["Psalms",56,10,"When I cry to Thee, then shall my enemies turn back: this I know; for God is for me."],["Psalms",56,11,"In God, I will praise his word: in the Lord, I will praise his word."],["Psalms",56,12,"In God have I put my trust: I will not be afraid. What can man do to me?"],["Psalms",56,13,"Thy vows are upon me, O God: I will pay Thee my offerings of thanksgiving."],["Psalms",56,14,"For Thou hast delivered my soul from death, yea, my feet from falling, that I may walk before God in the light of the living!"],["Psalms",57,1,"To the chief Musician, Al-taschith, a Michtam of David, when he fled from Saul in the cave."],["Psalms",57,2,"Be gracious to me, O God, be gracious to me: for my soul trusts in Thee: and in the shadow of Thy wings will I take refuge, until calamities be overpast."],["Psalms",57,3,"I will cry to God most high; to God who performs all things for me."],["Psalms",57,4,"He will send from heaven, and save me; he scorns him who would swallow me up. (Selah.) God shall send forth his steadfast love and his truth."],["Psalms",57,5,"My soul is among lions: and I lie down among those who are aflame, the sons of men, whose teeth are spears and arrows, and their tongue a sharp sword."],["Psalms",57,6,"Be Thou exalted, O God, above the heavens; let Thy glory be above all the earth."],["Psalms",57,7,"They have prepared a net for my steps; my soul is bowed down: they have dug a pit before me, into the midst of which they are fallen themselves. (Selah.)"],["Psalms",57,8,"My heart is steadfast, O God, my heart is steadfast: I will sing and give praise."],["Psalms",57,9,"Wake up, my glory; awake, the harp and the lyre: I will awake the dawn."],["Psalms",57,10,"I will praise Thee, O Lord, among the peoples: I will sing to Thee among the nations."],["Psalms",57,11,"For Thy love is great unto the heavens, and Thy truth to the clouds."],["Psalms",57,12,"Be Thou exalted, O God, above the heavens: let Thy glory be above all the earth."],["Psalms",58,1,"To the chief Musician, Al-taschith, A Michtam of David."],["Psalms",58,2,"Do you indeed speak righteousness in private? do you judge uprightly, O you sons of men?"],["Psalms",58,3,"No, in your hearts you work wickedness; your hands deal out violence on the earth."],["Psalms",58,4,"The wicked are estranged from the womb: they err from birth, speaking lies."],["Psalms",58,5,"Their poison is like the poison of a snake: they are like the deaf adder that stops its ear;"],["Psalms",58,6,"which will not hearken to the voice of charmers, charming never so wisely."],["Psalms",58,7,"Break their teeth, O God, in their mouth: break out the fangs of the young lions, O Lord."],["Psalms",58,8,"Let them melt away like waters which run continually: when he aims his arrows, let them be as if cut in pieces;"],["Psalms",58,9,"like the slimy track of a snail which disappears: like the untimely births of a woman, that have not seen the sun."],["Psalms",58,10,"Before your pots can feel the thorns, he shall sweep them away as with a whirlwind, both the green and the burning."],["Psalms",58,11,"The righteous shall rejoice when he sees the vengeance: he shall wash his feet in the blood of the wicked."],["Psalms",58,12,"So that a man shall say, Verily there is a reward for the righteous: verily there is a God who judges in the earth."],["Psalms",59,1,"To the chief Musician, Al-taschith, A Michtam of David; when Saul sent, and they watched the house to kill him."],["Psalms",59,2,"Deliver me from my enemies, O my God: defend me from those who rise up against me."],["Psalms",59,3,"Deliver me from the workers of iniquity, and save me from bloody men."],["Psalms",59,4,"For, lo, they lie in wait for my soul: fierce men are gathered against me; not for my transgression, nor for my sin, O Lord."],["Psalms",59,5,"They run and prepare themselves for no fault of mine: awake to help me, and behold."],["Psalms",59,6,"Thou therefore, O Lord God of hosts, the God of Israel, awake to punish all the nations: be not gracious to any wicked traitors. (Selah.)"],["Psalms",59,7,"They return at evening: they howl like a dog, and go round about the city."],["Psalms",59,8,"Behold, they belch out with their mouth: swords are in their lips: for who hears?"],["Psalms",59,9,"But Thou, O Lord, shalt laugh at them; Thou shalt have all the nations in derision."],["Psalms",59,10,"Upon Thee, O my strength, will I wait: for God is my fortress."],["Psalms",59,11,"God who loves me shall come to meet me: God shall let me gaze upon my enemies."],["Psalms",59,12,"Slay them not, lest my people forget: scatter them by Thy power; and bring them down, O Lord our shield."],["Psalms",59,13,"For the sin of their mouth and the words of their lips let them even be taken in their pride: and for cursing and lying which they speak."],["Psalms",59,14,"Consume them in wrath, consume them, that they may be no more: and let them know that God rules in Jacob to the ends of the earth. (Selah.)"],["Psalms",59,15,"And at evening let them return; and let them howl like a dog, and go round about the city."],["Psalms",59,16,"Let them wander up and down for food, and murmur if they have not their fill."],["Psalms",59,17,"But I will sing of Thy power; yea, I will sing aloud of Thy steadfast love in the morning: for Thou hast been my defence and refuge in the day of my distress."],["Psalms",59,18,"To Thee, O my strength, will I sing: for God is my fortress, and the God who loves me."],["Psalms",60,1,"To the chief Musician upon Shushan-eduth, A Michtam of David, to teach;"],["Psalms",60,2,"when he strove with Mesopotamia and with Aram-zobah, and Joab returned, and smote twelve thousand of Edom in the valley of salt."],["Psalms",60,3,"O God, Thou hast cast us off, Thou hast shattered us, Thou hast been angry; O turn Thyself to us again."],["Psalms",60,4,"Thou hast made the earth to tremble; Thou hast broken it: heal its breaches; for it totters."],["Psalms",60,5,"Thou hast shown Thy people hard things: Thou hast made us drink the wine of staggering."],["Psalms",60,6,"Thou hast given a banner to those who fear Thee, that it may be displayed because of the truth. (Selah.)"],["Psalms",60,7,"That Thy beloved ones may be delivered; save with Thy right hand, and answer me."],["Psalms",60,8,"God has spoken in his holiness; I will rejoice, I will divide Shechem, and measure out the valley of Succoth."],["Psalms",60,9,"Gilead is mine, and Manasseh is mine; Ephraim also is the strength of my head; Judah is my sceptre;"],["Psalms",60,10,"Moab is my washpot; over Edom will I cast my shoe: Philistia, cry aloud because of me."],["Psalms",60,11,"Who will bring me into the strong city? who will lead me into Edom?"],["Psalms",60,12,"Hast thou not rejected us, O God? so that Thou goest not forth, O God, with our hosts."],["Psalms",60,13,"Give us help against the foe: for vain is the help of man."],["Psalms",60,14,"Through God we shall do valiantly: for he it is who will tread down our enemies."],["Psalms",61,1,"To the chief Musician, on strings, Of David."],["Psalms",61,2,"Hear my cry, O God; attend to my prayer."],["Psalms",61,3,"From the end of the earth I will cry to Thee, when my heart faints. lead me to the rock that is too high for me."],["Psalms",61,4,"For Thou hast been a shelter for me, and a strong tower from the enemy."],["Psalms",61,5,"I will abide in Thy tent for ever: I will trust in the covert of Thy wings. (Selah.)"],["Psalms",61,6,"For Thou, O God, hast heard my vows: Thou hast granted the heritage of those who fear Thy name."],["Psalms",61,7,"Prolong the king's life: may his years be as many generations."],["Psalms",61,8,"May he be enthroned before God for ever: O appoint love and truth, that they may preserve him."],["Psalms",61,9,"So will I sing praise to Thy name for ever, as I perform my vows day by day."],["Psalms",62,1,"To the chief Musician, to Jeduthun, A Psalm of David."],["Psalms",62,2,"My soul waits in silence only for God: from him comes my salvation."],["Psalms",62,3,"He alone is my rock and my salvation; he is my fortress: I shall not be greatly moved."],["Psalms",62,4,"How long will you seek to overwhelm a man? You will be all of you demolished like a leaning wall, or a tottering fence."],["Psalms",62,5,"They even devise to thrust him down from his majesty: they delight in lies: they bless with their mouth, but they curse inwardly. (Selah.)"],["Psalms",62,6,"My soul waits in silence only for God; for my expectation is from him."],["Psalms",62,7,"He alone is my rock and my salvation: he is my defence; I shall not be moved."],["Psalms",62,8,"In God is my salvation and my glory: the rock of my strength, and my refuge, is in God."],["Psalms",62,9,"Trust in him at all times; you people, pour out your heart before him: God is a refuge for us. (Selah.)"],["Psalms",62,10,"Men of low degree are mere breath, and men of high degree are a lie: to be laid in the balance, they are altogether lighter than air."],["Psalms",62,11,"Trust not in oppression, and become not vain in robbery: if riches increase, set not your heart upon them."],["Psalms",62,12,"God has spoken once: twice have I heard this; that power belongs to God."],["Psalms",62,13,"But love is also Thine, when Thou renderest to every man according to his work."],["Psalms",63,1,"A Psalm of David, when he was in the wilderness of Judah."],["Psalms",63,2,"O God, Thou art my God; earnestly I seek Thee: my soul thirsts for Thee, my flesh longs for Thee in a dry and thirsty land, where no water is;"],["Psalms",63,3,"to see Thy power and Thy glory, as I have seen Thee in the sanctuary."],["Psalms",63,4,"Because Thy steadfast love is better than life, my lips shall praise Thee."],["Psalms",63,5,"Thus will I bless Thee while I live: I will lift up my hands in Thy name."],["Psalms",63,6,"My soul is satisfied as with marrow and fatness; and my mouth praises Thee with joyful lips:"],["Psalms",63,7,"when I remember Thee upon my bed, and meditate on Thee in the night watches."],["Psalms",63,8,"Because Thou hast been my help, therefore in the shadow of Thy wings I will rejoice."],["Psalms",63,9,"My soul clings to Thee: Thy right hand upholds me."],["Psalms",63,10,"But those who seek my soul, to destroy it, shall go into the lower parts of the earth."],["Psalms",63,11,"They shall be given over to the sword: they shall be a portion for foxes."],["Psalms",63,12,"But the king shall rejoice in God; everyone who swears by him shall glory: for the mouth of those who speak lies shall be stopped."],["Psalms",64,1,"To the chief Musician, A Psalm of David."],["Psalms",64,2,"Hear my voice, O God, in my prayer: preserve my life from fear of the enemy."],["Psalms",64,3,"Hide me from the secret council of the wicked; from the tumult of the workers of iniquity:"],["Psalms",64,4,"who have whetted their tongue like a sword, aimed their arrows of bitter words:"],["Psalms",64,5,"to shoot the innocent man in secret; suddenly do they shoot at him, and fear not."],["Psalms",64,6,"They encourage one another in an evil matter: they speak of laying snares secretly; they say, Who shall see them?"],["Psalms",64,7,"They search out iniquities; they accomplish a diligent search: for the inward thought of man, and the heart, is deep."],["Psalms",64,8,"But God shoots his arrow at them: suddenly their wounds are on them."],["Psalms",64,9,"So they make their own tongue a stumbling to themselves; all that see them shake the head."],["Psalms",64,10,"And all men are afraid, and they declare the work of God; for they wisely consider of his doing."],["Psalms",64,11,"The just man shall be glad in the Lord, and shall trust in him; and all the upright in heart shall glory."],["Psalms",65,1,"To the chief Musician, A Psalm of David, a Poem."],["Psalms",65,2,"Praise awaits Thee, O God, in Zion: and to Thee shall the vow be performed."],["Psalms",65,3,"O Thou that hearest prayer, to Thee shall all flesh come."],["Psalms",65,4,"Iniquities prevail against me: as for our transgressions, Thou shalt purge them away."],["Psalms",65,5,"Happy is the man whom Thou choosest, and causest to approach to Thee, that he may dwell in Thy courts: we will be satisfied with the goodness of Thy house, Thy holy temple."],["Psalms",65,6,"By terrible things in righteousness wilt Thou answer us, O God of our salvation; who art the confidence of all the ends of the earth, and of the farthest sea."],["Psalms",65,7,"Who by his strength places the mountains in position; who is girded with power:"],["Psalms",65,8,"who stills the noise of the seas, the roaring of their waves, and the tumult of the peoples."],["Psalms",65,9,"They also who dwell in the uttermost parts are afraid at Thy signs: Thou makest the outgoings of the morning and evening to rejoice."],["Psalms",65,10,"Thou visitest the earth, and waterest it: Thou greatly enrichest it with the river of God, which is full of water: Thou providest corn for them, for so Thou hast prepared it."],["Psalms",65,11,"Watering her furrows abundantly, settling her ridges: Thou makest it soft with showers: Thou blessest its growth."],["Psalms",65,12,"Thou crownest the year with Thy goodness; and Thy paths drop fatness."],["Psalms",65,13,"The pastures of the wilderness drop moisture: and the little hills rejoice on every side."],["Psalms",65,14,"The meadows are clothed with flocks; the valleys also are covered over with corn; they shout for joy, they also sing."],["Psalms",66,1,"To the chief Musician, A Poem, a Psalm. Make a joyful noise to God, all the earth:"],["Psalms",66,2,"sing to the glory of his name: make his praise glorious."],["Psalms",66,3,"Say to God, How terrible are Thy works! through the greatness of Thy power shall Thy enemies cringe before Thee."],["Psalms",66,4,"All the earth shall worship Thee, and shall sing to Thee; they shall sing to Thy name. (Selah.)"],["Psalms",66,5,"Come and see the works of God: terrible is his doing towards the children of men."],["Psalms",66,6,"He turned the sea into dry land: they went through the river on foot: there did we rejoice in him."],["Psalms",66,7,"He rules by his power forever; his eyes behold the nations: let not the rebellious exalt themselves. (Selah.)"],["Psalms",66,8,"O bless our God, you peoples, and make the voice of his praise to be heard:"],["Psalms",66,9,"who has kept our soul in life, and has not suffered our foot to be moved."],["Psalms",66,10,"For Thou, O God, hast tested us: Thou hast tried us, as silver is refined."],["Psalms",66,11,"Thou hast brought us into the net; Thou hast laid affliction upon our loins."],["Psalms",66,12,"Thou hast caused men to ride over our heads; we went through fire and through water: but Thou didst bring us out into abundance."],["Psalms",66,13,"I will go into Thy house with burnt offerings: I will pay Thee my vows,"],["Psalms",66,14,"which my lips have uttered, and my mouth has spoken, when I was in trouble."],["Psalms",66,15,"I will offer unto Thee burnt sacrifices of fatlings, with the sweet smoke of rams; I will offer bullocks with goats. (Selah.)"],["Psalms",66,16,"Come and hear, all you that fear God, and I will declare what he has done for my soul."],["Psalms",66,17,"I cried to him with my mouth, and he was extolled with my tongue."],["Psalms",66,18,"If I had looked on wickedness with my heart, the Lord would not have heard:"],["Psalms",66,19,"but verily God has heard me; he has attended to the voice of my prayer."],["Psalms",66,20,"Blessed be God, who has not turned away my prayer, nor removed his steadfast love from me."],["Psalms",67,1,"To the chief Musician on strings, A Psalm, a Poem."],["Psalms",67,2,"God be gracious to us, and bless us; and cause his face to shine upon us; (Selah.)"],["Psalms",67,3,"that Thy way may be known upon earth, Thy salvation among all nations."],["Psalms",67,4,"Let the peoples praise Thee, O God; let all the peoples give thanks to Thee."],["Psalms",67,5,"O let the nations be glad and sing for joy: for Thou shalt judge the peoples with equity, and govern the nations upon earth. (Selah.)"],["Psalms",67,6,"Let the peoples praise Thee, O God; let all the peoples give Thee thanks."],["Psalms",67,7,"The earth has yielded her increase; and God, our own God, shall bless us."],["Psalms",67,8,"God shall bless us; and let all the ends of the earth fear him."],["Psalms",68,1,"To the chief Musician, A Psalm, a Poem of David."],["Psalms",68,2,"Let God arise, let his enemies be scattered: and let those who hate him flee before him."],["Psalms",68,3,"As smoke is driven away, so drive them away: as wax melts before the fire, so let the wicked perish at the presence of God."],["Psalms",68,4,"But let the righteous be glad; let them rejoice before God: and let them joyfully exult."],["Psalms",68,5,"Sing to God, sing praises to his name: extol him who rides upon the clouds; Jah is his name: and rejoice before him."],["Psalms",68,6,"A father of the fatherless, and a judge of widows, is God in his holy habitation."],["Psalms",68,7,"God makes the lonely ones dwell in a house: he brings out the prisoners into prosperity; but the rebellious dwell in a parched land."],["Psalms",68,8,"O God, when Thou didst go out before Thy people, when Thou didst march through the wilderness; (Selah;)"],["Psalms",68,9,"the earth shook, the heavens also dropped at the presence of God: even Sinai itself at the presence of God, the God of Israel."],["Psalms",68,10,"Thou, O God, didst send a plentiful rain, whereby Thou didst strengthen Thy inheritance, when it languished."],["Psalms",68,11,"Thy flock found a dwelling in it: Thou, O God, preparest of Thy goodness for the poor."],["Psalms",68,12,"The Lord gives the word: great is the company of those who bear the tidings."],["Psalms",68,13,"Kings of armies flee, they flee: and she who dwells in the house divides the spoil."],["Psalms",68,14,"When you lie among the sheep folds you shall shine as the wings of a dove covered with silver, and her pinions with yellow gold."],["Psalms",68,15,"When the Almighty scatters kings in it, snow falls in Zalmon."],["Psalms",68,16,"O mighty hill, O hill of Bashan; O high peaked hill, hill of Bashan:"],["Psalms",68,17,"why dost thou look askance, O high peaked hill, at the mountain which God has desired for his abode? truly the Lord will dwell there forever."],["Psalms",68,18,"The chariots of God are twice ten thousand, thousands upon thousands: the Lord is among them: Sinai in holiness!"],["Psalms",68,19,"Thou hast ascended on high, thou hast led captivity captive: thou hast received gifts from men; yea, from the rebellious also, that the Lord God might dwell there."],["Psalms",68,20,"Blessed be the Lord who day by day bears our burden. God is our salvation. (Selah.)"],["Psalms",68,21,"He That is our God is the God of salvations; and to God the Lord belong the issues of death."],["Psalms",68,22,"But God will smite through the head of his enemies, the hairy scalp of such as goes on still in his trespasses."],["Psalms",68,23,"The Lord said, I will bring back from Bashan, I will bring them back from the depths of the sea:"],["Psalms",68,24,"that thy foot may wade in blood; and the tongue of thy dogs have its portion of thy enemies."],["Psalms",68,25,"They see Thy processions, O God; the processions of my God, my King, in the sanctuary."],["Psalms",68,26,"The singers go before, the players on instruments follow after; among them are maidens beating tambourines."],["Psalms",68,27,"Bless God in the congregations, the Lord, from the fountain of Israel."],["Psalms",68,28,"There is Benjamin, the youngest, ruling them, the princes of Judah, their council, the princes of Zebulun, and the princes of Naphtali."],["Psalms",68,29,"Thy God has commanded thy strength: strengthen, O God, that which Thou hast wrought for us,"],["Psalms",68,30,"out of Thy temple at Jerusalem, whither kings shall bring Thee gifts."],["Psalms",68,31,"Rebuke the wild beast of the reed grass, the company of bulls with the calves of the peoples, who seek to ingratiate themselves with pieces of silver; the prodigality of nations desiring to approach Thee."],["Psalms",68,32,"Nobles shall come out of Egypt; Ethiopia shall soon stretch out her hands to God."],["Psalms",68,33,"Sing to God, you kingdoms of the earth; O sing praise to the Lord; (Selah;)"],["Psalms",68,34,"to him that rides upon the heavens of heavens, which are of old; lo, he sends out his voice, a mighty voice."],["Psalms",68,35,"Ascribe strength to God: his majesty is over Israel, and his strength is in the clouds."],["Psalms",68,36,"O God, Thou art terrible out of Thy holy places: the God of Israel: he gives strength and power to his people. Blessed is God."],["Psalms",69,1,"To the chief Musician upon Shoshannim, Of David."],["Psalms",69,2,"Save me, O God; for the waters are come in to my soul."],["Psalms",69,3,"I sink in deep mire, where there is no standing: I am come into deep waters, and the flood overwhelms me."],["Psalms",69,4,"I am weary with my crying: my throat is dried: my eyes fail while I wait for my God."],["Psalms",69,5,"They who hate me without cause are more than the hairs of my head: they who would destroy me are many, who hate me wrongfully."],["Psalms",69,6,"What I took not away, that must I restore. O God, Thou knowst my folly; and my sins are not hid from Thee."],["Psalms",69,7,"Let not those who wait on Thee, O Lord God of hosts, be ashamed for my sake: let not those who seek Thee be confounded for my sake, O God of Israel."],["Psalms",69,8,"Because for Thy sake I have borne insult; confusion has covered my face."],["Psalms",69,9,"I am become a stranger to my brothers, and an alien to my mother's children."],["Psalms",69,10,"For the zeal of Thy house has eaten me up; and the taunts of those who taunt Thee are fallen upon me."],["Psalms",69,11,"When I wept, and chastened my soul with fasting, that became a reproach to me."],["Psalms",69,12,"I made sackcloth also my garment; and I became a proverb to them."],["Psalms",69,13,"They who sit in the gate talk of me; and I am the song of drunkards."],["Psalms",69,14,"But as for me, let my prayer be to Thee, O Lord, in an acceptable time: O God, in the greatness of Thy steadfast love hear me, in the truth of Thy salvation."],["Psalms",69,15,"Deliver me out of the mire, and let me not sink: let me be delivered from those who hate me, and out of the deep waters."],["Psalms",69,16,"Let not the waterflood overwhelm me, nor let the deep swallow me up, and let not the pit shut her mouth upon me."],["Psalms",69,17,"Hear me, O Lord; for Thy love is good: turn towards me according to the multitude of Thy compassion."],["Psalms",69,18,"And hide not Thy face from Thy servant; for I am in trouble: answer me speedily."],["Psalms",69,19,"Draw near to my soul, and redeem it: ransom me because of my enemies."],["Psalms",69,20,"Thou knowst my reproach, and my shame, and my dishonour: my adversaries are all before Thee."],["Psalms",69,21,"Insult has broken my heart; and I am sick: and I looked for some to take pity, but there was none; and for comforters, but I found none."],["Psalms",69,22,"And they gave me poison in my food; and for my thirst they gave me vinegar to drink."],["Psalms",69,23,"Let their table become a snare before them: and when they are at peace, let it be a trap."],["Psalms",69,24,"Let their eyes be darkened, that they see not; and make their loins continually to shake."],["Psalms",69,25,"Pour out Thy indignation upon them, and let Thy fierce anger overtake them."],["Psalms",69,26,"Let their habitation be desolate; let none dwell in their tents."],["Psalms",69,27,"For they persecute him whom Thou hast smitten; and they tell of the pain of those whom Thou hast wounded."],["Psalms",69,28,"Add iniquity to their iniquity: and let them not be admitted to Thy vindication."],["Psalms",69,29,"Let them be blotted out of the book of the living, and not be written with the righteous."],["Psalms",69,30,"But I am afflicted and in pain: let thy salvation, O God, set me on high."],["Psalms",69,31,"I will praise the name of God with a song, and will magnify him with thanksgiving."],["Psalms",69,32,"And it shall please the Lord better than an ox or a bullock that has horns and hoofs."],["Psalms",69,33,"The humble shall see this, and be glad: and let your hearts revive, you who seek God."],["Psalms",69,34,"For the Lord hears the poor, and despises not his prisoners."],["Psalms",69,35,"Let the heaven and earth praise him, the seas, and everything that moves therein."],["Psalms",69,36,"For God will save Zion, and will build the cities of Judah: that they may dwell there, and have it in possession."],["Psalms",69,37,"The seed also of his servants shall inherit it: and they that love his name shall dwell there."],["Psalms",70,1,"To the chief Musician, of David, for invocation."],["Psalms",70,2,"Make haste, O God, to deliver me; to help me, O Lord."],["Psalms",70,3,"Let them be ashamed and confounded who seek after my soul: let them be turned backward, and put to confusion, who desire my hurt."],["Psalms",70,4,"Let them be turned back because of their shame who say, Aha, aha."],["Psalms",70,5,"Let all those who seek Thee rejoice and be glad in Thee: and let such as love Thy salvation say continually, Let God be magnified."],["Psalms",70,6,"But I am poor and needy: make haste to me, O God: Thou art my help and my deliverer; delay not, O Lord."],["Psalms",71,1,"In thee, O Lord, do I take refuge: let me never be put to confusion."],["Psalms",71,2,"Deliver me in Thy righteousness, and cause me to escape: incline Thy ear to me, and save me."],["Psalms",71,3,"Be Thou my strong habitation, to which I may continually resort; which Thou hast appointed to save me; for Thou art my rock and my fortress."],["Psalms",71,4,"Deliver me, O my God, out of the hand of the wicked man, out of the hand of the unrighteous and violent man."],["Psalms",71,5,"For Thou art my hope, O Lord God: Thou art my trust from my youth."],["Psalms",71,6,"By Thee have I been sustained from the womb: Thou art he who took me out of my mother's bowels: my praise is continually of Thee."],["Psalms",71,7,"I am as a marvel to many; but Thou art my strong refuge."],["Psalms",71,8,"Let my mouth be filled with Thy praise and with Thy glory all the day."],["Psalms",71,9,"Cast me not off in the time of old age; forsake me not when my strength fails me."],["Psalms",71,10,"For my enemies speak against me; and they who watch for my soul take counsel together,"],["Psalms",71,11,"saying, God has forsaken him: pursue and catch him; for there is none to deliver him."],["Psalms",71,12,"O God, be not far from me: O my God, make haste to help me."],["Psalms",71,13,"Let them be confounded and consumed who are adversaries to my soul; let them be covered with reproach and dishonour who seek my hurt."],["Psalms",71,14,"But as for me, I will hope continually, and will praise Thee yet more and more."],["Psalms",71,15,"My mouth shall rehearse Thy righteousness and Thy salvation all the day; for I cannot count them."],["Psalms",71,16,"I will come to celebrate the mighty acts of the Lord God: I will make mention of Thy righteousness, Thine alone."],["Psalms",71,17,"O God, Thou hast taught me from my youth: and I still declare Thy wondrous deeds."],["Psalms",71,18,"Now also when I am old and greyheaded, O God, forsake me not; until I have related Thy strength to this generation, and Thy power to everyone that is to come."],["Psalms",71,19,"Thy righteousness also, O God, reaches the high heavens, who hast done great things."],["Psalms",71,20,"O God, who is like Thee! Thou who hast shown me many and grievous troubles, restore me to life again, and bring me up again from the depths of the earth."],["Psalms",71,21,"Increase my greatness, and turn to comfort me."],["Psalms",71,22,"I too will praise Thee with the harp, speaking of Thy truth, O my God: to Thee will I sing with the lyre, O Thou Holy One of Israel."],["Psalms",71,23,"My lips shall greatly rejoice when I sing to Thee; and my soul, which Thou hast redeemed."],["Psalms",71,24,"My tongue also shall tell of Thy righteousness all the day long: for they are confounded, for they are brought to shame, who seek my hurt."],["Psalms",72,1,"For Solomon. Give the king Thy judgments, O God, and Thy righteousness to the king's son."],["Psalms",72,2,"That he may judge Thy people with righteousness, and Thy poor with justice."],["Psalms",72,3,"Let the mountains bring peace to the people, and the hills, by righteousness."],["Psalms",72,4,"May he judge the cause of the poor of the people, may he save the children of the needy, and break the oppressor in pieces."],["Psalms",72,5,"May they fear Thee as long as the sun and moon endure, throughout all generations."],["Psalms",72,6,"May he come down like rain upon the mown grass: like showers that water the earth."],["Psalms",72,7,"In his days let the righteous flourish; and let there be abundance of peace till the moon is no more."],["Psalms",72,8,"May he have dominion also from sea to sea, and from the river to the ends of the earth."],["Psalms",72,9,"Let them who dwell in the wilderness bow down before him, and his enemies lick the dust."],["Psalms",72,10,"May the kings of Tarshish and of the isles bring presents: let the kings of Seba and Sheba offer gifts."],["Psalms",72,11,"And may all kings fall down before him; all nations serve him."],["Psalms",72,12,"For he shall deliver the needy when he cries; the poor also, and him who has no helper."],["Psalms",72,13,"He will spare the poor and needy, and shall save the souls of the needy."],["Psalms",72,14,"He will redeem their soul from deceit and violence: and precious shall their blood be in his sight."],["Psalms",72,15,"Long may he live, and may the gold of Sheba be given to him: and let prayer be continually offered for him: let them bless him all the day."],["Psalms",72,16,"May there be abundance of corn in the land: may it rustle on the tops of the mountains: may its fruit be like the Lebanon: and may they flourish in the city like the grass of the earth."],["Psalms",72,17,"May his name endure forever: may his name continue as long as the sun: and may men bless themselves by him: let all nations call him happy!"],["Psalms",72,18,"Blessed be the Lord God, the God of Israel, who does wondrous things alone."],["Psalms",72,19,"And blessed be his glorious name for ever: and let the whole earth be filled with his glory; Amen, and Amen."],["Psalms",72,20,"The prayers of David the son of Jesse are ended."],["Psalms",73,1,"A Psalm of Asaph. Truly God is good to Israel, to such as are of a clean heart."],["Psalms",73,2,"But as for me, my feet were almost gone; my steps had well nigh slipped."],["Psalms",73,3,"For I was envious of the arrogant, when I saw the prosperity of the wicked."],["Psalms",73,4,"For there are no pangs at their death; their body is firm."],["Psalms",73,5,"They are not in trouble as other men; nor are they plagued like other men."],["Psalms",73,6,"Therefore pride is their necklace; violence covers them like a garment."],["Psalms",73,7,"Their eyes stand out with fatness: they have more than heart could wish."],["Psalms",73,8,"They deride, and wickedly speak oppression: they speak loftily."],["Psalms",73,9,"They set their mouth against the heavens, and their tongue struts through the earth."],["Psalms",73,10,"Therefore his people return here: and abundant waters are drained out by them."],["Psalms",73,11,"And they say, How does God know? and is there knowledge in the most High?"],["Psalms",73,12,"Behold, these are the wicked, always at ease; they increase in riches."],["Psalms",73,13,"Surely I have cleansed my heart in vain, and washed my hands in innocency;"],["Psalms",73,14,"for all the day I have been stricken, and chastised every morning."],["Psalms",73,15,"If I had said, I will speak thus; behold, I should have offended against the generation of Thy children."],["Psalms",73,16,"So I pondered how I might understand this, but it was too wearisome for me."],["Psalms",73,17,"Until I entered the sanctuary of God; then I understood their end."],["Psalms",73,18,"Surely Thou dost set them in slippery places: Thou dost cast them down into destruction."],["Psalms",73,19,"How are they brought into desolation in a moment! they are utterly consumed with terrors."],["Psalms",73,20,"As a dream when one awakes; so, O Lord, on awaking, Thou shalt despise their image."],["Psalms",73,21,"When my heart was embittered, and I was pricked in my reins;"],["Psalms",73,22,"then I was foolish and ignorant: I was like a beast before Thee."],["Psalms",73,23,"But I am continually with Thee: Thou holdest my right hand."],["Psalms",73,24,"Thou shalt guide me with Thy counsel, and afterwards receive me to honourable state."],["Psalms",73,25,"Whom have I in heaven but Thee? and there is none upon earth that I desire beside Thee."],["Psalms",73,26,"My flesh and my heart fail: but God is the strength of my heart, and my portion for ever."],["Psalms",73,27,"For, lo, they that are far from Thee shall perish: Thou hast destroyed all those who go astray from Thee."],["Psalms",73,28,"But as for me, the nearness of God is my good: I have made the Lord God my refuge, that I may relate all Thy works."],["Psalms",74,1,"A Maschil of Asaph. O God, why hast Thou cast us off for ever? why does Thy anger smoke against the sheep of Thy pasture?"],["Psalms",74,2,"Remember Thy congregation, which Thou hast purchased of old; the tribe of Thy inheritance, which Thou hast redeemed; this mount Zion, wherein Thou hast dwelt."],["Psalms",74,3,"Lift up Thy feet to the perpetual desolations; the enemy has destroyed everything in the sanctuary."],["Psalms",74,4,"Thy enemies roar in the midst of thy meeting place; they set up their signs for signs:"],["Psalms",74,5,"they are known as swingers of axes upwards in the thick forest:"],["Psalms",74,6,"and now they break down its carved work altogether with hatchet and with hammers."],["Psalms",74,7,"They have burned Thy sanctuary with fire, to the ground: they have defiled the dwelling place of Thy name."],["Psalms",74,8,"They have said in their hearts, Let us destroy them together: they have burned up all the meeting places of God in the land."],["Psalms",74,9,"We see not our signs: there is no longer a prophet: nor is there among us any that knows how long."],["Psalms",74,10,"O God, how long shall the adversary insult? shall the enemy blaspheme Thy name for ever?"],["Psalms",74,11,"Why dost Thou withdraw Thy hand, even Thy right hand? out of Thy bosom with it! destroy!"],["Psalms",74,12,"for God is my King of old, working salvation in the midst of the earth."],["Psalms",74,13,"Thou didst divide the sea by Thy strength: Thou didst break the heads of the sea monsters in the waters."],["Psalms",74,14,"Thou didst crush the heads of livyatan: thou didst give him for food to the desert people."],["Psalms",74,15,"Thou didst split open springs and wadis: Thou didst dry up the ever flowing streams."],["Psalms",74,16,"The day is Thine, the night also is Thine: Thou hast prepared the light and the sun."],["Psalms",74,17,"Thou hast set all the borders of the earth: Thou hast made summer and winter."],["Psalms",74,18,"Remember this, how the enemy has insulted the Lord, and how a base people have blasphemed Thy name."],["Psalms",74,19,"O deliver not the soul of Thy turtledove to the wild beast: forget not the congregation of Thy poor for ever."],["Psalms",74,20,"Look upon the covenant: for the dark places of the earth are full, the habitations of cruelty."],["Psalms",74,21,"O let not the oppressed return ashamed: let the poor and needy praise Thy name."],["Psalms",74,22,"Arise, O God, plead Thy own cause: remember how the foolish man insults Thee daily."],["Psalms",74,23,"Forget not the voice of Thy enemies: the tumult of those who rise up against Thee increases continually."],["Psalms",75,1,"To the chief Musician, Al-taschith, A Psalm of Asaph, A Poem."],["Psalms",75,2,"To Thee, O God, we give thanks; we give thanks; for Thy name is near; men declare Thy wondrous works."],["Psalms",75,3,"Surely I shall take the appointed time; I will judge with equity."],["Psalms",75,4,"When the earth and all its inhabitants are dissolved, I bear up the pillars of it. (Selah.)"],["Psalms",75,5,"I said to the arrogant, Deal not arrogantly! and to the wicked, Lift not the horn."],["Psalms",75,6,"Lift not your horn on high: speak not with an insolent neck."],["Psalms",75,7,"For judgment comes neither from the east, nor from the west, nor from the desert peaks:"],["Psalms",75,8,"but God is the judge: he puts one down, and sets up another."],["Psalms",75,9,"For in the hand of the Lord there is a cup, with foaming wine; it is full of mixture; and he pours out of the same: but its dregs, shall all the wicked of the earth drain and drink."],["Psalms",75,10,"But I will declare for ever; I will sing praises to the God of Jacob."],["Psalms",75,11,"All the horns of the wicked also will I cut off; but the horns of the righteous shall be exalted."],["Psalms",76,1,"To the chief Musician on strings, A Psalm of Asaph, A Poem."],["Psalms",76,2,"In Judah is God known: his name is great in Israel."],["Psalms",76,3,"In Salem also is his tabernacle, and his dwelling place is in Zion."],["Psalms",76,4,"There he broke the flashing arrows, the shield, and the sword, and the battle. (Selah.)"],["Psalms",76,5,"Thou art glorious and excellent, coming down from the mountains of prey."],["Psalms",76,6,"The stouthearted are bereft of reason, they have slept their sleep: and none of the men of might have found their hands."],["Psalms",76,7,"At Thy rebuke, O God of Jacob, he is put to sleep, together with chariot and horse."],["Psalms",76,8,"Thou, even Thou, art to be feared: and who may stand in Thy sight when once Thou art angry?"],["Psalms",76,9,"Thou didst cause judgment to be heard from heaven; the earth feared, and was still,"],["Psalms",76,10,"When God arose to judgment, to save all the humble of the earth. (Selah.)"],["Psalms",76,11,"Surely the wrath of man shall praise Thee: Thou wilt gird Thyself with the remainder of wrath."],["Psalms",76,12,"Vow, and pay to the Lord your God: let all that be round about him bring presents to him that is to be feared."],["Psalms",76,13,"He shall cut off the spirit of princes: he is terrible to the kings of the earth."],["Psalms",77,1,"To the chief Musician, to Jeduthun, A Psalm of Asaph."],["Psalms",77,2,"To God I will cry aloud: aloud to God. O, hear me!"],["Psalms",77,3,"In the day of my trouble I sought the Lord: my hand is stretched out in the night, and rests not: my soul refuses to be comforted."],["Psalms",77,4,"I remember God, and moan: I meditate, and my spirit faints. (Selah.)"],["Psalms",77,5,"Thou holdest fast my eyelids: I am so troubled that I cannot speak."],["Psalms",77,6,"I have considered the days of old, the years of ancient times."],["Psalms",77,7,"I call to remembrance my song in the night: I meditate with my heart: and my spirit makes diligent search."],["Psalms",77,8,"Will the Lord cast off for ever? and will he be favourable no more?"],["Psalms",77,9,"Is his steadfast love clean gone forever? does his promise fail for evermore?"],["Psalms",77,10,"Has God forgotten to be gracious? has he in anger shut up his tender mercies? (Selah.)"],["Psalms",77,11,"And I said, I am sick at heart, for the right hand of the most High has changed."],["Psalms",77,12,"I will remember the works of the Lord: surely I will remember Thy wonders of old."],["Psalms",77,13,"I will meditate also on all Thy work, and muse on Thy doings."],["Psalms",77,14,"Thy way, O God, is in holiness: who is so great a God as our God?"],["Psalms",77,15,"Thou art the God That doest wonders: Thou hast declared Thy strength among the people."],["Psalms",77,16,"Thou hast with Thy arm redeemed Thy people, the sons of Jacob and Joseph. (Selah.)"],["Psalms",77,17,"The waters saw Thee, O God, the waters saw Thee: they were afraid: the depths also trembled."],["Psalms",77,18,"The clouds poured out water: the skies sent out a sound: Thy arrows also went abroad."],["Psalms",77,19,"The voice of Thy thunder was in the whirlwind: the lightnings lightened the world: the earth trembled and shook."],["Psalms",77,20,"Thy way was in the sea, and Thy path in the great waters, and Thy footsteps were not known."],["Psalms",77,21,"Thou didst lead Thy people like a flock by the hand of Moses and Aaron."],["Psalms",78,1,"A Maschil of Asaph. Give ear, O my people, to my law: incline your ears to the words of my mouth."],["Psalms",78,2,"I will open my mouth with a parable: I will utter riddles concerning ancient times:"],["Psalms",78,3,"of that which we have heard and known, and our fathers have told us."],["Psalms",78,4,"We will not hide them from their children, relating to the latter generation the praises of the Lord, and his strength, and his wonderful works that he has done."],["Psalms",78,5,"For he established a Testimony in Jacob, and appointed a law in Israel, which he commanded our fathers, that they should make them known to their children:"],["Psalms",78,6,"that the generation to come might know them, the children which should be born; who should arise and declare them to their children:"],["Psalms",78,7,"that they might set their hope in God, and not forget the works of God, but keep his commandments:"],["Psalms",78,8,"and that they might not be as their fathers, a stubborn and rebellious generation; a generation that set not their heart aright, and whose spirit was not steadfast with God."],["Psalms",78,9,"The children of Ephraim were as archers, carrying bows, who turned back in the day of battle."],["Psalms",78,10,"They kept not the covenant of God, and refused to follow his law;"],["Psalms",78,11,"and forgot his works, and his wonders that he had shown them."],["Psalms",78,12,"Marvellous things he did in the sight of their fathers, in the land of Egypt, in the field of Zoan."],["Psalms",78,13,"He divided the sea, and caused them to pass through; and he made the waters to stand like a heap."],["Psalms",78,14,"In the daytime also he led them with a cloud, and all the night with a light of fire."],["Psalms",78,15,"He split rocks in the wilderness, and gave them drink as out of the great depths."],["Psalms",78,16,"He brought streams also out of the rock, and caused waters to run down like rivers."],["Psalms",78,17,"And they sinned yet more against him, rebelling against the most High in the wilderness."],["Psalms",78,18,"And they tempted God in their heart by asking food for their craving."],["Psalms",78,19,"And they spoke against God; they said, Can God furnish a table in the wilderness?"],["Psalms",78,20,"Behold, he smote the rock, that the waters gushed out, and the streams overflowed; can he give bread also? can he provide meat for his people?"],["Psalms",78,21,"Therefore the Lord heard this, and was angry: so a fire was kindled against Jacob, and anger also came up against Israel;"],["Psalms",78,22,"because they believed not in God, and trusted not in his salvation:"],["Psalms",78,23,"though he commanded the clouds from above, and opened the doors of heaven,"],["Psalms",78,24,"and rained down manna upon them to eat, and gave them of the corn of heaven."],["Psalms",78,25,"Man ate the bread of angels: he sent them provision to the full."],["Psalms",78,26,"He caused an east wind to blow in the sky: and by his power he brought on the south wind."],["Psalms",78,27,"And he rained meat upon them like dust, and feathered birds like the sand of the sea:"],["Psalms",78,28,"and he let it fall in the midst of their camp, round about their habitations."],["Psalms",78,29,"So they did eat, and were well filled: for he gave them their own desire;"],["Psalms",78,30,"they were not yet sated with their lust: whilst their meat was still in their mouths,"],["Psalms",78,31,"the wrath of God came upon them, and slew the fattest of them, and smote down the young men of Israel."],["Psalms",78,32,"For all this they sinned still, and did not believe in his wondrous works."],["Psalms",78,33,"Therefore he ended their days with emptiness, and their years with trouble."],["Psalms",78,34,"When he slew them, then they sought him: and they returned and earnestly inquired after God."],["Psalms",78,35,"And they remembered that God was their rock, and the high God their redeemer."],["Psalms",78,36,"Nevertheless they did flatter him with their mouths, and they lied to him with their tongues."],["Psalms",78,37,"For their heart was not steadfast with him, neither were they faithful in his covenant."],["Psalms",78,38,"But he was full of compassion, forgiving iniquity, and he did not destroy them: often he turned away his anger, not stirring up all his wrath."],["Psalms",78,39,"For he remembered that they were but flesh; a wind that passes away, and comes not again."],["Psalms",78,40,"How often did they rebel against him in the wilderness, and grieve him in the desert!"],["Psalms",78,41,"They turned back also and tempted God, and pained the Holy One of Israel."],["Psalms",78,42,"They remembered not his hand, nor the day when he delivered them from the enemy."],["Psalms",78,43,"How he had wrought his signs in Egypt, and his wonders in the field of Zoan:"],["Psalms",78,44,"and had turned their canals into blood; and their floods, so that they could not drink."],["Psalms",78,45,"He sent swarms of gnats among them, which devoured them; and frogs, which destroyed them."],["Psalms",78,46,"He gave also their increase to the destroying locust, and their labour to the swarming locust."],["Psalms",78,47,"He destroyed their vines with hail, and their sycamore trees with frost."],["Psalms",78,48,"He gave over their cattle also to the hail, and their flocks to hot thunderbolts."],["Psalms",78,49,"He cast upon them the fierceness of his anger, wrath, and indignation, and trouble, an embassy of evil messengers."],["Psalms",78,50,"He levelled a path for his anger; he spared not their soul from death, but gave their life over to the pestilence;"],["Psalms",78,51,"and smote all the firstborn in Egypt; the first of their strength in the tents of Ham:"],["Psalms",78,52,"but made his own people to go out like sheep, and guided them in the wilderness like a flock."],["Psalms",78,53,"And he led them on safely, so that they feared not: but the sea overwhelmed their enemies."],["Psalms",78,54,"And he brought them to his holy border, to the mountain, which his right hand had purchased."],["Psalms",78,55,"He cast out nations before them, and apportioned to them an inheritance by line, and made the tribes of Israel to dwell in their tents."],["Psalms",78,56,"Yet they tempted and rebelled against the most high God, and kept not his testimonies:"],["Psalms",78,57,"but turned back, and dealt unfaithfully like their fathers: they were turned aside like a deceitful bow."],["Psalms",78,58,"For they provoked him to anger with their high places, and moved him to jealousy with their carved idols."],["Psalms",78,59,"When God heard this, he was wroth, and greatly abhorred Israel:"],["Psalms",78,60,"so that he forsook the tabernacle of Shiloh, the tent where he made his dwelling among men;"],["Psalms",78,61,"and delivered his strength into captivity, and his glory into the enemy's hand."],["Psalms",78,62,"He gave his people over also to the sword; and was wroth with his inheritance."],["Psalms",78,63,"The fire consumed their young men; and their virgins had no marriage song."],["Psalms",78,64,"Their priests fell by the sword; and their widows made no lamentation."],["Psalms",78,65,"Then the Lord awoke as one out of sleep, and like a mighty man that shouts by reason of wine."],["Psalms",78,66,"And he smote his enemies backward: he put upon them a perpetual reproach."],["Psalms",78,67,"And he rejected the tabernacle of Joseph, and chose not the tribe of Ephraim:"],["Psalms",78,68,"but chose the tribe of Judah, the mount Zion which he loved."],["Psalms",78,69,"And he built his sanctuary like the high heavens, like the earth which he has established for ever."],["Psalms",78,70,"And chose David his servant, and took him from the sheepfolds:"],["Psalms",78,71,"from following the ewes that gave suck, he brought him to be shepherd of Jacob his people, and Israel his inheritance."],["Psalms",78,72,"So he tended them according to the integrity of his heart; and guided them by the skilfulness of his hands."],["Psalms",79,1,"A Psalm of Asaph. O God, heathen nations are come into Thy inheritance; Thy holy temple they have defiled; they have laid Jerusalem in heaps."],["Psalms",79,2,"The dead bodies of Thy servants they have given to be food to the birds of the sky, the flesh of Thy pious ones to the beasts of the earth."],["Psalms",79,3,"Their blood have they shed like water round about Jerusalem; and there was none to bury them."],["Psalms",79,4,"We are become a taunt to our neighbours, a scorn and derision to those round about us."],["Psalms",79,5,"How long, Lord? wilt Thou be angry for ever? will Thy jealousy burn like fire?"],["Psalms",79,6,"Pour out Thy wrath upon the nations that do not know Thee, and upon the kingdoms that do not call upon Thy name."],["Psalms",79,7,"For they have devoured Jacob, and laid waste his dwelling place."],["Psalms",79,8,"O remember not against us former iniquities: let Thy tender mercies speedily come to meet us: for we are brought very low."],["Psalms",79,9,"Help us, O God of our salvation, for the glory of Thy name: and deliver us, and forgive our sins, for Thy name's sake."],["Psalms",79,10,"Why should the nations say, Where is their God? let the revenging of the blood of Thy servants which is shed be made manifest among the nations, and before our eyes."],["Psalms",79,11,"Let the groaning of the prisoners come before thee; according to the greatness of Thy power preserve a remnant of those who are appointed to die;"],["Psalms",79,12,"and render to our neighbours sevenfold into their bosom their insult, wherewith they have insulted Thee, O Lord."],["Psalms",79,13,"So we Thy people and the sheep of Thy pasture will give Thee thanks for ever: we will relate Thy praise to all generations."],["Psalms",80,1,"To the chief Musician upon Shoshannim, A Testimony, A Psalm of Asaph."],["Psalms",80,2,"Give ear, O shepherd of Israel, that leadest Joseph like flock, Thou who art enthroned upon the keruvim, shine forth."],["Psalms",80,3,"Before Ephraim, and Benjamin, and Manasseh, stir up Thy might, and come to save us."],["Psalms",80,4,"Restore us, O God, and cause Thy face to shine; and we shall be saved."],["Psalms",80,5,"O Lord God of hosts, how long wilt Thou be angry against the prayer of Thy people?"],["Psalms",80,6,"Thou hast fed them with the bread of tears; and hast given them tears to drink in great measure."],["Psalms",80,7,"Thou makest us a strife to our neighbours: and our enemies mock as they please."],["Psalms",80,8,"Restore us, O God of hosts, and cause Thy face to shine; and we shall be saved."],["Psalms",80,9,"Thou hast brought a vine out of Egypt, Thou hast cast out nations, and planted it."],["Psalms",80,10,"Thou didst clear a space for it, and didst cause it to take deep root, and it filled the land."],["Psalms",80,11,"The hills were covered with the shadow of it, and the mighty cedars with its boughs."],["Psalms",80,12,"She sent out her boughs to the sea, and her branches to the river."],["Psalms",80,13,"Why hast Thou then broken down her fences, so that all they who pass by the way do pluck her fruit?"],["Psalms",80,14,"The boar out of the wood ravages it, and the wild beast of the field devours it."],["Psalms",80,15,"Return, we beseech Thee, O God of hosts: look down from heaven, and behold, and be mindful of this vine;"],["Psalms",80,16,"and of the stock which Thy right hand has planted, and the branch that Thou madest strong for Thyself."],["Psalms",80,17,"It is burned with fire, it is cut down: they perish at the rebuke of Thy countenance."],["Psalms",80,18,"Let Thy hand be upon the man of Thy right hand, upon the son of a man whom Thou madest strong for Thyself."],["Psalms",80,19,"So shall we not turn back from Thee: revive us and we will call upon Thy name."],["Psalms",80,20,"Restore us, O Lord God of hosts, cause Thy face to shine; and we shall be saved."],["Psalms",81,1,"To the chief Musician upon the Gittith, Of Asaph."],["Psalms",81,2,"Sing aloud to God our strength: make a joyful noise to the God of Jacob."],["Psalms",81,3,"Raise a song, sound the timbrel, the sweet lyre, with the harp."],["Psalms",81,4,"Blow a shofar at the new moon, at the full moon on our feast day."],["Psalms",81,5,"For this is a statute for Israel, an ordinance of the God of Jacob."],["Psalms",81,6,"This he ordained in Joseph for testimony, when he went out over the land of Egypt. I heard the language of him whom I had not known, saying,"],["Psalms",81,7,"I removed his shoulder from the burden: his hands are freed from the basket."],["Psalms",81,8,"Thou didst call in trouble, and I delivered thee; I answered thee in the secret place of thunder: I proved thee at the waters of Meribah. (Selah.)"],["Psalms",81,9,"Hear, O my people, and I will testify against thee: O Israel, if thou wilt hearken to me:"],["Psalms",81,10,"there shall be no strange god among thee; nor shalt thou worship any foreign deity."],["Psalms",81,11,"I am the Lord thy God who brought thee out of the land of Egypt: open thy mouth wide, and I will fill it."],["Psalms",81,12,"But my people would not hearken to my voice; and Israel would none of me."],["Psalms",81,13,"So I let them go after the stubbornness of their hearts, that they might follow their own counsels."],["Psalms",81,14,"Oh that my people would hearken to me, and Israel would walk in my ways!"],["Psalms",81,15,"I would soon subdue their enemies, and turn my hand against their adversaries."],["Psalms",81,16,"Let the haters of the Lord cringe before him: and their punishment should last forever."],["Psalms",81,17,"But he would feed him with the finest of the wheat: and with honey out of the rock I will satisfy thee."],["Psalms",82,1,"A Psalm of Asaph. God stands in the congregation of God; he judges among the judges."],["Psalms",82,2,"How long will you judge unjustly, and respect the persons of the wicked? (Selah.)"],["Psalms",82,3,"Judge the cause of the poor and fatherless: vindicate the afflicted and needy."],["Psalms",82,4,"Deliver the poor and destitute: rescue them out of the hand of the wicked."],["Psalms",82,5,"They know not, nor do they understand; they walk on in darkness: all the foundations of the earth are shaken."],["Psalms",82,6,"I had said, You are angels, all of you sons of the most High;"],["Psalms",82,7,"Nevertheless, you shall die like a man, and fall as one man, O princes."],["Psalms",82,8,"Arise, O God, judge the earth: for Thou shalt possess all the nations."],["Psalms",83,1,"A Poem, A Psalm of Asaph."],["Psalms",83,2,"Do not keep silence, O God: do not hold Thy peace, and be still, O God."],["Psalms",83,3,"For lo, Thy enemies make a tumult: and they who hate Thee have lifted up the head."],["Psalms",83,4,"They take crafty counsel against Thy people, and consult against Thy hidden ones."],["Psalms",83,5,"They have said, Come, and let us cut them off from being a nation; that the name of Israel may be no more in remembrance."],["Psalms",83,6,"For they have consulted together with one consent: they are confederate against Thee:"],["Psalms",83,7,"the tents of Edom, and the Ishmaelites; of Moab, and the Hagarenes;"],["Psalms",83,8,"Gebal, and Ammon, and Amalek; Philistia with the inhabitants of Tyre;"],["Psalms",83,9,"Assyria also is joined with them: they are the strong arm of the children of Lot. (Selah.)"],["Psalms",83,10,"Do to them as to Midian; as to Sisera, as to Jabin, at the wadi of Kishon:"],["Psalms",83,11,"who perished at En-dor: they became like dung on the earth."],["Psalms",83,12,"Make their nobles like Oreb, and like Zeeb: and all their princes like Zebah, and Zalmunna:"],["Psalms",83,13,"who said, Let us seize for our possession the pastures of God."],["Psalms",83,14,"O my God, make them like the whirling chaff: like the stubble before the wind."],["Psalms",83,15,"As the fire burns a wood, and as the flame sets the mountains on fire;"],["Psalms",83,16,"so pursue them with thy tempest, and terrify them with thy storm."],["Psalms",83,17,"Fill their faces with shame; that they may seek thy name, O Lord."],["Psalms",83,18,"Let them be confounded and affrighted forever; and let them be put to shame, and perish:"],["Psalms",83,19,"that men may know that thou alone, whose name is the Lord, art the most high over all the earth."],["Psalms",84,1,"To the chief Musician upon the Gittith, A Psalm for the sons of Korah."],["Psalms",84,2,"How lovely are Thy dwelling places, O Lord of hosts!"],["Psalms",84,3,"My soul longs, indeed, it faints for the courts of the Lord: my heart and my flesh cry out for the living God."],["Psalms",84,4,"Even the sparrow has found a home, and the swallow a nest for herself, where she may lay her young. Thy altars, O Lord of hosts, my King, and my God –"],["Psalms",84,5,"happy are they who dwell in Thy house: they are ever praising thee. (Selah.)"],["Psalms",84,6,"Happy is the man whose strength is in Thee; in whose heart are Thy highways,"],["Psalms",84,7,"who, passing through the valley of Baca, turn in into a waterspring; moreover, the early rain covers it with blessings."],["Psalms",84,8,"They go from strength to strength, every one of them appears before God in Zion."],["Psalms",84,9,"O Lord God of hosts, hear my prayer: give ear, O God of Jacob. (Selah.)"],["Psalms",84,10,"Behold, O God, our shield, and look upon the face of Thy anointed."],["Psalms",84,11,"For a day in Thy courts is better than a thousand. I had rather be at the threshold in the house of my God, than dwell in the tents of wickedness."],["Psalms",84,12,"For the Lord God is a sun and shield: the Lord will give grace and honour: no good thing will he withhold from those who walk uprightly."],["Psalms",84,13,"O Lord of hosts, happy is the man who trusts in Thee."],["Psalms",85,1,"To the chief Musician, A Psalm for the sons of Korah."],["Psalms",85,2,"Lord, Thou hast been favourable to Thy land: Thou hast brought back the captivity of Jacob."],["Psalms",85,3,"Thou hast forgiven the iniquity of Thy people, Thou hast pardoned all their sin. (Selah.)"],["Psalms",85,4,"Thou hast withdrawn all Thy wrath: Thou hast turned from the fierceness of Thy anger."],["Psalms",85,5,"Restore us, O God of our salvation, and cause Thy anger towards us to cease."],["Psalms",85,6,"Wilt Thou be angry with us forever? Wilt Thou draw out Thy anger to all generations?"],["Psalms",85,7,"Wilt Thou not revive us again: that Thy people may rejoice in Thee?"],["Psalms",85,8,"Show us thy mercy, O Lord, and grant us Thy salvation."],["Psalms",85,9,"I will hear what God the Lord will speak: for he will speak peace to his people, and to his pious ones: but let them not turn back to folly."],["Psalms",85,10,"Surely his salvation is near to them who fear him; that glory may dwell in our land."],["Psalms",85,11,"Love and truth are met together; righteousness and peace have kissed each other."],["Psalms",85,12,"Truth will spring out of the earth; and righteousness will look down from heaven."],["Psalms",85,13,"The Lord moreover shall give that which is good; and our land shall yield its increase."],["Psalms",85,14,"Righteousness shall go before him, and walk in the way of his steps."],["Psalms",86,1,"A Prayer of David. Incline Thy ear, O Lord, hear me: for I am poor and needy."],["Psalms",86,2,"Preserve my soul; for I am godly: O Thou my God, save Thy servant who trusts in Thee."],["Psalms",86,3,"Be gracious to me, O Lord: for I cry to Thee daily."],["Psalms",86,4,"Rejoice the soul of Thy servant: for to Thee, O Lord, do I lift up my soul."],["Psalms",86,5,"For Thou, Lord, art good, and ready to forgive; and of bountiful love towards all those who call upon Thee."],["Psalms",86,6,"Give ear, O Lord, to my prayer; and attend to the voice of my supplications."],["Psalms",86,7,"On the day of my trouble I will call upon Thee: for Thou wilt answer me."],["Psalms",86,8,"Among the gods there is none like Thee, O Lord; nor are there any works like Thine."],["Psalms",86,9,"All nations whom Thou hast made shall come and prostrate themselves before Thee, O Lord; and shall glorify Thy name."],["Psalms",86,10,"For Thou art great, and doest wondrous things: Thou art God alone."],["Psalms",86,11,"Teach me Thy way, O Lord; I will walk in Thy truth: make my heart single to fear Thy name."],["Psalms",86,12,"I will thank Thee, O Lord my God, with all my heart: and I will glorify Thy name for evermore."],["Psalms",86,13,"For great is Thy steadfast love towards me: and Thou hast delivered my soul from the depths of Sheol."],["Psalms",86,14,"O God, the proud are risen against me, and the assembly of violent men have sought after my soul; and have not set Thee before them."],["Psalms",86,15,"But Thou, O Lord, art a God full of compassion, and gracious, longsuffering, and bountiful in love and truth."],["Psalms",86,16,"O turn to me, and have mercy upon me; give Thy strength to Thy servant, and save the son of Thy handmaid."],["Psalms",86,17,"Show me a sign for good; that they who hate me may see it, and be ashamed: because Thou, Lord, hast helped me, and comforted me."],["Psalms",87,1,"A Psalm for the sons of Korah, A Poem. His foundation is in the holy mountains."],["Psalms",87,2,"The Lord loves the gates of Zion more than all the dwellings of Jacob."],["Psalms",87,3,"Glorious things are spoken of thee, O city of God. (Selah.)"],["Psalms",87,4,"I will make mention of Rahab and Babylon to those who know me: behold Philistia, and Tyre, with Ethiopia, saying, Such a man was born there."],["Psalms",87,5,"But of Zion it shall be said, This and that man was born in her: and the highest himself shall establish her."],["Psalms",87,6,"The Lord shall record, when he registers the peoples, that this man was born there. (Selah.)"],["Psalms",87,7,"And singers and dancers alike, shall say, All my springs are in Thee."],["Psalms",88,1,"A Poem, A Psalm for the sons of Korah, to the chief Musician upon Mahalath Leannoth, A Maschil of Heman the Ezrahite."],["Psalms",88,2,"O Lord God of my salvation, when I cry in the night before Thee:"],["Psalms",88,3,"let my prayer come before Thee: incline Thy ear to my cry;"],["Psalms",88,4,"for my soul is sated with evils: and my life draws near to Sheol."],["Psalms",88,5,"I am reckoned with those who go down into the pit: I am like a man who has no strength:"],["Psalms",88,6,"free among the dead, like the slain that lie in the grave, whom Thou rememberest no more: and they are cut off from Thy hand."],["Psalms",88,7,"Thou hast laid me in the lowest pit, in darkness, in the deeps."],["Psalms",88,8,"Thy wrath lies hard upon me, and Thou dost overwhelm me with all Thy waves. (Selah.)"],["Psalms",88,9,"Thou hast put away my acquaintances far from me; Thou hast made me an abomination to them: I am shut up, and I cannot come out."],["Psalms",88,10,"My eye is dim by reason of affliction: Lord, I have called daily upon Thee, I have stretched out my hands to Thee."],["Psalms",88,11,"Wilt Thou show wonders to the dead? shall the shades arise and praise Thee? (Selah.)"],["Psalms",88,12,"Shall Thy steadfast love be reported in the grave? or Thy faithfulness in Abaddon?"],["Psalms",88,13,"Shall Thy wonders be known in the dark? and Thy righteousness in the land of forgetfulness?"],["Psalms",88,14,"But to Thee have I cried, O Lord; and in the morning shall my prayer attend Thee."],["Psalms",88,15,"Lord, why dost Thou cast off my soul? why dost Thou hide Thy face from me?"],["Psalms",88,16,"I am afflicted and close to death from my youth up. I suffer Thy terrors, I am numb."],["Psalms",88,17,"Thy fierce wrath goes over me; Thy terrors have cut me off."],["Psalms",88,18,"They come round about me daily like water; they compass me about together."],["Psalms",88,19,"Friend and companion hast Thou put far from me, my acquaintances are in darkness."],["Psalms",89,1,"A Maschil of Ethan the Ezrahite."],["Psalms",89,2,"I will sing of the steadfast love of the Lord for ever: with my mouth I will make known Thy faithfulness to all generations."],["Psalms",89,3,"For I have said, The world is built by love: Thou dost establish Thy faithfulness in the very heavens."],["Psalms",89,4,"I have made a covenant with my chosen, I have sworn to David my servant,"],["Psalms",89,5,"Thy seed will I establish for ever, and build up thy throne to all generations. (Selah.)"],["Psalms",89,6,"And the heavens shall praise Thy wonders, O Lord: Thy faithfulness also in the assembly of the holy ones."],["Psalms",89,7,"For who in the skies can be compared to the Lord? who among the sons of the mighty can be likened to the Lord?"],["Psalms",89,8,"A God dreaded in the great council of the holy ones, and had in reverence by all those round about him."],["Psalms",89,9,"O Lord God of hosts, O Lord, who is strong like Thee? and Thy faithfulness is round about Thee."],["Psalms",89,10,"Thou rulest the raging of the sea: when the waves thereof rise up, Thou stillest them."],["Psalms",89,11,"Thou hast trodden down Rahab like carrion; Thou hast scattered Thy enemies with Thy strong arm."],["Psalms",89,12,"The skies are Thine, the earth also is Thine: the world and the fulness thereof, Thou hast founded them."],["Psalms",89,13,"The north and the south, Thou hast created them: Tabor and Hermon shall rejoice in Thy name."],["Psalms",89,14,"Thou hast a mighty arm: strong is Thy hand, and high is Thy right hand."],["Psalms",89,15,"Righteousness and justice are the foundation of Thy throne: love and truth shall go before Thee."],["Psalms",89,16,"Happy is the people that know the joyful note: they shall walk, O Lord, in the light of Thy countenance."],["Psalms",89,17,"In Thy name they rejoice all the day: and in Thy righteousness they are exalted."],["Psalms",89,18,"For Thou art the glory of their strength: and in Thy favour our horn shall be exalted."],["Psalms",89,19,"For our shield belongs to the Lord; and our king to the Holy One of Israel."],["Psalms",89,20,"Then Thou didst speak in vision to Thy pious one, and didst say, I have laid help upon one that is mighty; have exalted one chosen out of the people."],["Psalms",89,21,"I have found David my servant; with my holy oil have I anointed him:"],["Psalms",89,22,"with whom my hand shall be established: my arm also shall strengthen him."],["Psalms",89,23,"The enemy shall not exact upon him; nor the son of wickedness afflict him."],["Psalms",89,24,"And I will beat down his foes before his face, and strike down those who hate him."],["Psalms",89,25,"But my faithfulness and my steadfast love shall be with him: and in my name shall his horn be exalted."],["Psalms",89,26,"I will set his hand also on the sea, and his right hand on the rivers."],["Psalms",89,27,"He shall cry to me, Thou art my father, my God, and the rock of my salvation."],["Psalms",89,28,"Also I will make him firstborn, the highest of the kings of the earth."],["Psalms",89,29,"I will keep my truth with him for evermore, and my covenant shall stand fast with him."],["Psalms",89,30,"His seed also will I make to endure for ever, and his throne like the days of heaven."],["Psalms",89,31,"If his children forsake my law, and walk not in my judgments;"],["Psalms",89,32,"if they break my statutes, and keep not my commandments;"],["Psalms",89,33,"then I will punish their transgression with the rod, and their iniquity with strokes."],["Psalms",89,34,"Nevertheless I will not utterly take my steadfast love from him, nor suffer my faithfulness to fail."],["Psalms",89,35,"My covenant I will not break, nor alter that which has issued from my lips."],["Psalms",89,36,"Once I have sworn by my holiness that I will not fail unto David."],["Psalms",89,37,"His seed shall endure for ever, and his throne shall be like the sun before me."],["Psalms",89,38,"It shall be established for ever like the moon, and the witness in the sky is sure. (Selah.)"],["Psalms",89,39,"But Thou hast cast off and rejected, Thou hast been angry with Thy anointed."],["Psalms",89,40,"Thou hast renounced the covenant of Thy servant: Thou hast profaned his crown to the ground."],["Psalms",89,41,"Thou hast broken down all his fences; Thou hast brought his strongholds to ruin."],["Psalms",89,42,"All that pass by the way plunder him: he is a taunt to his neighbours."],["Psalms",89,43,"Thou hast exalted the right hand of his adversaries; Thou hast made all his enemies rejoice."],["Psalms",89,44,"Thou hast also turned back the edge of his sword, and hast not made him to stand in the battle."],["Psalms",89,45,"Thou hast made his brightness to cease, and cast his throne down to the ground."],["Psalms",89,46,"The days of his youth Thou hast shortened: Thou hast covered him with shame. (Selah.)"],["Psalms",89,47,"How long, Lord? wilt Thou hide Thyself forever? shall Thy wrath burn like fire?"],["Psalms",89,48,"Remember how short my time is: for what nothingness hast Thou created all the sons of men!"],["Psalms",89,49,"What man is he that lives, and shall not see death, but shall deliver his soul from the power of Sheol? (Sheol.)"],["Psalms",89,50,"Lord, where are Thy former oaths of steadfast love which Thou didst make to David in Thy faithfulness?"],["Psalms",89,51,"Remember, Lord, the disgrace of Thy servants: how I bear in my bosom the insults of all the many peoples,"],["Psalms",89,52,"wherewith Thy enemies have insulted, O Lord; wherewith they have insulted the footsteps of Thy anointed."],["Psalms",89,53,"Blessed be the Lord for evermore. Amen, and Amen."],["Psalms",90,1,"A Prayer of Moses the man of God. Lord, Thou hast been our dwelling place in all generations."],["Psalms",90,2,"Before the mountains were brought forth, and before ever Thou hadst formed the earth and the world, even from everlasting to everlasting, Thou art God."],["Psalms",90,3,"Thou turnest man back to dust; and sayst, Return, you children of men."],["Psalms",90,4,"For a thousand years in Thy sight are but like yesterday when it is past, and like a watch in the night."],["Psalms",90,5,"Thou engulfest them; they are like sleepers; they are like the short lived grass in the morning."],["Psalms",90,6,"In the morning it flourishes, and fades; by evening it is withered and dry."],["Psalms",90,7,"For we are consumed by Thy anger, and by Thy wrath are we terrified."],["Psalms",90,8,"Thou hast set our iniquities before Thee, our secret sins in the light of Thy countenance."],["Psalms",90,9,"For all our days are passed away in Thy wrath: we spend our years like a tale that is told."],["Psalms",90,10,"The days of our years are seventy; or if by reason of special strength, eighty years; yet their pride is but trouble and wretchedness; it is soon cut off, and we fly away."],["Psalms",90,11,"Who knows the power of Thy anger? even according to Thy fear, so is Thy wrath."],["Psalms",90,12,"So teach us to number our days, that we may get a heart of wisdom."],["Psalms",90,13,"Return, O Lord, how long? and relent concerning Thy servants."],["Psalms",90,14,"O satisfy us in the morning with Thy steadfast love; that we may rejoice and be glad all our days."],["Psalms",90,15,"Make us glad according to the days wherein Thou hast afflicted us, and the years in which we have seen evil."],["Psalms",90,16,"Let Thy work appear to Thy servants, and Thy glory to their children."],["Psalms",90,17,"And let the beauty of the Lord our God be upon us: and establish the work of our hands upon us; O prosper it, the work of our hands."],["Psalms",91,1,"He that dwells in the secret place of the most High shall abide under the shadow of the Almighty."],["Psalms",91,2,"I will say of the Lord, who is my refuge and my fortress: (my God; in him will I trust,)"],["Psalms",91,3,"that he will deliver thee from the snare of the fowler, and from the noisome pestilence."],["Psalms",91,4,"He shall cover thee with his pinions, and under his wings shalt thou find refuge: his truth shall be thy shield and buckler."],["Psalms",91,5,"Thou shalt not be afraid of the terror by night; nor of the arrow that flies by day;"],["Psalms",91,6,"nor of the pestilence that walks in darkness; nor of the destruction that wastes at noonday."],["Psalms",91,7,"A thousand shall fall at thy side and ten thousand at thy right hand; but it shall not come near thee."],["Psalms",91,8,"Only with thy eyes shalt thou behold and see the recompense of the wicked; because Thou O Lord, art my refuge."],["Psalms",91,9,"Thou hast made the most High Thy habitation."],["Psalms",91,10,"No evil shall befall thee, nor shall any plague come near thy dwelling."],["Psalms",91,11,"For he shall give his angels charge over thee, to keep thee in all thy ways."],["Psalms",91,12,"They shall bear thee up in their hands, lest thou dash thy foot against a stone."],["Psalms",91,13,"Thou shalt tread upon the lion and adder: the young lion and the crocodile shalt thou trample under foot."],["Psalms",91,14,"Because he has set his delight upon me, therefore will I deliver him: I will set him on high, because he has known my name."],["Psalms",91,15,"He shall call upon me, and I will answer him: I will be with him in trouble; I will deliver him, and honour him."],["Psalms",91,16,"With long life I will satisfy him, and show him my salvation."],["Psalms",92,1,"A Psalm, A Poem for the Sabbath day."],["Psalms",92,2,"It is a good thing to give thanks to the Lord, and to sing praise to Thy name, O most High:"],["Psalms",92,3,"to relate Thy steadfast love in the morning, and Thy faithfulness every night,"],["Psalms",92,4,"upon an instrument of ten strings and upon the harp; to the melody of the lyre."],["Psalms",92,5,"For Thou, Lord, hast made me glad through Thy work: I will triumph in the works of Thy hands."],["Psalms",92,6,"O Lord, how great are Thy works! and Thy thoughts are very deep."],["Psalms",92,7,"A brutish man does not know; nor does a fool understand this."],["Psalms",92,8,"When the wicked spring like grass, and when all the workers of iniquity flourish; it is that they shall be destroyed forever:"],["Psalms",92,9,"but Thou, Lord, art most high for evermore."],["Psalms",92,10,"For, lo, Thy enemies, O Lord, for lo, Thy enemies shall perish; all the workers of iniquity shall be scattered."],["Psalms",92,11,"But my horn shalt Thou exalt like the horn of a wild ox: I shall be anointed with fresh oil."],["Psalms",92,12,"My eye has seen the downfall of my enemies, and my ears have heard the doom of the wicked who rise against me."],["Psalms",92,13,"The righteous man flourishes like the palm tree: he grows like a cedar in the Lebanon."],["Psalms",92,14,"Those that are planted in the house of the Lord shall flourish in the courts of our God."],["Psalms",92,15,"They still bring forth fruit in old age; they are fat and flourishing;"],["Psalms",92,16,"to declare that the Lord is upright: he is my rock, and there is no unrighteousness in him."],["Psalms",93,1,"The Lord reigns, he is clothed with majesty; the Lord is robed; he has girded himself with strength: the world also is established, that it cannot be moved."],["Psalms",93,2,"Thy throne is established of old: Thou art from everlasting."],["Psalms",93,3,"The floods have lifted up, O Lord, the floods have lifted up their voice; the floods lift up their roaring."],["Psalms",93,4,"The Lord on high is mightier than the noise of many waters, than the mighty waves of the sea."],["Psalms",93,5,"Thy testimonies are very sure: holiness becomes Thy house, O Lord, for length of days."],["Psalms",94,1,"O Lord God, to whom vengeance belongs; O God, to whom vengeance belongs, shine forth!"],["Psalms",94,2,"Lift up Thyself, Thou judge of the earth: render to the proud their recompense."],["Psalms",94,3,"Lord, how long shall the wicked, how long shall the wicked triumph?"],["Psalms",94,4,"How long shall they utter and speak hard things? and all the workers of iniquity boast themselves?"],["Psalms",94,5,"They crush Thy people, O Lord, and afflict Thy heritage."],["Psalms",94,6,"They slay the widow and the stranger, and murder the fatherless."],["Psalms",94,7,"Yet they say, The Lord shall not see, nor shall the God of Jacob regard it."],["Psalms",94,8,"Understand, you brutish among the people: and fools, when will you be wise?"],["Psalms",94,9,"He That planted the ear, shall he not hear? he That formed the eye, shall he not see?"],["Psalms",94,10,"He That chastises nations, shall he not correct? he That teaches man knowledge?"],["Psalms",94,11,"The Lord knows the thoughts of man, that they are vanity."],["Psalms",94,12,"Blessed is the man whom Thou dost chasten, O Lord, and teachest him out of Thy law,"],["Psalms",94,13,"that Thou mayst give him rest from the days of adversity, until the pit is dug for the wicked."],["Psalms",94,14,"For the Lord will not cast off his people, nor will he forsake his inheritance."],["Psalms",94,15,"But judgment shall return to righteousness: and all the upright in heart shall follow it."],["Psalms",94,16,"Who will rise up for me against the evildoers? who will stand up for me against the workers of iniquity?"],["Psalms",94,17,"Unless the Lord had been my help, my soul had soon dwelt in silence."],["Psalms",94,18,"When I said, My foot slips; Thy steadfast love, O Lord, held me up."],["Psalms",94,19,"When my cares within me were many, Thy comforts would cheer my soul."],["Psalms",94,20,"Shall the seat of iniquity, framing mischief by law, have fellowship with Thee?"],["Psalms",94,21,"They gather themselves together against the soul of the righteous, and condemn the innocent blood."],["Psalms",94,22,"But the Lord has become my defence; and my God, the rock of my refuge."],["Psalms",94,23,"And he brings upon them their own iniquity, and he cuts them off in their own wickedness; the Lord our God cuts them off."],["Psalms",95,1,"O Come, let us sing to the Lord: let us make a joyful noise to the rock of our salvation."],["Psalms",95,2,"Let us come before his presence with thanksgiving, and make a joyful noise to him with psalms."],["Psalms",95,3,"For the Lord is a great God, and a great King above all gods."],["Psalms",95,4,"In his hand are the deep places of the earth: the mountain peaks are his also."],["Psalms",95,5,"The sea is his, and he made it: and his hands formed the dry land."],["Psalms",95,6,"O come, let us worship and bow down: let us kneel before the Lord our maker;"],["Psalms",95,7,"for he is our God; and we are the people of his pasture, and the flock of his hand: today even, if you will only hearken to his voice!"],["Psalms",95,8,"Do not harden your hearts as in Meribah, as in the day of Massa in the wilderness:"],["Psalms",95,9,"when your fathers tempted me, proved me, even though they saw my deeds."],["Psalms",95,10,"Forty years long did I loathe this generation and I said, It is a people that errs in their heart, and that do not know my ways:"],["Psalms",95,11,"whereupon I swore in my anger that they should not enter into my rest."],["Psalms",96,1,"O Sing to the Lord a new song: sing to the Lord, all the earth."],["Psalms",96,2,"Sing to the Lord, bless his name; announce his salvation from day to day."],["Psalms",96,3,"Declare his glory among the nations, his wonders among all the peoples."],["Psalms",96,4,"For the Lord is great, and greatly to be praised: he is to be feared above all gods."],["Psalms",96,5,"For all the gods of the nations are idols: but the Lord made the heavens."],["Psalms",96,6,"Honour and majesty are before him: strength and beauty are in his sanctuary."],["Psalms",96,7,"Ascribe to the Lord, O families of the peoples, ascribe to the Lord glory and strength."],["Psalms",96,8,"Ascribe to the Lord the glory due to his name: bring an offering, and come into his courts."],["Psalms",96,9,"O worship the Lord in the beauty of holiness: tremble before him, all the earth."],["Psalms",96,10,"Say among the nations that the Lord reigns: the world also is established so that it shall not be moved: he shall judge the people with equity."],["Psalms",96,11,"Let the heavens rejoice, and let the earth be glad; let the sea roar, and the fulness thereof;"],["Psalms",96,12,"let the field be joyful, and all that is in it: then shall all the trees of the wood sing for joy."],["Psalms",96,13,"Before the Lord: for he comes, for he comes to judge the earth: he shall judge the world in righteousness, and the people in his faithfulness."],["Psalms",97,1,"The Lord reigns; let the earth rejoice; let the multitude of isles be glad."],["Psalms",97,2,"Clouds and darkness are round about him: righteousness and judgment are the foundation of his throne."],["Psalms",97,3,"A fire goes before him, and burns up his enemies round about."],["Psalms",97,4,"His lightnings lightened the world: the earth saw, and trembled."],["Psalms",97,5,"The hills melted like wax at the presence of the Lord, at the presence of the Lord of the whole earth."],["Psalms",97,6,"The heavens declared his righteousness, and all the peoples saw his glory."],["Psalms",97,7,"Confounded be all they who serve carved idols, who boast themselves of idols: bow down before him, all you gods."],["Psalms",97,8,"Zion heard, and was glad; and the daughters of Judah rejoiced because of Thy judgments, O Lord."],["Psalms",97,9,"For Thou, Lord, art high above all the earth: Thou art exalted far above all gods."],["Psalms",97,10,"You that love the Lord, hate evil! he preserves the souls of his pious ones; he delivers them out of the hand of the wicked."],["Psalms",97,11,"Light is sown for the righteous, and gladness for the upright in heart."],["Psalms",97,12,"Rejoice in the Lord, O you righteous; and give thanks to his holy name."],["Psalms",98,1,"A Psalm. O sing to the Lord a new song; for he has done marvellous things: his right hand, and his holy arm have gained him the victory."],["Psalms",98,2,"The Lord has made known his salvation: his righteousness he has revealed in the sight of the nations."],["Psalms",98,3,"He has remembered his love and his truth towards the house of Israel: all the ends of the earth have seen the salvation of our God."],["Psalms",98,4,"Make a joyful noise to the Lord, all the earth: make a loud noise, and rejoice, and sing praise."],["Psalms",98,5,"Sing to the Lord with the lyre; with the lyre, and the voice of psalm."],["Psalms",98,6,"With trumpets and sound of a shofar make a joyful noise before the Lord, the King."],["Psalms",98,7,"Let the sea roar, and the fulness thereof; the world, and they who dwell therein."],["Psalms",98,8,"Let the rivers clap their hands: let the mountains sing for joy together."],["Psalms",98,9,"Before the Lord; for he comes to judge the earth: with righteousness shall he judge the world, and the people with equity."],["Psalms",99,1,"The Lord reigns; let the peoples tremble: he is enthroned upon the keruvim; let the earth be moved."],["Psalms",99,2,"The Lord is great in Zion; and he is high above all the peoples."],["Psalms",99,3,"Let them praise Thy great and terrible name; for it is holy."],["Psalms",99,4,"O mighty king, who loves justice, Thou hast established equity; Thou dost execute justice and righteousness in Jacob."],["Psalms",99,5,"Exalt the Lord our God, and worship at his footstool; for he is holy."],["Psalms",99,6,"Moses and Aaron among his priests, and Samuel among those who call upon his name; they called upon the Lord, and he answered them."],["Psalms",99,7,"He spoke to them in the cloudy pillar: they kept his testimonies, and the ordinance that he gave them."],["Psalms",99,8,"Thou didst answer them, O Lord our God: a forgiving God wast Thou to them, though Thou didst take vengeance for their misdeeds."],["Psalms",99,9,"Exalt the Lord our God, and worship at his holy hill; for the Lord our God is holy."],["Psalms",100,1,"A Psalm of thanksgiving. Make a joyful noise to the Lord, all the earth."],["Psalms",100,2,"Serve the Lord with gladness: come before his presence with singing."],["Psalms",100,3,"Know that the Lord he is God: it is he who made us, and we belong to him; we are his people, and the sheep of his pasture."],["Psalms",100,4,"Enter into his gates with thanksgiving, and into his courts with praise: be thankful to him, and bless his name."],["Psalms",100,5,"For the Lord is good; his steadfast love endures forever; and his faithfulness to all generations."],["Psalms",101,1,"A Psalm of David, I will sing of loyal love and justice: to Thee, O Lord, I will sing."],["Psalms",101,2,"I will celebrate with a Maschil psalm the way of integrity. O when wilt Thou come to me? I will walk within my house in the integrity of my heart."],["Psalms",101,3,"I will set no wicked thing before my eyes: I hate the work of those who turn aside; it shall not cleave to me."],["Psalms",101,4,"A perverse heart shall depart from me: I will know no evil matter."],["Psalms",101,5,"Whoever secretly slanders his neighbour, him I will cut off: him that has a high look and a proud heart I will not suffer."],["Psalms",101,6,"My eyes are upon the faithful of the land, that they may dwell with me: he that walks in the way of integrity, he shall serve me."],["Psalms",101,7,"He that works deceit shall not dwell within my house: he that tells lies shall not remain in my sight."],["Psalms",101,8,"Morning by morning I will destroy all the wicked of the land; that I may cut off all the evildoers from the city of the Lord."],["Psalms",102,1,"A Prayer of the afflicted, when he faints, and pours out his complaint before the Lord."],["Psalms",102,2,"Hear my prayer, O Lord, and let my cry reach Thee."],["Psalms",102,3,"Hide not Thy face from me in the day when I am in trouble; incline Thy ear to me: in the day when I call, answer me speedily."],["Psalms",102,4,"For my days are consumed like smoke, and my bones are burned like a hearth."],["Psalms",102,5,"My heart is smitten like grass, and withered; so that I forget how to eat my bread."],["Psalms",102,6,"By reason of the voice of my groaning, my bones cleave to my skin."],["Psalms",102,7,"I am like an owl of the wilderness: I am like a night flier of the desert."],["Psalms",102,8,"I watch, and am like a lonely sparrow upon the house top."],["Psalms",102,9,"My enemies insult me all the day; and they that are mad against me swear by me."],["Psalms",102,10,"For I have eaten ashes like bread, and mingled my drink with weeping,"],["Psalms",102,11,"because of Thy indignation and Thy wrath: for Thou hast lifted me up, and cast me down."],["Psalms",102,12,"My days are like an evening shadow; and I am withered like grass."],["Psalms",102,13,"But Thou, O Lord, sittest enthroned forever; and Thy name endures to all generations."],["Psalms",102,14,"Thou wilt arise, and have mercy upon Zion: for it is time to favour her; for the set time is come."],["Psalms",102,15,"For Thy servants hold her stones dear, and cherish her very dust."],["Psalms",102,16,"So the nations shall fear the name of the Lord, and all the kings of the earth Thy glory."],["Psalms",102,17,"For the Lord builds up Zion, he appears in his glory."],["Psalms",102,18,"He heeds the prayer of the destitute, and does not despise their prayer."],["Psalms",102,19,"This shall be written for the generation to come: so that a people yet unborn shall praise the Lord."],["Psalms",102,20,"For he has looked down from the height of his sanctuary; from heaven did the Lord behold the earth;"],["Psalms",102,21,"to hear the groaning of the prisoner; to loose those who are appointed to death;"],["Psalms",102,22,"that men may declare the name of Lord in Zion, and his praise in Jerusalem;"],["Psalms",102,23,"when the people are gathered together, and the kingdoms, to serve the Lord."],["Psalms",102,24,"He weakened my strength in the way; he shortened my days."],["Psalms",102,25,"I say, O my God, take me not away in the midst of my days: Thou whose years endure to all generations."],["Psalms",102,26,"Of old Thou hast laid the foundation of the earth: and the heavens are the work of Thy hands."],["Psalms",102,27,"They shall perish, but Thou shalt endure: yea, all of them shall grow old like a garment; Thou shalt change them like a cloak, and they will pass away:"],["Psalms",102,28,"but Thou art the same, and Thy years shall have no end."],["Psalms",102,29,"The children of Thy servants shall continue, and their seed shall be established before Thee."],["Psalms",103,1,"Of David. Bless the Lord, O my soul: and all that is within me bless his holy name."],["Psalms",103,2,"Bless the Lord, O my soul, and forget not all his benefits:"],["Psalms",103,3,"who forgives all thy iniquities; who heals all thy diseases;"],["Psalms",103,4,"who redeems thy life from the pit; who encircles thee with love and compassion;"],["Psalms",103,5,"who satisfies thy old age with good; so that thy youth is renewed like the eagle's."],["Psalms",103,6,"The Lord executes righteousness, and judgment for all that are oppressed."],["Psalms",103,7,"He made known his ways to Moses, his acts to the children of Israel."],["Psalms",103,8,"The Lord is merciful and gracious, slow to anger, and plenteous in steadfast love."],["Psalms",103,9,"He will not always chide: neither will he keep his anger forever."],["Psalms",103,10,"He has not dealt with us after our sins; nor repaid us according to our iniquities."],["Psalms",103,11,"For as the heaven is high above the earth, so great is his steadfast love towards those who fear him."],["Psalms",103,12,"As far as the east is from the west, so far has he removed our transgressions from us."],["Psalms",103,13,"As a father pities his children, so the Lord pities those who fear him."],["Psalms",103,14,"For he knows our frame; he remembers that we are dust."],["Psalms",103,15,"As for man, his days are like grass: like a flower of the field, so he blooms."],["Psalms",103,16,"For the wind passes over it, and it is gone; and its place knows it no more."],["Psalms",103,17,"But the steadfast love of the Lord is from everlasting to everlasting upon those who fear him, and his righteousness to children's children;"],["Psalms",103,18,"to such as keep his covenant, and to those who remember his commandments to do them."],["Psalms",103,19,"The Lord has established his throne in the heavens; and his kingdom rules over all."],["Psalms",103,20,"Bless the Lord, you angels of his, you mighty ones who perform his bidding, hearkening to the voice of his word."],["Psalms",103,21,"Bless the Lord, all his hosts; you ministers of his, who do his pleasure."],["Psalms",103,22,"Bless the Lord, all his works in all places of his dominion. Bless the Lord, O my soul!"],["Psalms",104,1,"Bless the Lord, O my soul. O Lord my God Thou art very great, Thou art clothed with glory and majesty."],["Psalms",104,2,"Who covers himself with light as with a garment: who stretches out the heavens like a curtain:"],["Psalms",104,3,"who lays the beams of his chambers in the waters: who makes the clouds his chariot: who walks upon the wings of the wind:"],["Psalms",104,4,"who makes the winds his messengers; the flames of fire his ministers:"],["Psalms",104,5,"who laid the foundations of the earth, that it should not be removed forever."],["Psalms",104,6,"Thou didst cover it with the deep as with a garment: the waters stood above the mountains."],["Psalms",104,7,"At Thy rebuke they fled; at the voice of Thy thunder they hastened away;"],["Psalms",104,8,"they went up the mountains; they flowed down the valleys to the place which Thou didst found for them."],["Psalms",104,9,"Thou didst set a bound that they might not pass over; that they might not turn back to cover the earth."],["Psalms",104,10,"He sends the springs into the valleys; they flow between the hills:"],["Psalms",104,11,"they give drink to every wild beast: the wild asses quench their thirst."],["Psalms",104,12,"Beside them dwell the birds of the sky; from among the branches they sing."],["Psalms",104,13,"He waters the hills from his upper chambers: the earth is satisfied with the fruit of Thy works."],["Psalms",104,14,"He causes the grass to grow for the cattle, and plants for the service of man: that he may bring forth food out of the earth;"],["Psalms",104,15,"and wine that makes glad the heart of man; oil to brighten his face; and bread which sustains the heart of man."],["Psalms",104,16,"The trees of the Lord have their fill; the cedars of Lebanon, which he has planted;"],["Psalms",104,17,"where the birds make their nests: as for the stork, the cypress trees are her house."],["Psalms",104,18,"The high hills are a refuge for the wild goats; and the rocks for the badgers."],["Psalms",104,19,"He appointed the moon for seasons: the sun knows his going down."],["Psalms",104,20,"Thou makest darkness, and it is night; when all the beasts of the forest do creep forth."],["Psalms",104,21,"The young lions roar after their prey, and seek their food from God."],["Psalms",104,22,"The sun rises, they slink away, and lay them down in their dens."],["Psalms",104,23,"Man goes forth to his work and to his labour until the evening."],["Psalms",104,24,"O Lord, how manifold are Thy works! in wisdom hast Thou made them all: the earth is full of Thy creatures."],["Psalms",104,25,"So is this great and wide sea, wherein are creeping things innumerable, both small and great beasts."],["Psalms",104,26,"There go the ships: there are the dolphins, whom Thou hast made to play therein."],["Psalms",104,27,"These wait all upon Thee; that Thou mayst give them their food in due season."],["Psalms",104,28,"Thou givest it to them; they gather it: Thou openest Thy hand, they are filled with good."],["Psalms",104,29,"Thou hidest Thy face, they are troubled: Thou takest away their breath, they die, and return to their dust."],["Psalms",104,30,"Thou sendest forth Thy breath, they are created: and Thou renewest the face of the earth."],["Psalms",104,31,"May the glory of the Lord endure forever: let the Lord rejoice in his works."],["Psalms",104,32,"He looks on the earth, and it trembles: he touches the hills, and they smoke."],["Psalms",104,33,"I will sing to the Lord as long as I live: I will sing praise to my God while I have my being."],["Psalms",104,34,"My meditation of him shall be sweet: I will rejoice in the Lord."],["Psalms",104,35,"The sinners will be consumed out of the earth, and the wicked will be no more. Bless thou the Lord, O my soul. Hallelujah!"],["Psalms",105,1,"O Give thanks to the Lord; call upon his name: make known his deeds among the people."],["Psalms",105,2,"Sing to him, sing psalms to him: talk of all his wondrous works."],["Psalms",105,3,"Glory in his holy name: let the heart of those who seek the Lord rejoice."],["Psalms",105,4,"Seek the Lord, and his strength: seek his face continually."],["Psalms",105,5,"Remember his marvellous works that he has done; his wonders, and the judgments of his mouth;"],["Psalms",105,6,"O seed of Abraham his servant, you children of Jacob his chosen ones."],["Psalms",105,7,"He is the Lord our God: his judgments are over all the earth."],["Psalms",105,8,"He has remembered his covenant forever, the word which he commanded to a thousand generations;"],["Psalms",105,9,"which he made with Abraham, and his oath to Isaac;"],["Psalms",105,10,"and confirmed the same to Jacob for a law, and to Israel for an everlasting covenant:"],["Psalms",105,11,"saying, To thee I will give the land of Canaan, the lot of your inheritance:"],["Psalms",105,12,"when they were but a few men in number; of little account, and sojourners there:"],["Psalms",105,13,"when they went from one nation to another, from one kingdom to another people;"],["Psalms",105,14,"he suffered no man to do them wrong: but he reproved kings for their sakes; saying,"],["Psalms",105,15,"Touch not my anointed, and do my prophets no harm."],["Psalms",105,16,"Moreover he called for a famine upon the land: he broke every staff of bread."],["Psalms",105,17,"He sent a man before them; Joseph was sold for a servant:"],["Psalms",105,18,"whose foot they hurt with fetters: he was laid in iron:"],["Psalms",105,19,"until the time that his word came to pass: the word of the Lord had tested him."],["Psalms",105,20,"The king sent and loosed him: and the ruler of the people let him go free."],["Psalms",105,21,"He made him lord of his house, and ruler of all his substance:"],["Psalms",105,22,"to bind his princes at his pleasure; and teach his elders wisdom."],["Psalms",105,23,"So Israel came into Egypt; and Jacob sojourned in the land of Ham."],["Psalms",105,24,"And he increased his people greatly; and made them stronger than their enemies."],["Psalms",105,25,"He turned their heart to hate his people, to deal craftily with his servants."],["Psalms",105,26,"He sent Moses his servant; and Aaron whom he had chosen."],["Psalms",105,27,"They performed his signs among them, and wonders in the land of Ham."],["Psalms",105,28,"He sent darkness, and made it dark, and they did not rebel against his word."],["Psalms",105,29,"He turned their water into blood, and slew their fish."],["Psalms",105,30,"Their land swarmed with frogs, in the chambers of their kings."],["Psalms",105,31,"He spoke, and there came swarms of gnats, and lice in all their borders."],["Psalms",105,32,"He gave them hail for rain, and flaming fire in their land."],["Psalms",105,33,"He smote their vines also and their fig trees; and broke the trees of their country."],["Psalms",105,34,"He spoke, and the swarming locust came, and the hopping locust without number,"],["Psalms",105,35,"and they did eat up every plant in their land, and devoured the fruit of their ground."],["Psalms",105,36,"Then he smote all the firstborn in their land, the chief of all their strength."],["Psalms",105,37,"He brought them forth also with silver and gold: and there was not one who stumbled among their tribes."],["Psalms",105,38,"Egypt was glad when they departed: for the fear of them had fallen on them."],["Psalms",105,39,"He spread a cloud for a covering; and fire to give light in the night."],["Psalms",105,40,"They asked, and he brought quails, and satisfied them with bread from heaven."],["Psalms",105,41,"He opened the rock, and the water gushed out; it ran in the dry places like a river."],["Psalms",105,42,"For he remembered his holy promise to Abraham his servant."],["Psalms",105,43,"And he brought out his people with joy, and his chosen ones with gladness:"],["Psalms",105,44,"and gave them the lands of the nations: and they seized the labour of the peoples;"],["Psalms",105,45,"that they might observe his statutes, and keep his laws. Hallelujah!"],["Psalms",106,1,"Hallelujah; O give thanks to the Lord; for he is good: for his steadfast love endures for ever."],["Psalms",106,2,"Who can utter the mighty acts of the Lord? who can declare all his praise?"],["Psalms",106,3,"Happy are they who maintain justice, and do righteousness at all times."],["Psalms",106,4,"Remember me, O Lord, when Thou showest favour to Thy people: O visit me with Thy salvation;"],["Psalms",106,5,"that I may see the good of Thy chosen ones, that I may rejoice in the gladness of Thy nation, that I may glory with Thy inheritance."],["Psalms",106,6,"We have sinned with our fathers, we have committed iniquity, we have done wickedly."],["Psalms",106,7,"Our fathers in Egypt paid no heed to Thy wonders; they did not remember the multitude of Thy deeds of lovingkindness; and they rebelled against Thee at the Sea, at the Red Sea."],["Psalms",106,8,"But he saved them for his name's sake, that he might make known his mighty power."],["Psalms",106,9,"He rebuked the Red Sea also, and it was dried up: so he led them through the depths, as through the wilderness."],["Psalms",106,10,"And he saved them from the hand of him who hated them, and redeemed them from the hand of the enemy."],["Psalms",106,11,"And the waters covered their enemies: there was not one of them left."],["Psalms",106,12,"Then they believed his words; they sang his praise."],["Psalms",106,13,"They soon forgot his works; they did not wait for his counsel:"],["Psalms",106,14,"but lusted exceedingly in the wilderness, and tried God in the desert."],["Psalms",106,15,"And he gave them their request; but sent leanness into their soul."],["Psalms",106,16,"And they envied Moses in the camp, Aaron the Lord's holy one."],["Psalms",106,17,"The earth opened and swallowed up Dathan, and covered the company of Abiram."],["Psalms",106,18,"And a fire was kindled in their company; the flame burned up the wicked."],["Psalms",106,19,"They made a calf in Horeb, and worshipped a molten image."],["Psalms",106,20,"Thus they exchanged their glory for the likeness of an ox that eats grass!"],["Psalms",106,21,"They forgot God who had saved them, who had done great things in Egypt;"],["Psalms",106,22,"wondrous works in the land of Ham, and terrible things by the Red Sea."],["Psalms",106,23,"Therefore he said that he would destroy them. had not Moses his chosen one stood before him in the breach, to turn away his wrath, lest he should destroy them."],["Psalms",106,24,"Moreover, they despised the pleasant land, they believed not his word:"],["Psalms",106,25,"but murmured in their tents, and did not hearken to the voice of the Lord."],["Psalms",106,26,"Therefore he lifted up his hand against them, swearing to overthrow them in the wilderness:"],["Psalms",106,27,"to cast out their seed also among the nations, and to scatter them in the lands."],["Psalms",106,28,"Then they joined themselves to Baal-peor, and ate the sacrifices of the dead."],["Psalms",106,29,"Thus they provoked him to anger with their deeds: and the plague broke out upon them."],["Psalms",106,30,"Then stood up Phinehas, and executed judgment: and so the plague was stayed."],["Psalms",106,31,"And that was counted to him for righteousness to all generations for evermore."],["Psalms",106,32,"And they angered him at the waters of Meribah, so that it went ill with Moses for their sakes:"],["Psalms",106,33,"because they angered his spirit, so that he spoke rashly with his lips."],["Psalms",106,34,"They did not destroy the nations, concerning whom the Lord commanded them:"],["Psalms",106,35,"but were mingled among the nations, and learned their works:"],["Psalms",106,36,"and they served their idols, which became a snare to them."],["Psalms",106,37,"And they sacrificed their sons and their daughters to idols,"],["Psalms",106,38,"and shed innocent blood, the blood of their sons and of their daughters, whom they sacrificed to the idols of Canaan: and the land was polluted with blood."],["Psalms",106,39,"Thus they were defiled with their own works, and went astray in their doings."],["Psalms",106,40,"Therefore was the wrath of the Lord kindled against his people, and he abhorred his inheritance."],["Psalms",106,41,"So he gave them into the hand of the nations; and they that hated them ruled over them."],["Psalms",106,42,"Their enemies also oppressed them, and they were brought into subjection under their hand."],["Psalms",106,43,"Many times did he deliver them; but they were rebellious in their counsel, and were brought low through their iniquity."],["Psalms",106,44,"Nevertheless he regarded their affliction, when he heard their cry:"],["Psalms",106,45,"and he remembered for them his covenant, and relented according to the abundance of his steadfast love."],["Psalms",106,46,"Moreover he caused them to be pitied by all their captors."],["Psalms",106,47,"Save us, O Lord our God, and gather us from among the nations, to give thanks to Thy holy name, and to triumph in Thy praise."],["Psalms",106,48,"Blessed be the Lord God of Israel from everlasting to everlasting: and let all the people say, Amen. Hallelujah!"],["Psalms",107,1,"O Give thanks to the Lord, for he is good: for his steadfast love endures for ever."],["Psalms",107,2,"Let the redeemed of the Lord say so, whom he has redeemed from the hand of the enemy;"],["Psalms",107,3,"and gathered them out of the lands, from the east, and from the west, from the north, and from the south."],["Psalms",107,4,"They wandered in the wilderness in a desert way; they found no city to dwell in."],["Psalms",107,5,"Hungry and thirsty, their soul fainted in them."],["Psalms",107,6,"Then they cried to the Lord in their trouble; he delivered them out of their distresses."],["Psalms",107,7,"And he led them forth by the right way, that they might go to a city of habitation."],["Psalms",107,8,"Let them praise the Lord for his steadfast love, and for his wonderful works to the children of men!"],["Psalms",107,9,"For he has satisfied the longing soul, and filled the hungry soul with goodness."],["Psalms",107,10,"Such as sat in darkness and in the shadow of death, bound in affliction and iron;"],["Psalms",107,11,"because they had rebelled against the words of God, and rejected the counsel of the most High:"],["Psalms",107,12,"so that he brought down their heart with labour; they fell down, and there was none to help."],["Psalms",107,13,"Then they cried to the Lord in their trouble, and he saved them out of their distresses."],["Psalms",107,14,"He brought them out of darkness and the shadow of death, and broke their bands asunder."],["Psalms",107,15,"Let them praise the Lord for his steadfast love, and for his wonderful works to the children of men!"],["Psalms",107,16,"For he has broken the gates of brass, and cut the bars of iron asunder."],["Psalms",107,17,"The foolish were afflicted on account of their sinful way, and their iniquities."],["Psalms",107,18,"Their soul abhorred all manner of food; for they came near the gates of death."],["Psalms",107,19,"Then they cried to the Lord in their trouble, and he saved them out of their distresses."],["Psalms",107,20,"He sends his word, and heals them, and delivers them from their destructions."],["Psalms",107,21,"Let them praise the Lord for his steadfast love, and for his wonderful works to the children of men!"],["Psalms",107,22,"And let them sacrifice the sacrifices of thanksgiving, and declare his works with rejoicing."],["Psalms",107,23,"They that go down to the sea in ships, that do business in great waters;"],["Psalms",107,24,"these saw the works of the Lord, and his wonders in the deep."],["Psalms",107,25,"For he commanded, and raised the stormy wind, which lifted up the waves thereof."],["Psalms",107,26,"They mount up to the sky, they go down again to the depths: their soul is melted away because of trouble."],["Psalms",107,27,"They reel to and fro, and stagger like a drunken man, and are at their wits' end."],["Psalms",107,28,"Then they cry to the Lord in their trouble, and he brings them out of their distresses."],["Psalms",107,29,"He makes the storm a calm, so that the waves thereof are still."],["Psalms",107,30,"Then are they glad because they are quiet; and he brings them to their desired haven."],["Psalms",107,31,"Let them praise the Lord for his steadfast love, and for his wonderful works to the children of men!"],["Psalms",107,32,"Let them exalt him also in the congregation of the people, and praise him in the assembly of the elders."],["Psalms",107,33,"He turns rivers into a wilderness, and watersprings into dry ground;"],["Psalms",107,34,"a fruitful land into barrenness, because of wickedness of those who dwell therein."],["Psalms",107,35,"He turned the wilderness into a pool of water, and dry ground into watersprings."],["Psalms",107,36,"And there he makes the hungry to dwell, and they establish a city for habitation;"],["Psalms",107,37,"and sow fields, and plant vineyards, which yield fruits of increase."],["Psalms",107,38,"He blesses them also, so that they are multiplied greatly; and does not let their cattle decrease."],["Psalms",107,39,"When they are diminished and brought low through oppression, affliction, and sorrow:"],["Psalms",107,40,"he pours contempt upon nobles, and causes them to wander in the wilderness, where there is no way:"],["Psalms",107,41,"yet he sets the poor on high from affliction, and makes his families like a flock."],["Psalms",107,42,"The righteous shall see it, and rejoice: and all iniquity shall stop her mouth."],["Psalms",107,43,"Whoever is wise, let them consider these things, and let them observe the loving acts of the Lord."],["Psalms",108,1,"A Poem, A Psalm of David."],["Psalms",108,2,"My heart is firm, O God; I will sing, I will give praise; my glory likewise."],["Psalms",108,3,"Awake the harp and the lyre: I will awaken the dawn."],["Psalms",108,4,"I will praise Thee, O Lord, among the peoples: and I will sing praises to Thee among the nations."],["Psalms",108,5,"For Thy steadfast love is great above the heavens: and Thy truth reaches the clouds."],["Psalms",108,6,"Be Thou exalted, O God, above the heavens: and Thy glory above all the earth;"],["Psalms",108,7,"that Thy beloved ones may be delivered: save with Thy right hand, and answer me."],["Psalms",108,8,"God has spoken in his holiness; I will rejoice, I will divide Shechem, and measure out the valley of Succoth."],["Psalms",108,9,"Gilead is mine; Manasseh is mine; Ephraim also is the strength of my head; Judah is my sceptre;"],["Psalms",108,10,"Moab is my washpot; over Edom will I cast my shoe; over Philistia I will cry in triumph."],["Psalms",108,11,"Who will bring me into the strong city? who will lead me to Edom?"],["Psalms",108,12,"Hast Thou not rejected us, O God? so that Thou goest not forth, O God, with our hosts."],["Psalms",108,13,"Give us help against the foe: for vain is the help of man."],["Psalms",108,14,"Through God we shall do valiantly: for he it is who will tread down our enemies."],["Psalms",109,1,"To the chief Musician, A Psalm of David. Keep not silent, O God of my praise;"],["Psalms",109,2,"for the mouth of the wicked and the mouth of the deceitful are opened against me: they have spoken against me with a lying tongue."],["Psalms",109,3,"For they have compassed me about with words of hatred; and fought against me without a cause."],["Psalms",109,4,"In return for my love they are my accusers; whilst I have nothing but prayer."],["Psalms",109,5,"And they have repaid me evil for good, and hatred for my love, saying:"],["Psalms",109,6,"Set a wicked man over him: and let an adversary stand at his right hand."],["Psalms",109,7,"When he shall be judged, let him be condemned: and let his prayer be turned into sin."],["Psalms",109,8,"Let his days be few; and let another take his possessions."],["Psalms",109,9,"Let his children be fatherless, and his wife a widow."],["Psalms",109,10,"Let his children be vagabonds, and beg: let them seek their bread also out of their desolate places."],["Psalms",109,11,"Let the creditor seize everything that he has, and let strangers spoil his labour."],["Psalms",109,12,"Let there be none to extend kindness to him: nor let there be any to favour his fatherless children."],["Psalms",109,13,"Let his posterity be cut off; and in the generation following let their name be blotted out."],["Psalms",109,14,"May the iniquity of his fathers be remembered by the Lord; and let not the sin of his mother be blotted out."],["Psalms",109,15,"Let them be before the Lord continually, that he may cut off the memory of them from the earth."],["Psalms",109,16,"Because he remembered not to show kindness, but pursued the poor and needy man, and the brokenhearted to their death."],["Psalms",109,17,"For he loved cursing, and it came to him: and he delighted not in blessing, and it was far from him."],["Psalms",109,18,"And he clothed himself with cursing like his garment, and it came into his bowels like water, and like oil into his bones."],["Psalms",109,19,"Let it be to him as the garment which he puts on, and for the girdle wherewith he is girded continually."],["Psalms",109,20,"This is what my adversaries seek to obtain from the Lord, and they who speak evil against my soul."],["Psalms",109,21,"But do Thou for me, O God the Lord, for Thy name's sake: because Thy steadfast love is good, deliver Thou me."],["Psalms",109,22,"For I am poor and needy, and my heart is wounded within me."],["Psalms",109,23,"I am gone like the shadow at evening: I am shaken off like the locust."],["Psalms",109,24,"My knees totter through fasting; and my flesh fails of fatness."],["Psalms",109,25,"I have become a taunt to them: when they see me they shake their heads."],["Psalms",109,26,"Help me, O Lord my God: O save me according to Thy steadfast love:"],["Psalms",109,27,"that they may know that this is Thy hand; that Thou, Lord, hast done it."],["Psalms",109,28,"Let them curse, but bless Thou: when they arise, let them be ashamed; but let Thy servant rejoice."],["Psalms",109,29,"Let my adversaries be clothed with shame, and let them cover themselves with their own confusion, as with a robe."],["Psalms",109,30,"I will greatly praise the Lord with my mouth; yea, I will praise him among the multitude."],["Psalms",109,31,"For he stands at the right hand of the poor, to save him from those who would condemn him to death."],["Psalms",110,1,"A Psalm of David. The Lord says to my master, Sit thou at my right hand, until I make thy enemies thy footstool."],["Psalms",110,2,"The Lord shall send thy mighty sceptre out of Zion: rule in the midst of thy enemies."],["Psalms",110,3,"Thy people offered themselves willingly in the majesty of their holiness, on the day of thy battle; when still the dew of thy youth was upon thee, fresh from the womb of dawn."],["Psalms",110,4,"The Lord has sworn, and will not change his mind, Thou shalt be a priest forever, after the manner of Melchizedek."],["Psalms",110,5,"The Lord is at thy right hand, he crushes kings on the day of his wrath."],["Psalms",110,6,"He judges among the nations: their land is full of dead bodies; he will shatter heads over many countries."],["Psalms",110,7,"He will drink of the brook in the way: therefore will he lift up the head."],["Psalms",111,1,"Hallelujah! I will praise the Lord with my whole heart, in the assembly of the upright, and in the congregation."],["Psalms",111,2,"The works of the Lord are great, sought out by all who love them."],["Psalms",111,3,"His work is honourable and glorious: and his righteousness endures for ever."],["Psalms",111,4,"He has made his wonderful works to be remembered: the Lord is gracious and full of compassion."],["Psalms",111,5,"He has given food to those who fear him: he will ever be mindful of his covenant."],["Psalms",111,6,"He has declared to his people the power of his works, that he may give them the heritage of the nations."],["Psalms",111,7,"The works of his hands are truth and justice; all his commandments are sure."],["Psalms",111,8,"They stand fast for ever and ever, done in truth and uprightness."],["Psalms",111,9,"He sent redemption to his people: he has commanded his covenant forever: holy and reverend is his name."],["Psalms",111,10,"The fear of the Lord is the beginning of wisdom: a good understanding have all they who do his commandments: his praise endures forever."],["Psalms",112,1,"Hallelujah! Happy is the man who fears the Lord, who delights greatly in his commandments."],["Psalms",112,2,"His seed shall be mighty upon earth: the generation of the upright shall be blessed."],["Psalms",112,3,"Wealth and riches shall be in his house: and his righteousness endures for ever."],["Psalms",112,4,"Light rises in the darkness for the upright: he is gracious, and full of compassion, and just."],["Psalms",112,5,"A good man lends with a good grace: he conducts his affairs justly."],["Psalms",112,6,"Surely he shall never be moved: the righteous shall be in everlasting remembrance."],["Psalms",112,7,"He shall not be afraid of evil tidings: his heart is firm, trusting in the Lord."],["Psalms",112,8,"His heart is established, he shall not be afraid, until he gaze upon his enemies."],["Psalms",112,9,"He has distributed freely, he has given to the poor; his righteousness endures for ever; his horn shall be exalted with honour."],["Psalms",112,10,"The wicked man shall see it, and be grieved; he shall gnash his teeth, and melt away: the desire of the wicked shall come to nought."],["Psalms",113,1,"Hallelujah! Give praise, O servants of the Lord, praise the name of the Lord."],["Psalms",113,2,"Blessed be the name of the Lord from this time forth and for evermore."],["Psalms",113,3,"From the rising of the sun to its setting, the Lord's name is to be praised."],["Psalms",113,4,"The Lord is high above all nations, and his glory is above the heavens."],["Psalms",113,5,"Who is like the Lord our God, who is enthroned on high,"],["Psalms",113,6,"and yet looks far down to behold the things that are in heaven, and on the earth!"],["Psalms",113,7,"He raises up the poor out of the dust, and lifts the needy out of the ashheap;"],["Psalms",113,8,"that he may set him with nobles, with the nobles of his people."],["Psalms",113,9,"He makes the barren woman to keep house, and be a joyful mother of children. Hallelujah!"],["Psalms",114,1,"When Israel went out of Egypt, the house of Jacob from a people of strange language;"],["Psalms",114,2,"Judah became his sanctuary, and Israel his dominion."],["Psalms",114,3,"The sea saw it, and fled: the Jordan was driven back."],["Psalms",114,4,"The mountains skipped like rams, the little hills like young sheep."],["Psalms",114,5,"What ails thee, O thou sea, that thou fleest? thou Jordan, that thou art driven back?"],["Psalms",114,6,"You mountains, that you skip like rams; and you little hills, like lambs?"],["Psalms",114,7,"Tremble, thou earth, at the presence of the Lord, at the presence of the God of Jacob;"],["Psalms",114,8,"who turned the rock into a pool of water, the flint into a fountain of waters."],["Psalms",115,1,"Not to us, O Lord, not to us, but to Thy name give glory, for Thy steadfast love, and for Thy truth."],["Psalms",115,2,"Why should the nations say, Where is now their God?"],["Psalms",115,3,"But our God is in the heavens: he has done whatever he has pleased."],["Psalms",115,4,"Their idols are silver and gold, the work of men's hands."],["Psalms",115,5,"They have mouths, but they cannot speak: eyes have they, but they cannot see:"],["Psalms",115,6,"they have ears, but they cannot hear: noses have they, but they cannot smell:"],["Psalms",115,7,"they have hands, but they cannot feel: feet have they, but they cannot walk: nor can they speak through their throat."],["Psalms",115,8,"They who make them are like them; so is everyone who trusts in them."],["Psalms",115,9,"O Israel, trust in the Lord: he is their help and their shield."],["Psalms",115,10,"O house of Aaron, trust in the Lord: he is their help and their shield."],["Psalms",115,11,"You who fear the Lord, trust in the Lord: he is their help and their shield."],["Psalms",115,12,"The Lord has been mindful of us: he will bless us; he will bless the house of Israel; he will bless the house of Aaron."],["Psalms",115,13,"He will bless those who fear the Lord, both small and great."],["Psalms",115,14,"May the Lord increase you more and more, you and your children."],["Psalms",115,15,"May you be blessed of the Lord who made heaven and earth."],["Psalms",115,16,"The heavens are the heavens of the Lord: but he has given the earth to the children of men."],["Psalms",115,17,"The dead cannot praise the Lord, nor can any who go down into silence."],["Psalms",115,18,"But we will bless the Lord from this time forth and for evermore. Hallelujah!"],["Psalms",116,1,"I love the Lord who hears my voice and my supplications."],["Psalms",116,2,"Because he has inclined his ear to me, therefore I will call upon him as long as I live."],["Psalms",116,3,"The cords of death surrounded me, and the pains of Sheol seized upon me: I found trouble and sorrow."],["Psalms",116,4,"Then I called upon the name of the Lord; O Lord, I beseech Thee, deliver my soul."],["Psalms",116,5,"Gracious is the Lord, and just; and our God is merciful."],["Psalms",116,6,"The Lord preserves the simple: I was brought low, and he saved me."],["Psalms",116,7,"Return to thy rest, O my soul; for the Lord has dealt bountifully with thee."],["Psalms",116,8,"For Thou hast delivered my soul from death, my eyes from tears, and my feet from falling."],["Psalms",116,9,"I will walk before the Lord in the land of the living."],["Psalms",116,10,"I kept faith even when I said, I am greatly afflicted."],["Psalms",116,11,"I said in my haste, Every man is false."],["Psalms",116,12,"How can I repay the Lord for all his benefits toward me?"],["Psalms",116,13,"I will raise the cup of salvation, and call upon the name of the Lord."],["Psalms",116,14,"I will pay my vows to the Lord now in the presence of all his people."],["Psalms",116,15,"Precious in the sight of the Lord is the death of his pious ones."],["Psalms",116,16,"O Lord, truly I am Thy servant; I am Thy servant, the son of Thy handmaid: Thou hast loosed my bonds."],["Psalms",116,17,"I will offer to Thee the sacrifice of thanksgiving, and I will call upon the name of the Lord."],["Psalms",116,18,"I will pay my vows to the Lord in the presence of all his people,"],["Psalms",116,19,"in the courts of the Lord's house, in the midst of thee, O Jerusalem. Hallelujah!"],["Psalms",117,1,"O Praise the Lord, all you nations: praise him all you peoples."],["Psalms",117,2,"For his love for us is great: and the truth of the Lord endures for ever. Hallelujah!"],["Psalms",118,1,"O Give thanks to the Lord; for he is good: for his steadfast love endures forever."],["Psalms",118,2,"Let Israel now say, that his steadfast love endures forever."],["Psalms",118,3,"Let the house of Aaron now say, that his steadfast love endures forever."],["Psalms",118,4,"Let those now who fear the Lord say, that his steadfast love endures forever."],["Psalms",118,5,"Out of my distress I called upon the Lord: the Lord answered me with liberation."],["Psalms",118,6,"The Lord is on my side; I will not fear: what can a man do to me?"],["Psalms",118,7,"The Lord takes my part with those who help me: therefore I shall gaze upon those who hate me."],["Psalms",118,8,"It is better to take refuge in the Lord than to put confidence in man."],["Psalms",118,9,"It is better to take refuge in the Lord than to trust in princes."],["Psalms",118,10,"All nations compassed me about: but in the name of the Lord I cut them off."],["Psalms",118,11,"They compassed me about; indeed, they surrounded me: but in the name of the Lord I cut them off."],["Psalms",118,12,"They compassed me about like bees; they are quenched like a fire of thorns: for in the name of the Lord I cut them off."],["Psalms",118,13,"Thou didst push me hard that I might fall: but the Lord helped me."],["Psalms",118,14,"The Lord is my strength and song, and is become my salvation."],["Psalms",118,15,"The voice of rejoicing and salvation is in the tents of the righteous: the right hand of the Lord does valiantly."],["Psalms",118,16,"The right hand of the Lord is exalted: the right hand of the Lord does valiantly."],["Psalms",118,17,"I shall not die, but live, and declare the works of the Lord."],["Psalms",118,18,"The Lord has chastised me severely: but he has not given me up to death."],["Psalms",118,19,"Open to me the gates of righteousness: I will go in to them, and I will praise the Lord:"],["Psalms",118,20,"this is the gate of the Lord, into which the righteous shall enter."],["Psalms",118,21,"I will give Thee thanks, for Thou hast answered me, and art become my salvation."],["Psalms",118,22,"The stone which the builders rejected has become the head stone of the corner."],["Psalms",118,23,"This is the Lord's doing; it is marvellous in our eyes."],["Psalms",118,24,"This is the day which the Lord has made; we will rejoice and be glad in it."],["Psalms",118,25,"Save us, O Lord, we pray Thee: we pray Thee, O Lord, prosper us."],["Psalms",118,26,"Blessed is he who comes in the name of the Lord: we have blessed you out of the house of the Lord."],["Psalms",118,27,"God is the Lord, who has shown us light: bind the sacrifice with cords, to the horns of the altar."],["Psalms",118,28,"Thou art my God, and I will praise Thee: my God, I will exalt Thee."],["Psalms",118,29,"O give thanks to the Lord; for he is good: for his steadfast love endures forever."],["Psalms",119,1,"Happy are those whose way is blameless, who walk in the law of the Lord."],["Psalms",119,2,"Happy are they who keep his testimonies and seek him with the whole heart."],["Psalms",119,3,"They also do no iniquity: they walk in his ways."],["Psalms",119,4,"Thou hast commanded Thy precepts to be kept diligently."],["Psalms",119,5,"O that my ways were directed to keep Thy statutes!"],["Psalms",119,6,"Then should I not be ashamed, when I observe all Thy commandments."],["Psalms",119,7,"I shall give Thee thanks with uprightness of heart, when I learn Thy righteous judgments."],["Psalms",119,8,"I will keep Thy statutes: O do not forsake me utterly."],["Psalms",119,9,"Wherewith shall a young man keep his way pure? by guarding it according to Thy word."],["Psalms",119,10,"With my whole heart I have sought Thee: O let me not wander from Thy commandments."],["Psalms",119,11,"Thy word have I hid in my heart, that I might not sin against Thee."],["Psalms",119,12,"Blessed art Thou, O Lord: teach me Thy statutes."],["Psalms",119,13,"With my lips I have declared all the judgments of Thy mouth."],["Psalms",119,14,"I have rejoiced in the way of Thy testimonies, as much as in all riches."],["Psalms",119,15,"I will meditate in Thy precepts, and observe Thy ways."],["Psalms",119,16,"I will delight myself in Thy statutes: I will not forget Thy word."],["Psalms",119,17,"Deal bountifully with Thy servant, that I may live, and keep Thy word."],["Psalms",119,18,"Open Thou my eyes, that I may behold wondrous things out of Thy law."],["Psalms",119,19,"I am a stranger on the earth: do not hide Thy commandments from me."],["Psalms",119,20,"My soul is consumed with the longing that it has to Thy judgments at all times."],["Psalms",119,21,"Thou hast rebuked the proud that are cursed, who wander from Thy commandments."],["Psalms",119,22,"Remove insult and contempt from me; for I have kept Thy testimonies."],["Psalms",119,23,"Princes also did sit and speak against me: but Thy servant did meditate on Thy statutes."],["Psalms",119,24,"Thy testimonies also are my delight; they are my counsellors."],["Psalms",119,25,"My soul cleaves to the dust: revive me according to Thy word."],["Psalms",119,26,"I have declared my ways, and Thou didst hear me: teach me Thy statutes."],["Psalms",119,27,"Make me to understand the way of Thy precepts: so I shall talk of Thy wondrous works."],["Psalms",119,28,"My soul melts away for heaviness: strengthen me according to Thy word."],["Psalms",119,29,"Remove from me the way of falsehood: and graciously bestow Thy law upon me."],["Psalms",119,30,"I have chosen the way of truth: Thy judgments have I laid before me."],["Psalms",119,31,"I have held fast to Thy testimonies: O Lord, put me not to shame."],["Psalms",119,32,"I will run the way of Thy commandments, for therein Thou dost enlarge my heart."],["Psalms",119,33,"Teach me, O Lord, the way of Thy statutes; and I shall keep it to the end."],["Psalms",119,34,"Give me understanding, and I shall keep Thy law; and I shall observe it with my whole heart."],["Psalms",119,35,"Make me to go in the path of Thy commandments; for therein do I delight."],["Psalms",119,36,"Incline my heart to Thy testimonies, and not to unjust gain."],["Psalms",119,37,"Turn away my eyes from beholding vanity; and give me life in Thy way."],["Psalms",119,38,"Confirm to Thy servant Thy word, which relates to the fear of Thee."],["Psalms",119,39,"Turn away my insult which I fear: for Thy judgments are good."],["Psalms",119,40,"Behold, I have longed after Thy precepts: give me life in Thy righteousness."],["Psalms",119,41,"And let Thy promises of steadfast love come to pass for me, O Lord; even Thy salvation; according to Thy word."],["Psalms",119,42,"So shall I have wherewith to answer him who insults me: for I trust in Thy word."],["Psalms",119,43,"And take not the word of truth utterly out of my mouth; for I have hoped in Thy judgments."],["Psalms",119,44,"So shall I keep Thy law continually for ever and ever."],["Psalms",119,45,"And I will walk at liberty: for I seek Thy precepts."],["Psalms",119,46,"I will also speak of Thy testimonies before kings, and will not be ashamed."],["Psalms",119,47,"And I will delight myself in Thy commandments, which I have loved."],["Psalms",119,48,"My hands also will I lift up to Thy commandments, which I have loved; and I will meditate on Thy statutes."],["Psalms",119,49,"Remember the word to Thy servant, whereby Thou hast given me hope."],["Psalms",119,50,"This is my comfort in my affliction: for Thy word has revived me."],["Psalms",119,51,"The proud have had me greatly in derision: yet I have not declined from Thy law."],["Psalms",119,52,"When I remembered thy judgments of old, O Lord, I took comfort."],["Psalms",119,53,"Horror has taken hold of me because of the wicked who forsake Thy law."],["Psalms",119,54,"Thy statutes have been my songs in the house of my pilgrimage."],["Psalms",119,55,"I have remembered Thy name, O Lord, in the night, and have kept Thy law."],["Psalms",119,56,"This was my lot, because I kept Thy precepts."],["Psalms",119,57,"The Lord is my portion: I have said that I would keep Thy words."],["Psalms",119,58,"I entreated Thy favour with my whole heart: be merciful to me according to Thy word."],["Psalms",119,59,"I thought on my ways, and turned my feet to Thy testimonies."],["Psalms",119,60,"I made haste, and delayed not to keep Thy commandments."],["Psalms",119,61,"Bands of wicked men have robbed me: but I have not forgotten Thy law."],["Psalms",119,62,"At midnight I will rise to give thanks to Thee because of Thy righteous judgments."],["Psalms",119,63,"I am a companion of all those who fear Thee, and of those who keep Thy precepts."],["Psalms",119,64,"The earth, O Lord, is full of Thy steadfast love: teach me Thy statutes."],["Psalms",119,65,"Thou hast dealt well with Thy servant, O Lord, according to Thy word."],["Psalms",119,66,"Teach me good discernment and knowledge: for I have believed Thy commandments."],["Psalms",119,67,"Before I was afflicted I went astray: but now I observe Thy word."],["Psalms",119,68,"Thou art good, and doest good; teach me Thy statutes."],["Psalms",119,69,"The proud have smeared me with a lie: but I will keep Thy precepts with my whole heart."],["Psalms",119,70,"Their heart is gross like fat, but I delight in Thy law."],["Psalms",119,71,"It is good for me that I have been afflicted; that I might learn Thy statutes."],["Psalms",119,72,"The law of Thy mouth is better to me than thousands of gold and silver."],["Psalms",119,73,"Thy hands have made me and fashioned me: give me understanding, that I may learn Thy commandments."],["Psalms",119,74,"They who fear Thee will see me and be glad, because I have hoped in Thy word."],["Psalms",119,75,"I know, O Lord, that Thy judgments are right, and that in faithfulness Thou has afflicted me."],["Psalms",119,76,"Let Thy steadfast love be my comfort, according to Thy word to Thy servant."],["Psalms",119,77,"Let Thy mercies come to me, that I may live: for Thy law is my delight."],["Psalms",119,78,"Let the proud be ashamed; for they dealt perversely with me with guile: but I will meditate on Thy precepts."],["Psalms",119,79,"Let those who fear Thee turn to me, and those who have known Thy testimonies."],["Psalms",119,80,"Let my heart be sound in Thy statutes; that I be not ashamed."],["Psalms",119,81,"My soul faints for Thy salvation: I hope in Thy word."],["Psalms",119,82,"My eyes fail with longing for Thy word, saying, When wilt Thou comfort me?"],["Psalms",119,83,"For I am become like a wineskin in the smoke; yet I do not forget Thy statutes."],["Psalms",119,84,"How many are the days of Thy servant? when wilt Thou execute judgment on those who persecute me?"],["Psalms",119,85,"The proud have dug pits for me, which are not according to Thy law."],["Psalms",119,86,"All Thy commandments are faithful: they persecute me wrongfully; help Thou me."],["Psalms",119,87,"They had almost consumed me upon earth; but I forsook not Thy precepts."],["Psalms",119,88,"In Thy steadfast love spare my life; so I shall keep the testimony of Thy mouth."],["Psalms",119,89,"For ever, O Lord; Thy word stands fast in the heavens."],["Psalms",119,90,"Thy faithfulness endures to all generations: Thou hast established the earth, and it stands firm."],["Psalms",119,91,"They continue this day according to Thy ordinances: for all are Thy servants."],["Psalms",119,92,"Unless Thy law had been my delights, I should have perished in my affliction."],["Psalms",119,93,"I will never forget Thy precepts: for with them Thou hast given me life."],["Psalms",119,94,"I am Thine, save me; for I have sought Thy precepts."],["Psalms",119,95,"The wicked have waited for me to destroy me: but I will consider Thy testimonies."],["Psalms",119,96,"I have seen an end of every purpose: but Thy commandment is exceedingly broad."],["Psalms",119,97,"O how I love Thy law! it is my meditation all the day."],["Psalms",119,98,"Thy commandments make me wiser than my enemies: for they are ever with me."],["Psalms",119,99,"I have more understanding than all my teachers: for Thy testimonies are my meditation."],["Psalms",119,100,"I understand more than the elders, because I keep Thy precepts."],["Psalms",119,101,"I have restrained my feet from every evil way, that I might keep Thy word."],["Psalms",119,102,"I have not departed from Thy judgments: for Thou hast taught me."],["Psalms",119,103,"How sweet are Thy words to my palate! sweeter than honey to my mouth!"],["Psalms",119,104,"Through Thy precepts I get understanding: therefore I hate every false way."],["Psalms",119,105,"Thy word is a lamp to my feet and a light to my path."],["Psalms",119,106,"I have sworn, and I will perform it, that I will keep Thy righteous judgments."],["Psalms",119,107,"I am afflicted very much: revive me, O Lord, according to Thy word."],["Psalms",119,108,"Accept I beseech Thee, the freewill offerings of my mouth, O Lord, and teach me Thy ordinances."],["Psalms",119,109,"My soul is continually in my hand: yet I have not forgotten Thy law."],["Psalms",119,110,"The wicked have laid a snare for me: yet I have not strayed from Thy precepts."],["Psalms",119,111,"Thy testimonies I have taken as a heritage for ever: for they are the rejoicing of my heart."],["Psalms",119,112,"I have inclined my heart to perform Thy statutes always, to the end."],["Psalms",119,113,"I hate men of vain thoughts: but Thy law I love."],["Psalms",119,114,"Thou art my hiding place and my shield: I hope in Thy word."],["Psalms",119,115,"Depart from me, you evildoers: for I will keep commandments of my God."],["Psalms",119,116,"Uphold me according to Thy word, that I may live: and let me not be ashamed of my hope."],["Psalms",119,117,"Hold me up, and I shall be safe: and I will watch Thy statutes continually,"],["Psalms",119,118,"Thou hast trodden down all those who stray from Thy statutes: for their deceit is vain."],["Psalms",119,119,"Thou puttest away all the wicked of the earth like dross: therefore I love Thy testimonies."],["Psalms",119,120,"My flesh shudders for fear of Thee; and I am afraid of Thy judgments."],["Psalms",119,121,"I have done justice and righteousness: leave me not to my oppressors."],["Psalms",119,122,"Be surety for Thy servant for good: let not the proud oppress me."],["Psalms",119,123,"My eyes fail with watching for Thy salvation, and for the word of Thy righteousness."],["Psalms",119,124,"Deal with Thy servant according to Thy steadfast love, and teach me Thy statutes."],["Psalms",119,125,"I am Thy servant; give me understanding, that I may know Thy testimonies."],["Psalms",119,126,"It is time to act for the Lord: they have made void Thy law."],["Psalms",119,127,"Therefore I love Thy commandments above gold; yea, above fine gold."],["Psalms",119,128,"Therefore I esteem all Thy precepts to be entirely right; and I have loathed every false way."],["Psalms",119,129,"Thy testimonies are wonderful: therefore my soul keeps them."],["Psalms",119,130,"The unfolding of Thy words gives light; it gives understanding to the simple."],["Psalms",119,131,"With open mouth I pant: because I long for Thy commandments."],["Psalms",119,132,"Look upon me, and be gracious unto me, as is Thy wont towards those who love Thy name."],["Psalms",119,133,"Order my steps in Thy word: and let not any iniquity have dominion over me."],["Psalms",119,134,"Deliver me from the oppression of man: and I will keep Thy precepts."],["Psalms",119,135,"Make Thy face to shine upon Thy servant; and teach me Thy statutes."],["Psalms",119,136,"Rivers of water run down from my eyes, because they do not keep Thy law."],["Psalms",119,137,"Righteous art Thou, O Lord and upright are Thy judgments."],["Psalms",119,138,"Thou hast commanded Thy testimonies in righteousness and in great faithfulness."],["Psalms",119,139,"My zeal consumes me, because my enemies have forgotten Thy words."],["Psalms",119,140,"Thy word is very pure: therefore Thy servant loves it."],["Psalms",119,141,"I am small and despised: yet I do not forget Thy precepts."],["Psalms",119,142,"Thy righteousness is an everlasting righteousness, and Thy law is truth."],["Psalms",119,143,"Trouble and anguish have taken hold of me: yet Thy commandments are my delights."],["Psalms",119,144,"Thy testimonies are righteous forever: give me understanding, and I shall live."],["Psalms",119,145,"I cry with my whole heart; answer me, O Lord: I will keep Thy statutes."],["Psalms",119,146,"I cry to Thee; save me, and I shall keep Thy testimonies."],["Psalms",119,147,"I rise before dawn, and I cry out: my hope is in Thy word."],["Psalms",119,148,"My eyes open before the night watches, that I may meditate on Thy saying."],["Psalms",119,149,"Hear my voice according to Thy steadfast love: O Lord, revive me according to Thy judgment."],["Psalms",119,150,"Those who follow after mischief draw near: they are far from Thy law."],["Psalms",119,151,"Thou art near, O Lord; and all Thy commandments are truth."],["Psalms",119,152,"Concerning Thy testimonies, I have known of old that Thou hast founded them forever."],["Psalms",119,153,"Consider my affliction, and deliver me: for I do not forget Thy law."],["Psalms",119,154,"Plead my cause, and deliver me: give me life according to Thy word."],["Psalms",119,155,"Salvation is far from the wicked; for they seek not Thy statutes."],["Psalms",119,156,"Great are Thy compassions, O Lord: give me life as is Thy wont."],["Psalms",119,157,"Many are my persecutors and my enemies; yet I do not decline from Thy testimonies."],["Psalms",119,158,"I behold transgressors, and I am grieved; because they keep not Thy saying,"],["Psalms",119,159,"Consider how I love Thy precepts: revive me, O Lord, according to Thy steadfast love."],["Psalms",119,160,"The sum of Thy word is truth: and every one of Thy righteous judgments endures for ever."],["Psalms",119,161,"Princes have persecuted me without cause: but my heart stands in awe of Thy word."],["Psalms",119,162,"I rejoice at Thy word, like one who finds great spoil."],["Psalms",119,163,"I hate and abhor lying: but Thy law I love."],["Psalms",119,164,"Seven times a day I praise Thee because of Thy righteous judgments."],["Psalms",119,165,"Great peace have they who love Thy law: and nothing can make them stumble."],["Psalms",119,166,"Lord, I have hoped for Thy salvation, and I have done Thy commandments."],["Psalms",119,167,"My soul has kept Thy testimonies; and I love them exceedingly."],["Psalms",119,168,"I have kept Thy precepts and Thy testimonies: for all my ways are before Thee."],["Psalms",119,169,"Let my cry come before Thee, O Lord: give me understanding according to Thy word."],["Psalms",119,170,"Let my supplication come before Thee: deliver me according to Thy word."],["Psalms",119,171,"My lips shall utter praise, for Thou hast taught me Thy statutes."],["Psalms",119,172,"My tongue shall sing of Thy word: for all Thy commandments are just."],["Psalms",119,173,"Let Thy hand help me; for I have chosen Thy precepts."],["Psalms",119,174,"I long for Thy salvation, O Lord; and Thy law is my delight."],["Psalms",119,175,"Let my soul live, and it shall praise Thee; and let Thy judgment help me."],["Psalms",119,176,"I have gone astray like a lost sheep; seek out Thy servant; for I do not forget Thy commandments."],["Psalms",120,1,"A Song of Degrees. In my distress I cried to the Lord, and he heard me."],["Psalms",120,2,"Deliver my soul, O Lord, from lying lips, from a deceitful tongue."],["Psalms",120,3,"What shall be given to thee? or what shall be done to thee, thou false tongue?"],["Psalms",120,4,"Sharp arrows of the mighty, with coals of the broom tree."],["Psalms",120,5,"Woe is me, that I sojourn in Mesech, that I dwell in the tents of Kedar!"],["Psalms",120,6,"My soul has long dwelt with haters of peace."],["Psalms",120,7,"I am a man of peace: but when I speak, they are for war."],["Psalms",121,1,"A Song of Degrees. I will lift up my eyes to the hills From whence comes my help?"],["Psalms",121,2,"My help comes from the Lord, who made heaven and earth."],["Psalms",121,3,"He will not suffer thy foot to be moved: he who keeps thee will not slumber."],["Psalms",121,4,"Behold, he who keeps Israel shall neither slumber nor sleep."],["Psalms",121,5,"The Lord is thy keeper: the Lord is thy shade upon thy right hand."],["Psalms",121,6,"The sun shall not smite thee by day, nor the moon by night."],["Psalms",121,7,"The Lord shall preserve thee from all evil: he shall preserve thy soul."],["Psalms",121,8,"The Lord shall preserve thy going out and thy coming in from this time forth, and for evermore."],["Psalms",122,1,"A Song of Degrees of David. I was glad when they said to me, Let us go into the house of the Lord:"],["Psalms",122,2,"when our feet stood within thy gates, O Jerusalem;"],["Psalms",122,3,"O Jerusalem, built as a city that is compact together:"],["Psalms",122,4,"there the tribes used to go up, the tribes of the Lord, an appointed practice for Israel, to give thanks to the name of the Lord."],["Psalms",122,5,"For there are set thrones of judgment, the thrones of the house of David."],["Psalms",122,6,"Pray for the peace of Jerusalem: they who love thee shall prosper:"],["Psalms",122,7,"peace be within thy walls, and prosperity within thy palaces."],["Psalms",122,8,"For my brethren and companions' sakes, I will now say, Peace be within thee."],["Psalms",122,9,"For the sake of the house of the Lord our God I will seek thy good."],["Psalms",123,1,"A Song of Degrees. To Thee I lift up my eyes, O Thou who dwellest in the heavens."],["Psalms",123,2,"Behold, as the eyes of servants look to the hand of their masters, and as the eyes of a maid to the hand of her mistress; so our eyes wait upon the Lord our God, until he shall be gracious to us."],["Psalms",123,3,"Be gracious to us, O Lord, be gracious to us: for we are overfilled with contempt."],["Psalms",123,4,"Our soul is overfilled with the scorn of those who are at ease, and with the contempt of the proud."],["Psalms",124,1,"A Song of Degrees of David. If not for the Lord who was with us, let Israel now say –"],["Psalms",124,2,"if not for the Lord who was with us, when men rose up against us:"],["Psalms",124,3,"then they would have swallowed us up alive, when their anger was kindled against us:"],["Psalms",124,4,"then the waters would have overwhelmed us, the stream would have gone over our soul:"],["Psalms",124,5,"then the proud waters would have gone over our soul."],["Psalms",124,6,"Blessed be the Lord, who has not given us as a prey to their teeth."],["Psalms",124,7,"Our soul is escaped like a bird out of the snare of the fowlers: the snare is broken, and we are escaped."],["Psalms",124,8,"Our help is in the name of the Lord, who made heaven and earth."],["Psalms",125,1,"A Song of Degrees. They who trust in the Lord shall be like mount Zion, which cannot be removed, but abides for ever."],["Psalms",125,2,"As the mountains are round about Jerusalem, so the Lord is round about his people from henceforth and forever."],["Psalms",125,3,"For the sceptre of wickedness shall not rest upon the share allotted to the righteous; lest the righteous put forth their hands to do wrong."],["Psalms",125,4,"Do good, O Lord, to those who are good, and to those who are upright in their hearts."],["Psalms",125,5,"As for such as turn aside to their crooked ways, the Lord shall lead them away with the workers of iniquity: but peace shall be upon Israel."],["Psalms",126,1,"A Song of Degrees. When the Lord brought back the captivity of Zion, we were like men in a dream."],["Psalms",126,2,"Then was our mouth filled with laughter, and our tongue with singing: then they said among the nations, The Lord has done great things for them."],["Psalms",126,3,"The Lord has done great things for us; we are glad."],["Psalms",126,4,"Bring back our captivity, O Lord, like the streams in the south."],["Psalms",126,5,"They who sow in tears shall reap in joy."],["Psalms",126,6,"He who goes weeping on his way, bearing a bag of seed, shall come back with a joyful shout, carrying his sheaves."],["Psalms",127,1,"A Song of Degrees for Solomon. Unless the Lord builds the house, they who build it labour in vain: unless the Lord keeps the city, the watchman stays awake in vain."],["Psalms",127,2,"It is vain for you to rise up early, to sit up late, to eat the bread of toil: for truly to his beloved he gives tranquillity."],["Psalms",127,3,"Lo, children are a heritage of the Lord: and the fruit of the womb is a reward."],["Psalms",127,4,"As arrows in the hand of a mighty man; so are the children of one's youth."],["Psalms",127,5,"Happy is the man that has his quiver full of them: they shall not be put to shame, but they shall speak with their enemies in the gate."],["Psalms",128,1,"A Song of Degrees. Happy is everyone who fears the Lord; who walks in his ways."],["Psalms",128,2,"For thou shalt eat the labour of thy hands: happy shalt thou be, and it shall be well with thee."],["Psalms",128,3,"Thy wife shall be like a fruitful vine in the recesses of thy house: thy children like olive plants round about thy table."],["Psalms",128,4,"Behold, thus shall the man be blessed who fears the Lord."],["Psalms",128,5,"The Lord shall bless thee out of Zion: and thou shalt see the good of Jerusalem all the days of thy life."],["Psalms",128,6,"And thou shalt see thy children's children, and peace upon Israel."],["Psalms",129,1,"A Song of Degrees. Many a time have they afflicted me from my youth, may Israel now say:"],["Psalms",129,2,"many a time have they afflicted me from my youth: yet they have not prevailed against me."],["Psalms",129,3,"The ploughers ploughed upon my back: they made long their furrows."],["Psalms",129,4,"The Lord is righteous: he has cut asunder the cord of the wicked."],["Psalms",129,5,"Let them be confounded and turned back, all who hate Zion."],["Psalms",129,6,"Let them be like the grass upon the housetops, which withers before it is plucked:"],["Psalms",129,7,"wherewith the mower fills not his hand; nor he who binds sheaves his bosom."],["Psalms",129,8,"Nor do they who go by say, The blessing of the Lord be upon you: we bless you in the name of the Lord."],["Psalms",130,1,"A Song of Degrees. Out of the depths I have cried to Thee, O Lord."],["Psalms",130,2,"Lord, hear my voice: let Thy ears be attentive to the voice of my supplications."],["Psalms",130,3,"If Thou, Lord, shouldst mark iniquities, O Lord, who could stand?"],["Psalms",130,4,"But there is forgiveness with Thee, that Thou mayst be feared."],["Psalms",130,5,"I wait for the Lord, my soul waits, and in his word I hope."],["Psalms",130,6,"My soul waits for the Lord more than they who watch for the morning: more than watchmen for the morning."],["Psalms",130,7,"Let Israel hope in the Lord: for with the Lord there is steadfast love, and with him is plenteous redemption."],["Psalms",130,8,"And he shall redeem Israel from all his iniquities."],["Psalms",131,1,"A Song of Degrees of David. Lord, my heart is not haughty, nor my eyes lofty: nor do I exercise myself in great matters, or in things too high for me."],["Psalms",131,2,"Surely I have stilled and quieted myself, like a weaned child beside his mother: my soul within me is like a weaned child."],["Psalms",131,3,"Let Israel hope in the Lord from henceforth and for ever."],["Psalms",132,1,"A Song of Degrees. Lord, remember to David's favour all his afflictions:"],["Psalms",132,2,"how he swore to the Lord, and vowed to the mighty God of Jacob:"],["Psalms",132,3,"Surely I will not come into the tabernacle of my house, nor go up into my bed;"],["Psalms",132,4,"I will not give sleep to my eyes, slumber to my eyelids,"],["Psalms",132,5,"until I find out a place for the Lord, a habitation for the mighty One of Jacob."],["Psalms",132,6,"Lo, we heard of it at Ephratah: we found it in the fields of the wood."],["Psalms",132,7,"We will go into his dwelling places: we will worship at his footstool."],["Psalms",132,8,"Arise, O Lord, to Thy resting place; Thou, and the ark of Thy strength."],["Psalms",132,9,"Let Thy priests be clothed with righteousness; and let Thy pious ones shout for joy."],["Psalms",132,10,"For Thy servant David's sake do not turn away the face of Thy anointed."],["Psalms",132,11,"The Lord has sworn in truth to David; he will not turn from it; One of the sons of thy body will I set upon thy throne."],["Psalms",132,12,"If thy children will keep my covenant and my Testimony that I shall teach them, their children shall also sit upon thy throne for evermore."],["Psalms",132,13,"For the Lord has chosen Zion: he has desired it for his habitation."],["Psalms",132,14,"This is my resting place forever: here will I dwell; for I have desired it."],["Psalms",132,15,"I will abundantly bless her provisions: I will satisfy her poor with bread."],["Psalms",132,16,"I will also clothe her priests with salvation: and her pious ones shall shout aloud for joy."],["Psalms",132,17,"There will I make the horn of David to shoot up: I have set up a lamp for my anointed."],["Psalms",132,18,"His enemies I will clothe with shame: but upon himself his crown will flourish."],["Psalms",133,1,"A Song of Degrees of David. Behold, how good and how pleasant it is for brothers to dwell together in unity!"],["Psalms",133,2,"It is like the precious ointment upon the head, running down upon the beard, the beard of Aaron: running down over the hem of his garments:"],["Psalms",133,3,"like the dew of Hermon descending upon the mountains of Zion: for there the Lord has commanded the blessing, even life for evermore."],["Psalms",134,1,"A Song of Degrees. Behold, bless the Lord, all you servants of the Lord, who stand by night in the house of the Lord."],["Psalms",134,2,"Lift up your hands in the sanctuary, and bless the Lord."],["Psalms",134,3,"May the Lord who made heaven and earth bless thee out of Zion."],["Psalms",135,1,"Hallelujah! Praise the name of the Lord; praise him, O servants of the Lord."],["Psalms",135,2,"You who stand in the house of the Lord, in the courts of the house of our God,"],["Psalms",135,3,"Hallelujah! for the Lord is good: sing praises to his name; for it is pleasant."],["Psalms",135,4,"For the Lord has chosen Jacob to himself, Israel for his peculiar possession."],["Psalms",135,5,"For I know that the Lord is great, and that our Lord is above all gods."],["Psalms",135,6,"Whatever the Lord wishes, he has done in heaven, and in earth, in the seas, and all deep places."],["Psalms",135,7,"He causes vapours to ascend from the ends of the earth; he makes lightnings for the rain; he brings the wind out of the treasuries."],["Psalms",135,8,"It was he who smote the firstborn of Egypt, both of man and beast;"],["Psalms",135,9,"who sent signs and wonders into the midst of thee, O Egypt, upon Pharaoh, and upon all his servants;"],["Psalms",135,10,"who smote great nations, and slew mighty kings;"],["Psalms",135,11,"Sihon king of the Amorite, and Og king of Bashan, and all the kingdoms of Canaan;"],["Psalms",135,12,"and gave their land for a heritage, a heritage to Israel his people."],["Psalms",135,13,"Thy name, O Lord, endures forever; and Thy renown, O Lord, throughout all generations."],["Psalms",135,14,"For the Lord will judge the cause of his people, and he will relent concerning his servants."],["Psalms",135,15,"The idols of the nations are silver and gold, the work of men's hands."],["Psalms",135,16,"They have mouths, but they cannot speak; eyes have they, but they cannot see;"],["Psalms",135,17,"they have ears, but they cannot hear; nor is there any breath in their mouths."],["Psalms",135,18,"May they who make them become like them; and everyone who trusts in them."],["Psalms",135,19,"Bless the Lord, O house of Israel: bless the Lord, O house of Aaron:"],["Psalms",135,20,"Bless the Lord, O house of Levi: you who fear the Lord, bless the Lord."],["Psalms",135,21,"Blessed be the Lord out of Zion, he who dwells at Jerusalem. Hallelujah!"],["Psalms",136,1,"O Give thanks to the Lord; for he is good: for his steadfast love endures forever."],["Psalms",136,2,"O give thanks to the God of gods: for his steadfast love endures forever."],["Psalms",136,3,"O give thanks to the Lord of lords: for his steadfast love endures forever."],["Psalms",136,4,"To him who alone does great wonders: for his steadfast love endures forever."],["Psalms",136,5,"To him who by understanding made the heavens: for his steadfast love endures forever."],["Psalms",136,6,"To him who stretched out the earth above the waters: for his steadfast love endures forever."],["Psalms",136,7,"To him who made great lights: for his steadfast love endures forever:"],["Psalms",136,8,"the sun to rule by day: for his steadfast love endures forever:"],["Psalms",136,9,"the moon and stars to rule by night: for his steadfast love endures forever."],["Psalms",136,10,"To him who smote Egypt in their firstborn: for his steadfast love endures forever:"],["Psalms",136,11,"and brought out Israel from among them: for his steadfast love endures forever:"],["Psalms",136,12,"with a strong hand, and with a stretched out arm: for his steadfast love endures forever."],["Psalms",136,13,"To him who divided the Red Sea asunder: for his steadfast love endures forever:"],["Psalms",136,14,"and made Israel pass through the midst of it: for his steadfast love endures forever:"],["Psalms",136,15,"but overthrew Pharaoh and his host in the Red Sea: for his steadfast love endures forever."],["Psalms",136,16,"To him who led his people through the wilderness: for his steadfast love endures forever."],["Psalms",136,17,"To him who smote great kings: for his steadfast love endures forever:"],["Psalms",136,18,"and slew mighty kings: for his steadfast love endures forever:"],["Psalms",136,19,"Sihon king of the Amorite: for his steadfast love endures forever:"],["Psalms",136,20,"and Og the king of Bashan: for his steadfast love endures forever:"],["Psalms",136,21,"and gave their land for a heritage: for his steadfast love endures forever:"],["Psalms",136,22,"a heritage to Israel his servant: for his steadfast love endures forever."],["Psalms",136,23,"Who remembered us in our low estate: for his steadfast love endures forever:"],["Psalms",136,24,"and has delivered us from our enemies: for his steadfast love endures forever."],["Psalms",136,25,"Who gives bread to all flesh: for his steadfast love endures forever."],["Psalms",136,26,"O give thanks to the God of heaven: for his steadfast love endures forever."],["Psalms",137,1,"By the rivers of Babylon, there we sat down, yea, we wept, when we remembered Zion."],["Psalms",137,2,"We hung our lyres upon the willows in its midst."],["Psalms",137,3,"For there they who carried us away captive asked us for a song; and they who spoiled us asked us for mirth, saying, Sing us one of the songs of Zion."],["Psalms",137,4,"How shall we sing the Lord's song in a foreign land?"],["Psalms",137,5,"If I forget thee, O Jerusalem, let my right hand forget her cunning."],["Psalms",137,6,"If I do not remember thee, let my tongue cleave to the roof of my mouth; if I do not set Jerusalem above my highest joy."],["Psalms",137,7,"Remember, O Lord, against the children of Edom the day of Jerusalem, when they said, Rase it, rase it, to its very foundations."],["Psalms",137,8,"O daughter of Babylon, marked for devastation; happy is he who shall repay thee thy recompense for what thou hast done to us."],["Psalms",137,9,"Happy is he who shall seize and dash thy little ones against the rock."],["Psalms",138,1,"Of David. I will praise Thee with my whole heart: before princes I will sing praise to Thee."],["Psalms",138,2,"I will bow down towards Thy holy temple, and praise Thy name for Thy steadfast love, and for Thy truth: for Thou hast magnified Thy word above all Thy name."],["Psalms",138,3,"In the day when I cried Thou didst answer me, and didst strengthen me with strength in my soul."],["Psalms",138,4,"All the kings of the earth shall give Thee thanks, O Lord, when they hear the words of Thy mouth."],["Psalms",138,5,"Yea, they shall sing of the ways of the Lord: for great is the glory of the Lord."],["Psalms",138,6,"Though the Lord be high, yet he takes note of the lowly: but the haughty he knows from afar."],["Psalms",138,7,"Though I walk in the midst of trouble, Thou wilt revive me: Thou shalt stretch out Thy hand against the wrath of my enemies, and Thy right hand shall save me."],["Psalms",138,8,"May the Lord accomplish his purpose concerning me: Thy steadfast love, O Lord, endures forever: do not forsake the works of Thy own hands."],["Psalms",139,1,"To the chief Musician, A Psalm of David. O Lord, Thou hast searched me, and known me."],["Psalms",139,2,"Thou knowst my sitting down and my rising up, Thou understandest my thought afar off."],["Psalms",139,3,"Thou hast measured my going and my lying down, and Thou art acquainted with all my ways."],["Psalms",139,4,"For no word is yet on my tongue, and lo, O Lord, Thou knowst it all."],["Psalms",139,5,"Thou hast beset me behind and before, and laid Thy hand upon me."],["Psalms",139,6,"Such knowledge is too wonderful for me; it is high, I cannot attain unto it."],["Psalms",139,7,"Where shall I go from Thy spirit? or where shall I flee from Thy presence?"],["Psalms",139,8,"If I ascend up into heaven, Thou art there: if I make my bed in Sheol, behold, Thou art there."],["Psalms",139,9,"If I take the wings of the morning, and dwell in the uttermost parts of the sea;"],["Psalms",139,10,"even there shall Thy hand lead me, and Thy right hand shall hold me."],["Psalms",139,11,"If I say, Surely only darkness shall cover me; and the light be night about me,"],["Psalms",139,12,"even the darkness is not dark for Thee, but the night shines like the day: the darkness and the light are both alike to Thee."],["Psalms",139,13,"For Thou hast formed my reins: Thou hast knit me together in my mother's womb."],["Psalms",139,14,"I will praise Thee; for I am fearfully and wonderfully made: marvellous are Thy works; and my soul knows that right well."],["Psalms",139,15,"My frame was not hidden from Thee, when I was made in secret, and curiously wrought in the lowest parts of the earth."],["Psalms",139,16,"Thy eyes did see my unshaped flesh; for in Thy book all things are written: the days also in which they are to be fashioned, and for it too there was one of them."],["Psalms",139,17,"How precious also are Thy thoughts to me, O God! how great is the sum of them!"],["Psalms",139,18,"If I should count them, they are more in number than the sand. When I awake, I am still with Thee."],["Psalms",139,19,"Surely Thou wilt slay the wicked, O God: depart from me therefore, you bloody men,"],["Psalms",139,20,"who speak against Thee wickedly, and Thy enemies, who take Thy name in vain."],["Psalms",139,21,"Do I not hate, O Lord, those who hate Thee? and do I not strive with those who rise up against Thee?"],["Psalms",139,22,"I hate them with the utmost hatred: I count them my enemies."],["Psalms",139,23,"Search me, O God, and know my heart: try me, and know my thoughts:"],["Psalms",139,24,"and see if there is any wicked way in me, and lead me in the way everlasting."],["Psalms",140,1,"To the chief Musician, A Psalm of David."],["Psalms",140,2,"Deliver me, O Lord, from the evil man: preserve me from the violent man;"],["Psalms",140,3,"who devise mischiefs in their heart; continually they stir up wars."],["Psalms",140,4,"They have sharpened their tongues like a serpent; a spider's venom is under their lips. (Selah.)"],["Psalms",140,5,"Keep me, O Lord, from the hands of the wicked; preserve me from the violent man: who have purposed to trip up my feet."],["Psalms",140,6,"The proud have hidden a snare for me, and cords; they have spread a net by the wayside; they have set traps for me. (Selah.)"],["Psalms",140,7,"I said to the Lord, Thou art my God: hear the voice of my supplications, O Lord."],["Psalms",140,8,"O God the Lord, the strength of my salvation, Thou hast screened my head in the day of battle;"],["Psalms",140,9,"grant not, O Lord, the desires of the wicked man: further not his wicked device; lest they exalt themselves. (Selah.)"],["Psalms",140,10,"As for the head of those who compass me about, let the mischief of their own lips cover them."],["Psalms",140,11,"Let burning coals fall upon them: let them be cast into the fire; into deep pits, so that they do not rise up again."],["Psalms",140,12,"Let not a slanderer be established in the earth: let evil hunt the violent man to his overthrow."],["Psalms",140,13,"I know that the Lord will maintain the cause of the afflicted, and the right of the poor."],["Psalms",140,14,"Surely the righteous shall give thanks to Thy name: the upright shall dwell in Thy presence."],["Psalms",141,1,"A Psalm of David. Lord, I cry to Thee: make haste to me; give ear to my voice, when I cry to Thee."],["Psalms",141,2,"Let my prayer be set forth before Thee like incense; and the lifting up of my hands like the evening sacrifice."],["Psalms",141,3,"Set a guard, O Lord, to my mouth; keep watch over the door of my lips."],["Psalms",141,4,"Incline not my heart to any evil thing, to practise wicked deeds with men who work iniquity: and let me not eat of their dainties."],["Psalms",141,5,"Let the righteous strike me in kindness: and let him rebuke me; it shall be as oil for my head: let not my head refuse it: but still shall my prayer be against their evil plight."],["Psalms",141,6,"When their judges are thrown down upon the rocks, then they will hear how sweet were my words."],["Psalms",141,7,"As when one cuts and breaks up wood on the earth, so are our bones strewn at the mouth of Sheol."],["Psalms",141,8,"But my eyes are towards Thee, O God the Lord: in Thee I seek refuge; do not pour away my life."],["Psalms",141,9,"Keep me from the snare which they have laid for me, and the traps of the workers of iniquity."],["Psalms",141,10,"Let the wicked fall together into their own nets, whilst I escape."],["Psalms",142,1,"A Maschil of David; A Prayer when he was in the cave."],["Psalms",142,2,"I cry to the Lord with my voice; with my voice I make my supplication to the Lord."],["Psalms",142,3,"I pour out my complaint before him; I declare my trouble before him."],["Psalms",142,4,"When my spirit faints within me, then Thou knowst my path. In the way wherein I walk they have hidden a snare for me."],["Psalms",142,5,"I look on my right hand, and behold, but there is no man that knows me: I have nowhere to flee; no man cares for my soul."],["Psalms",142,6,"I cried to Thee, O Lord: I said, Thou art my refuge and my portion in the land of the living."],["Psalms",142,7,"Attend to my cry; for I am brought very low: deliver me from my persecutors; for they are stronger than I."],["Psalms",142,8,"Bring my soul out of prison, that I may give thanks to Thy name: the righteous shall crown themselves in me; for Thou shalt deal bountifully with me."],["Psalms",143,1,"A Psalm of David. Hear my prayer, O Lord, give ear to my supplications: in Thy faithfulness answer me, in thy righteousness."],["Psalms",143,2,"And enter not into judgment with Thy servant: for in Thy sight shall no man living be justified."],["Psalms",143,3,"For the enemy has persecuted my soul; he has trodden my life down to the ground; he has made me to dwell in darkness, as those that have been long dead."],["Psalms",143,4,"Therefore my spirit faints within me; my heart within me is appalled."],["Psalms",143,5,"I remember the days of old; I meditate on all Thy works; I muse on the work of Thy hands."],["Psalms",143,6,"I stretch forth my hands to Thee: my soul thirsts after Thee, like a thirsty land. (Selah.)"],["Psalms",143,7,"Answer me speedily, O Lord: my spirit fails: do not hide Thy face from me, lest I be like those who go down into the pit."],["Psalms",143,8,"Cause me to hear Thy words of steadfast love in the morning; for in Thee do I trust: cause me to know the way in which I should walk; for I lift up my soul to Thee."],["Psalms",143,9,"Deliver me, O Lord, from my enemies: I flee to Thee to hide me."],["Psalms",143,10,"Teach me to do Thy will; for Thou art my God: let Thy good spirit lead me into a level land."],["Psalms",143,11,"Revive me, O Lord, for Thy name's sake: for Thy righteousness' sake bring my soul out of trouble."],["Psalms",143,12,"And in Thy mercy cut off my enemies, and destroy all those who afflict my soul: for I am Thy servant."],["Psalms",144,1,"Of David. Blessed be the Lord my rock, who teaches my hands to war, and my fingers to fight:"],["Psalms",144,2,"my gracious one, and my fortress; my high tower, and my deliverer; my shield, and he in whom I trust; who subdues my people under me."],["Psalms",144,3,"Lord, what is man, that Thou takest knowledge of him! or the son of man, that Thou makest account of him!"],["Psalms",144,4,"Man is like a breath: his days are like a shadow that passes away."],["Psalms",144,5,"Bow Thy heavens, O Lord, and come down: touch the mountains, that they may smoke."],["Psalms",144,6,"Cast forth lightning, and scatter them: shoot out Thy arrows, and destroy them."],["Psalms",144,7,"Send Thy hand from above; rescue me, and deliver me out of many waters, from the hand of strangers;"],["Psalms",144,8,"whose mouth speaks vanity, and their right hand is a right hand of falsehood."],["Psalms",144,9,"I will sing a new song to Thee, O God: upon a harp of ten strings I will sing praises to Thee."],["Psalms",144,10,"It is he who gives salvation to kings: who delivers David his servant from the hurtful sword."],["Psalms",144,11,"Rescue me, and deliver me from the hand of strangers, whose mouth speaks vanity, and their right hand is a right hand of falsehood."],["Psalms",144,12,"For our sons are as plants grown up in their youth; our daughters as corner stones, polished after the fashion of a palace:"],["Psalms",144,13,"our garners are full, affording all manner of store: our sheep bring forth thousands and ten thousands in our streets:"],["Psalms",144,14,"our oxen are heavy laden: there is no breach or migration: and there is no loud cry in our streets."],["Psalms",144,15,"Happy is that people, that is in such a case: happy is that people, whose God is the Lord."],["Psalms",145,1,"A Praise of David. I will extol Thee, my God, O king; and I will bless Thy name for ever and ever."],["Psalms",145,2,"Every day I will bless Thee; and I will praise Thy name for ever and ever."],["Psalms",145,3,"Great is the Lord, and greatly to be praised; and his greatness is unsearchable."],["Psalms",145,4,"One generation shall praise Thy works to another, and shall declare Thy mighty acts."],["Psalms",145,5,"I will speak of the glorious splendour of Thy majesty, and of Thy wondrous works."],["Psalms",145,6,"And men shall speak of the might of Thy terrible acts: and I will declare Thy greatness."],["Psalms",145,7,"They shall utter the fame of Thy great goodness, and shall sing of Thy righteousness."],["Psalms",145,8,"The Lord is gracious, and full of compassion; slow to anger, and of abundant love."],["Psalms",145,9,"The Lord is good to all: and his tender mercies are over all his works."],["Psalms",145,10,"All Thy works shall praise Thee, O Lord; and Thy pious ones shall bless Thee."],["Psalms",145,11,"They shall speak of the glory of Thy kingdom, and talk of Thy power;"],["Psalms",145,12,"to make known to the sons of men his mighty acts, and the glorious majesty of his kingdom."],["Psalms",145,13,"Thy kingdom is an everlasting kingdom, and Thy dominion endures throughout all generations."],["Psalms",145,14,"The Lord upholds all that fall, and raises up all those who are bowed down."],["Psalms",145,15,"The eyes of all wait upon Thee; and Thou givest them their food in due season."],["Psalms",145,16,"Thou openest Thy hand, and satisfiest the desire of every living thing."],["Psalms",145,17,"The Lord is righteous in all his ways, and gracious in all his works."],["Psalms",145,18,"The Lord is near to all those who call upon him, to all who call upon him in truth."],["Psalms",145,19,"He will fulfil the desire of those who fear him: he also will hear their cry, and will save them."],["Psalms",145,20,"The Lord preserves all those who love him: but all the wicked he will destroy."],["Psalms",145,21,"My mouth shall speak the praise of the Lord: and let all flesh bless his holy name for ever and ever."],["Psalms",146,1,"Hallelujah! Praise the Lord, O my soul."],["Psalms",146,2,"While I live I will praise the Lord: I will sing praises to my God while I have my being."],["Psalms",146,3,"Put not your trust in princes, nor in the son of man, in whom there is no help."],["Psalms",146,4,"His breath goes forth, he returns to his earth; in that very day his thoughts perish."],["Psalms",146,5,"Happy is he who has the God of Jacob for his help, whose hope is in the Lord his God:"],["Psalms",146,6,"who made heaven, and earth, the sea, and all that is in them: who keeps truth forever."],["Psalms",146,7,"Who executes judgment for the oppressed: who gives bread to the hungry. The Lord looses the prisoners:"],["Psalms",146,8,"the Lord opens the eyes of the blind: the Lord raises those who are bowed down: the Lord loves the righteous:"],["Psalms",146,9,"the Lord preserves the strangers; he relieves the fatherless and widow: but the way of the wicked he makes crooked."],["Psalms",146,10,"The Lord shall reign forever, thy God, O Zion, to all generations. Hallelujah!"],["Psalms",147,1,"Praise the Lord: for it is good to sing praises to our God; for it is pleasant; praise is comely."],["Psalms",147,2,"The Lord builds Jerusalem: he gathers together the outcasts of Israel."],["Psalms",147,3,"He heals the brokenhearted, and binds up their wounds."],["Psalms",147,4,"He counts the number of the stars; he calls them all by their names."],["Psalms",147,5,"Great is our Lord, and of great power: his understanding is infinite."],["Psalms",147,6,"The Lord upholds the humble: he casts the wicked down to the ground."],["Psalms",147,7,"Sing to the Lord with thanksgiving; sing praise upon the lyre to our God:"],["Psalms",147,8,"who covers the heaven with clouds, who prepares rain for the earth, who makes grass to grow upon the mountains."],["Psalms",147,9,"He gives to the beast its food, and to the young ravens which cry."],["Psalms",147,10,"He delights not in the strength of the horse: he takes no pleasure in the legs of a man."],["Psalms",147,11,"The Lord takes pleasure in those who fear him, in those who hope in his steadfast love."],["Psalms",147,12,"Praise the Lord, O Jerusalem; praise Thy God, O Zion."],["Psalms",147,13,"For he has strengthened the bars of thy gates; he has blessed thy children within thee."],["Psalms",147,14,"He makes peace in Thy borders, and fills thee with the finest of the wheat."],["Psalms",147,15,"He sends forth his commandment upon the earth: his word runs very swiftly."],["Psalms",147,16,"He gives snow like wool: he scatters the hoar frost like ashes."],["Psalms",147,17,"He casts forth his ice like morsels: who can stand before his cold?"],["Psalms",147,18,"He sends out his word, and melts them: he causes his wind to blow: they run as water."],["Psalms",147,19,"He declares his Word to Jacob, his statutes and his judgments to Israel."],["Psalms",147,20,"He has not dealt so with any other nation: and as for his ordinances they have not known them. Hallelujah!"],["Psalms",148,1,"Hallelujah! Praise the Lord from the heavens: praise him in the heights."],["Psalms",148,2,"Praise him, all his angels: praise him, all his hosts."],["Psalms",148,3,"Praise him, sun and moon: praise him, all you stars of light."],["Psalms",148,4,"Praise him, heavens of heavens, and you waters that are above the heavens."],["Psalms",148,5,"Let them praise the name of the Lord: for he gave command, and they were created."],["Psalms",148,6,"And he established them for ever and ever: he has made a decree which shall not pass."],["Psalms",148,7,"Praise the Lord from the earth, O monsters, and all deeps:"],["Psalms",148,8,"fire, and hail; snow, and vapours; stormy wind fulfilling his word:"],["Psalms",148,9,"mountains, and all hills; fruitful trees, and all cedars:"],["Psalms",148,10,"beasts, and all cattle; creeping things, and winged birds:"],["Psalms",148,11,"kings of the earth, and all peoples; princes, and all judges of the earth:"],["Psalms",148,12,"both young men, and girls; old men, and children:"],["Psalms",148,13,"let them praise the name of the Lord: for his name alone is exalted; his glory is above the earth and heaven."],["Psalms",148,14,"He also has exalted the horn of his people, a praise for all his pious ones; even for the children of Israel, a people near to him. Hallelujah!"],["Psalms",149,1,"Hallelujah! Sing to the Lord a new song, his praise is sounded in the congregation of the pious."],["Psalms",149,2,"Let Israel rejoice in him who made him: let the children of Zion be joyful in their King."],["Psalms",149,3,"Let them praise his name in the dance: let them sing praises to him with the timbrel and lyre."],["Psalms",149,4,"For the Lord takes pleasure in his people: he will beautify the humble with salvation."],["Psalms",149,5,"Let the pious be joyful in glory: let them sing aloud upon their beds."],["Psalms",149,6,"The high praises of God are in their mouth, and a two edged sword in their hand;"],["Psalms",149,7,"to execute vengeance upon the nations, chastisements upon the peoples;"],["Psalms",149,8,"to bind their kings with chains, and their nobles with fetters of iron;"],["Psalms",149,9,"to execute upon them the judgment written: it is an honour to all his pious ones. Hallelujah!"],["Psalms",150,1,"Hallelujah! Praise God in his sanctuary: praise him in the firmament of his power."],["Psalms",150,2,"Praise him for his mighty acts: praise him according to his exceeding greatness."],["Psalms",150,3,"Praise him with the sound of the shofar: praise him with the harp and lyre."],["Psalms",150,4,"Praise him with the timbrel and dance: praise him with stringed instruments and the pipe."],["Psalms",150,5,"Praise him upon sounding cymbals: praise him upon loud clashing cymbals."],["Psalms",150,6,"Let everything that has breath praise the Lord. Hallelujah!"]]);
